{"command":"rm -f out; cat > src/source.rs <<'EOF'
use std::fmt;
use std::rc::Rc;

pub type Bytes = Vec<u8>;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct SourcePos {
    pub source: Rc<String>,
    pub line: u32,
    pub column: u32,
}

impl SourcePos {
    pub fn new(source: Rc<String>, line: u32, column: u32) -> Self {
        Self { source, line, column }
    }
}

impl fmt::Display for SourcePos {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} (line {}, column {})", self.source, self.line, self.column)
    }
}

#[derive(Clone, Debug)]
pub struct ErrorItem {
    pub message: String,
    pub pos: Option<SourcePos>,
}

impl ErrorItem {
    pub fn with_pos(pos: SourcePos, message: impl Into<String>) -> Self {
        Self { message: message.into(), pos: Some(pos) }
    }
    pub fn without_pos(message: impl Into<String>) -> Self {
        Self { message: message.into(), pos: None }
    }
    pub fn format_main(&self) -> String {
        match &self.pos {
            Some(pos) => format!("Error: {} - {}\n", pos, self.message),
            None => format!("Error: {}\n", self.message),
        }
    }
}

pub fn bytes_to_lossy_string(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

pub fn byte_as_char(byte: u8) -> String {
    let mut s = String::new();
    s.push(byte as char);
    s
}

pub fn escape_debug_byte(byte: u8) -> String {
    (byte as char).escape_debug().collect()
}

// Escape the contents (without surrounding quotes) of a string/char literal,
// matching Rust's escape_debug applied after a lossy UTF-8 conversion.
pub fn escape_string_contents(bytes: &[u8]) -> String {
    let text = bytes_to_lossy_string(bytes);
    let mut out = String::new();
    for c in text.chars() {
        // char::escape_debug is close to the original behaviour, except that
