impl Value {
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "bool",
            Value::Int(_) => "int",
            Value::Float(_) => "float",
            Value::Char(_) => "char",
            Value::Str(_) => "string",
            Value::Array(_) => "array",
            Value::Dict(_) => "dict",
            Value::Function(_) => "function",
            Value::Error(_) => "error",
        }
    }
    pub fn new_array(items: Vec<Value>) -> Value { Value::Array(Arc::new(Mutex::new(items))) }
    pub fn new_dict() -> Value { Value::Dict(Arc::new(Mutex::new(HashMap::new()))) }
    pub fn dict_from_entries(entries: Vec<(Value, Value)>) -> Value {
        let map = Arc::new(Mutex::new(HashMap::new()));
        {
            let mut guard = map.lock().unwrap();
            for (k, v) in entries {
                let key = DictKey::from_value(&k);
                guard.insert(key, DictEntry { key: k, value: v });
            }
        }
        Value::Dict(map)
    }
    pub fn display(&self) -> String {
        match self {
            Value::Nil => "nil".to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Int(i) => i.to_string(),
            Value::Float(x) => format_float(*x),
            Value::Char(b) => {
                let mut s = String::new();
                s.push(*b as char);
                s
            }
            Value::Str(bytes) => format_string_literal(bytes),
            Value::Array(items) => {
                let items = items.lock().unwrap();
                if items.is_empty() {
                    "[ ]".to_string()
                } else {
                    let parts: Vec<String> = items.iter().map(|v| v.display()).collect();
                    format!("[ {} ]", parts.join(", "))
                }
            }
            Value::Dict(map) => {
                let map = map.lock().unwrap();
                if map.is_empty() {
                    "@[ ]".to_string()
                } else {
                    let parts: Vec<String> = map
                        .values()
                        .map(|entry| format!("{}: {}", entry.key.display(), entry.value.display()))
                        .collect();
                    format!("@[ {} ]", parts.join(", "))
                }
            }
            Value::Function(fun) => match &fun.kind {
                FunctionKind::User { display_pos, .. } => format!("function<{}>", display_pos),
                FunctionKind::Native { name, .. } => name.clone(),
            },
            Value::Error(err) => format!("error: {} ({})", format_string_literal(&err.description), err.cause.display()),
        }
    }
    // Conversion used by std.print/println.
    pub fn print_bytes(&self) -> Vec<u8> {
        match self {
            Value::Str(bytes) => bytes.clone(),
            Value::Char(b) => vec![*b],
            _ => self.display().into_bytes(),
        }
    }
    pub fn string_bytes_lossy(&self) -> Option<Vec<u8>> {
        match self {
            Value::Str(bytes) => Some(bytes.clone()),
            _ => None,
        }
    }
    pub fn expect_string(&self) -> Option<Vec<u8>> { self.string_bytes_lossy() }

    pub fn equals(&self, other: &Value) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Char(a), Value::Char(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Array(a), Value::Array(b)) => {
                if Arc::ptr_eq(a, b) { return true; }
                let av = a.lock().unwrap().clone();
                let bv = b.lock().unwrap().clone();
                av.len() == bv.len() && av.iter().zip(bv.iter()).all(|(x, y)| x.equals(y))
            }
            (Value::Dict(a), Value::Dict(b)) => {
                if Arc::ptr_eq(a, b) { return true; }
                let av: Vec<(Value, Value)> = {
                    let m = a.lock().unwrap();
                    m.values().map(|e| (e.key.clone(), e.value.clone())).collect()
                };
                let bm = b.lock().unwrap();
                if av.len() != bm.len() { return false; }
                for (k, v) in &av {
                    let key = DictKey::from_value(k);
                    match bm.get(&key) {
                        Some(entry) => { if !v.equals(&entry.value) { return false; } }
                        None => return false,
                    }
                }
                true
            }
            (Value::Function(a), Value::Function(b)) => Arc::ptr_eq(a, b),
            (Value::Error(a), Value::Error(b)) => {
                a.description == b.description && a.cause.equals(&b.cause)
            }
            _ => false,
        }
    }

    pub fn compare(&self, other: &Value) -> Ordering {
        let rank = |v: &Value| match v {
            Value::Nil => 0,
            Value::Bool(_) => 1,
            Value::Char(_) => 2,
            Value::Int(_) => 3,
            Value::Float(_) => 4,
            Value::Str(_) => 5,
            Value::Array(_) => 6,
            Value::Dict(_) => 7,
            Value::Function(_) => 8,
            Value::Error(_) => 9,
        };
        let ra = rank(self); let rb = rank(other);
        if ra != rb { return ra.cmp(&rb); }
        match (self, other) {
            (Value::Bool(a), Value::Bool(b)) => a.cmp(b),
            (Value::Char(a), Value::Char(b)) => a.cmp(b),
            (Value::Int(a), Value::Int(b)) => a.cmp(b),
            (Value::Float(a), Value::Float(b)) => {
                if a.is_nan() && b.is_nan() { Ordering::Equal }
                else if a.is_nan() { Ordering::Less }
                else if b.is_nan() { Ordering::Greater }
                else { a.partial_cmp(b).unwrap_or(Ordering::Equal) }
            }
            (Value::Str(a), Value::Str(b)) => a.cmp(b),
            (Value::Array(a), Value::Array(b)) => {
                let av = a.lock().unwrap().clone();
                let bv = b.lock().unwrap().clone();
                for (x, y) in av.iter().zip(bv.iter()) {
                    let ord = x.compare(y);
                    if ord != Ordering::Equal { return ord; }
                }
                av.len().cmp(&bv.len())
            }
            (Value::Dict(a), Value::Dict(b)) => {
                let mut av: Vec<(Value, Value)> = {
                    let m = a.lock().unwrap();
                    m.values().map(|e| (e.key.clone(), e.value.clone())).collect()
                };
                let mut bv: Vec<(Value, Value)> = {
                    let m = b.lock().unwrap();
                    m.values().map(|e| (e.key.clone(), e.value.clone())).collect()
                };
                av.sort_by(|x, y| x.0.compare(&y.0).then_with(|| x.1.compare(&y.1)));
                bv.sort_by(|x, y| x.0.compare(&y.0).then_with(|| x.1.compare(&y.1)));
                for ((kx, vx), (ky, vy)) in av.iter().zip(bv.iter()) {
                    let ord = kx.compare(ky).then_with(|| vx.compare(vy));
                    if ord != Ordering::Equal { return ord; }
                }
                av.len().cmp(&bv.len())
            }
            (Value::Function(a), Value::Function(b)) => a.id.cmp(&b.id),
            (Value::Error(a), Value::Error(b)) => {
                a.description.cmp(&b.description).then_with(|| a.cause.compare(&b.cause))
            }
            _ => Ordering::Equal,
        }
    }
}

pub fn format_float(x: f64) -> String {
    if x.is_nan() {
        "NaN".to_string()
    } else {
        // Rust's Debug formatting for f64 matches the original:
        // 3.0, 100000.0, 1e16, 1e-5, inf, -inf.
        format!("{:?}", x)
    }
}

// A hashable/equality snapshot of a Value used as a dictionary key.
#[derive(Clone, PartialEq)]
pub enum DictKey {
    Nil,
    Bool(bool),
    Int(i64),
    Float(u64),
    Char(u8),
    Str(Vec<u8>),
    Array(Vec<DictKey>),
    Dict(Vec<(DictKey, DictKey)>),
    Function(u64),
    Error(Vec<u8>, Box<DictKey>),
}

impl DictKey {
    pub fn from_value(v: &Value) -> DictKey {
        match v {
            Value::Nil => DictKey::Nil,
            Value::Bool(b) => DictKey::Bool(*b),
            Value::Int(i) => DictKey::Int(*i),
            Value::Float(x) => DictKey::Float(canonical_float_bits(*x)),
            Value::Char(b) => DictKey::Char(*b),
            Value::Str(s) => DictKey::Str(s.clone()),
            Value::Array(items) => {
                let items = items.lock().unwrap();
                DictKey::Array(items.iter().map(DictKey::from_value).collect())
            }
            Value::Dict(map) => {
                let map = map.lock().unwrap();
                let mut entries: Vec<(DictKey, DictKey)> = map
                    .values()
                    .map(|e| (DictKey::from_value(&e.key), DictKey::from_value(&e.value)))
                    .collect();
                entries.sort_by(|a, b| hash_of_key(&a.0).cmp(&hash_of_key(&b.0)).then_with(|| hash_of_key(&a.1).cmp(&hash_of_key(&b.1))));
                DictKey::Dict(entries)
            }
            Value::Function(fun) => DictKey::Function(fun.id),
            Value::Error(err) => DictKey::Error(err.description.clone(), Box::new(DictKey::from_value(&err.cause))),
        }
    }
}

fn canonical_float_bits(x: f64) -> u64 {
    if x.is_nan() {
        0x7ff8_0000_0000_0001
    } else if x == 0.0 {
        0
    } else {
        x.to_bits()
    }
}

pub fn hash_of_key(key: &DictKey) -> u64 {
    let mut h = std::collections::hash_map::DefaultHasher::new();
    key.hash(&mut h);
    h.finish()
}

impl Eq for DictKey {}
impl Hash for DictKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        match self {
            DictKey::Nil => 0u8.hash(state),
            DictKey::Bool(b) => { 1u8.hash(state); b.hash(state); }
            DictKey::Int(i) => { 3u8.hash(state); i.hash(state); }
            DictKey::Float(bits) => { 4u8.hash(state); bits.hash(state); }
            DictKey::Char(b) => { 2u8.hash(state); b.hash(state); }
            DictKey::Str(s) => { 5u8.hash(state); s.hash(state); }
            DictKey::Array(items) => {
                6u8.hash(state);
                for item in items { item.hash(state); }
            }
            DictKey::Dict(entries) => {
                7u8.hash(state);
                // Order-independent combination.
                let mut acc: u64 = 0;
                for (k, v) in entries {
                    let mut inner = std::collections::hash_map::DefaultHasher::new();
                    k.hash(&mut inner);
                    v.hash(&mut inner);
                    acc = acc.wrapping_add(inner.finish());
                }
                acc.hash(state);
                entries.len().hash(state);
            }
            DictKey::Function(id) => { 8u8.hash(state); id.hash(state); }
            DictKey::Error(desc, cause) => {
                9u8.hash(state);
                desc.hash(state);
                cause.hash(state);
            }
        }
    }
}

pub fn escape_contents(bytes: &[u8]) -> String { escape_string_contents(bytes) }
EOF
