        RExprKind::Function(idx) => format!("function({})", idx),
        RExprKind::If(if_expr) => {
            let mut out = format!("if {} then", print_rexpr_inline(&if_expr.cond));
            let then_text = print_rblock_inline(&if_expr.then_block);
            if !then_text.is_empty() { out.push(' '); out.push_str(&then_text); }
            if let Some(else_block) = &if_expr.else_block {
                let else_text = print_rblock_inline(else_block);
                if !else_text.is_empty() { out.push_str(" else "); out.push_str(&else_text); }
            }
            out.push_str(" end");
            out
        }
        RExprKind::Command(block) => print_command_block_r_inline(block),
        RExprKind::Unary(op, inner) => {
