}

pub fn print_program(block: &Block) -> String { print_block(block, 0) }

pub fn print_stmt(stmt: &Statement, indent: usize) -> String {
    match stmt {
        Statement::Let { name, init, .. } => {
            let value = init.as_ref().map(|e| print_expr_pretty(e, indent)).unwrap_or_else(|| "nil".to_string());
            format!("let {} = {}", String::from_utf8_lossy(name), value)
        }
        Statement::Assign { target, value, .. } => {
            format!("{} = {}", print_expr_inline(target), print_expr_pretty(value, indent))
        }
        Statement::Expr(expr) => print_expr_pretty(expr, indent),
        Statement::Return(expr, _) => match expr {
            Some(expr) => format!("return {}", print_expr_pretty(expr, indent)),
            None => "return".to_string(),
        },
        Statement::Break(_) => "break".to_string(),
        Statement::For { name, iter, body, .. } => {
            format!(
                "for {} in {} do\n{}\n{}end",
                String::from_utf8_lossy(name),
                print_expr_inline(iter),
                print_block(body, indent + 1),
                tabs(indent)
            )
        }
        Statement::While { cond, body, .. } => {
            format!(
                "while {} do\n{}\n{}end",
                print_expr_inline(cond),
                print_block(body, indent + 1),
                tabs(indent)
            )
        }
        Statement::IllFormed => "***ill-formed***".to_string(),
    }
}

fn print_block_inline(block: &Block) -> String {
    block.iter().map(|s| print_stmt_inline(s)).collect::<Vec<_>>().join("; ")
}

pub fn print_stmt_inline(stmt: &Statement) -> String {
    match stmt {
        Statement::Let { name, init, .. } => {
            let value = init.as_ref().map(|e| print_expr_inline(e)).unwrap_or_else(|| "nil".to_string());
            format!("let {} = {}", String::from_utf8_lossy(name), value)
        }
        Statement::Assign { target, value, .. } => {
            format!("{} = {}", print_expr_inline(target), print_expr_inline(value))
        }
        Statement::Expr(expr) => print_expr_inline(expr),
        Statement::Return(expr, _) => match expr {
            Some(expr) => format!("return {}", print_expr_inline(expr)),
            None => "return".to_string(),
        },
        Statement::Break(_) => "break".to_string(),
        Statement::For { name, iter, body, .. } => format!(
            "for {} in {} do {} end",
            String::from_utf8_lossy(name), print_expr_inline(iter), print_block_inline(body)
        ),
        Statement::While { cond, body, .. } => format!(
            "while {} do {} end",
            print_expr_inline(cond), print_block_inline(body)
        ),
        Statement::IllFormed => "***ill-formed***".to_string(),
    }
}

pub fn print_expr_pretty(expr: &Expr, indent: usize) -> String {
    match &expr.kind {
        ExprKind::Array(items) => {
            if items.is_empty() { return "[]".to_string(); }
            let inner = items
                .iter()
                .map(|item| format!("{}{}", tabs(indent + 1), print_expr_pretty(item, indent + 1)))
                .collect::<Vec<_>>()
                .join(",\n");
            format!("[\n{}\n{}]", inner, tabs(indent))
        }
        ExprKind::Dict(pairs) => {
            if pairs.is_empty() { return "@[]".to_string(); }
            let inner = pairs
                .iter()
                .map(|pair| format!("{}{}: {}", tabs(indent + 1), String::from_utf8_lossy(&pair.key), print_expr_pretty(&pair.value, indent + 1)))
                .collect::<Vec<_>>()
                .join(",\n");
            format!("@[\n{}\n{}]", inner, tabs(indent))
        }
        ExprKind::Function(fun) => {
            let params = fun.params.iter().map(|(n, _)| String::from_utf8_lossy(n).into_owned()).collect::<Vec<_>>().join(", ");
            format!(
                "function({})\n{}\n{}end",
                params,
                print_block(&fun.body, indent + 1),
                tabs(indent)
            )
        }
        ExprKind::If(if_expr) => print_if_pretty(if_expr, indent),
        ExprKind::Command(block) => print_command_block_pretty(block, indent),
        _ => print_expr_inline(expr),
    }
}

fn print_if_pretty(if_expr: &IfExpr, indent: usize) -> String {
    let mut out = format!("if {} then", print_expr_inline(&if_expr.cond));
    if !if_expr.then_block.is_empty() {
        out.push('\n');
        out.push_str(&print_block(&if_expr.then_block, indent + 1));
    }
    if let Some(else_block) = &if_expr.else_block {
        if !else_block.is_empty() {
            out.push('\n');
            out.push_str(&tabs(indent));
            out.push_str("else\n");
            out.push_str(&print_block(else_block, indent + 1));
        }
    }
    out.push('\n');
    out.push_str(&tabs(indent));
    out.push_str("end");
    out
}

pub fn print_expr_inline(expr: &Expr) -> String {
    match &expr.kind {
        ExprKind::Nil => "nil".to_string(),
        ExprKind::Bool(b) => b.to_string(),
        ExprKind::Int(i) => i.to_string(),
        ExprKind::Float(x) => format_float(*x),
        ExprKind::Str(bytes) => format_string_literal(bytes),
        ExprKind::Char(b) => format_char_literal(*b),
        ExprKind::Var(name) => String::from_utf8_lossy(name).into_owned(),
        ExprKind::SelfKw => "self".to_string(),
        ExprKind::Array(items) => {
            if items.is_empty() { "[]".to_string() } else {
                format!("[ {} ]", items.iter().map(print_expr_inline).collect::<Vec<_>>().join(", "))
            }
        }
        ExprKind::Dict(pairs) => {
            if pairs.is_empty() { "@[]".to_string() } else {
                let parts = pairs.iter().map(|p| format!("{}: {}", String::from_utf8_lossy(&p.key), print_expr_inline(&p.value))).collect::<Vec<_>>();
                format!("@[ {} ]", parts.join(", "))
            }
        }
        ExprKind::Function(fun) => {
            let params = fun.params.iter().map(|(n, _)| String::from_utf8_lossy(n).into_owned()).collect::<Vec<_>>().join(", ");
            let body = print_block_inline(&fun.body);
            if body.is_empty() {
                format!("function({}) end", params)
            } else {
                format!("function({}) {} end", params, body)
            }
        }
        ExprKind::If(if_expr) => {
            let mut out = format!("if {} then", print_expr_inline(&if_expr.cond));
            let then_text = print_block_inline(&if_expr.then_block);
            if !then_text.is_empty() {
                out.push(' ');
                out.push_str(&then_text);
            }
            if let Some(else_block) = &if_expr.else_block {
                let else_text = print_block_inline(else_block);
                if !else_text.is_empty() {
                    out.push_str(" else ");
                    out.push_str(&else_text);
                }
            }
            out.push_str(" end");
            out
        }
        ExprKind::Command(block) => print_command_block_inline(block),
        ExprKind::Unary(op, inner) => {
            let op_text = match op { UnOp::Neg => "-", UnOp::Not => "not" };
            format!("({} {})", op_text, print_expr_inline(inner))
        }
        ExprKind::Binary(op, left, right, _) => {
            format!("({} {} {})", print_expr_inline(left), op.text(), print_expr_inline(right))
        }
        ExprKind::Call(callee, args, _) => {
            format!("{}({})", print_expr_inline(callee), args.iter().map(print_expr_inline).collect::<Vec<_>>().join(", "))
        }
        ExprKind::Index(base, index) => format!("{}[{}]", print_expr_inline(base), print_expr_inline(index)),
        ExprKind::Field(base, name, _) => format!("{}.{}", print_expr_inline(base), String::from_utf8_lossy(name)),
        ExprKind::IllFormed => "***ill-formed***".to_string(),
    }
}

// Commands

pub fn print_template(template: &Template) -> String {
    let mut content = String::new();
    for seg in &template.segments {
        match seg {
            TemplateSegment::Literal { bytes, .. } => content.push_str(&crate::source::escape_string_contents(bytes)),
            TemplateSegment::Var { name, .. } => {
                content.push_str("${");
                content.push_str(&String::from_utf8_lossy(name));
                content.push('}');
            }
        }
    }
    format!("\"{}\"", content)
}

pub fn print_command_inline(command: &Command) -> String {
    if command.ill_formed_program {
        return "***ill-formed*** ?".to_string();
    }
    let mut out = print_template(&command.program);
    for arg in &command.args {
        out.push(' ');
        out.push_str(&print_template(arg));
    }
    for redirect in &command.redirects {
        out.push(' ');
        out.push_str(&print_redirect(redirect));
    }
    for _ in 0..command.extra_ill_formed {
        out.push_str(" ***ill-formed***");
    }
    if command.question {
        out.push_str(" ?");
    }
    out
}

fn print_redirect(redirect: &Redirect) -> String {
    match redirect.kind {
        RedirectKind::Output => {
            let fd = redirect.source_fd.unwrap_or(1);
            match &redirect.target {
                RedirectTarget::File(t) => format!("{}>{}", fd, print_template(t)),
                RedirectTarget::Fd(n) => format!("{}>{}", fd, n),
                RedirectTarget::IllFormed => "***ill-formed***".to_string(),
            }
        }
        RedirectKind::Append => {
            let fd = redirect.source_fd.unwrap_or(1);
            match &redirect.target {
                RedirectTarget::File(t) => format!("{}>>{}", fd, print_template(t)),
                RedirectTarget::Fd(n) => format!("{}>>{}", fd, n),
                RedirectTarget::IllFormed => "***ill-formed***".to_string(),
            }
        }
        RedirectKind::Input => match &redirect.target {
            RedirectTarget::File(t) => format!("<{}", print_template(t)),
            RedirectTarget::Fd(n) => format!("<{}", n),
            RedirectTarget::IllFormed => "***ill-formed***".to_string(),
        },
        RedirectKind::InputString => match &redirect.target {
            RedirectTarget::File(t) => format!("<<{}", print_template(t)),
            RedirectTarget::Fd(n) => format!("<<{}", n),
            RedirectTarget::IllFormed => "***ill-formed***".to_string(),
        },
    }
}

pub fn print_pipeline_inline(pipeline: &Pipeline) -> String {
    if pipeline.ill_formed {
        return "***ill-formed*** ?".to_string();
    }
    pipeline.commands.iter().map(print_command_inline).collect::<Vec<_>>().join(" | ")
}

pub fn print_command_block_inline(block: &CommandBlock) -> String {
    let prefix = match block.kind {
        CommandBlockKind::Plain => "{",
        CommandBlockKind::Capture => "${",
        CommandBlockKind::Async => "&{",
    };
    if block.ill_formed_block {
        return format!("{} ***ill-formed*** ? }}", prefix);
    }
    let body = block.pipelines.iter().map(print_pipeline_inline).collect::<Vec<_>>().join("; ");
    format!("{} {} }}", prefix, body)
}

pub fn print_command_block_pretty(block: &CommandBlock, indent: usize) -> String {
    let prefix = match block.kind {
        CommandBlockKind::Plain => "{",
        CommandBlockKind::Capture => "${",
        CommandBlockKind::Async => "&{",
    };
    if block.ill_formed_block {
        return format!("{}\n{}***ill-formed*** ?\n{}}}", prefix, tabs(indent + 1), tabs(indent));
    }
    let mut lines = Vec::new();
    let total = block.pipelines.len();
    for (idx, pipeline) in block.pipelines.iter().enumerate() {
        let mut line = format!("{}{}", tabs(indent + 1), print_pipeline_inline(pipeline));
        if idx + 1 < total { line.push(';'); }
        lines.push(line);
    }
    format!("{}\n{}\n{}}}", prefix, lines.join("\n"), tabs(indent))
}

// Resolved program printing.

pub fn print_resolved_program(program: &ResolvedProgram) -> String {
    let fun = &program.function;
    let decls = print_slot_decls(&fun.slots, 0);
    let body = print_rblock(&fun.body, 0);
    format!("{}{}", decls_prefix(&decls), body)
}

fn decls_prefix(decls: &str) -> String {
    if decls.is_empty() {
        String::new()
    } else {
        format!("{}\n", decls)
    }
}

pub fn print_slot_decls(slots: &[SlotDecl], indent: usize) -> String {
    slots
        .iter()
        .enumerate()
        .map(|(idx, decl)| {
            let desc = match decl {
                SlotDecl::Auto => "auto".to_string(),
                SlotDecl::Capture(parent) => format!("capture #{}", parent),
                SlotDecl::AutoSelf => "auto self".to_string(),
            };
            format!("{}let #{}: {}", tabs(indent), idx, desc)
        })
        .collect::<Vec<_>>()
        .join("\n")
}

pub fn print_rblock(block: &[RStatement], indent: usize) -> String {
    block
        .iter()
        .map(|stmt| format!("{}{}", tabs(indent), print_rstmt(stmt, indent)))
        .collect::<Vec<_>>()
        .join("\n")
}

fn print_rstmt(stmt: &RStatement, indent: usize) -> String {
    match stmt {
        RStatement::LetSlot { slot, value } => format!("#{} = {}", slot, print_rexpr_pretty(value, indent)),
        RStatement::Assign { target, value, .. } => format!("{} = {}", print_rexpr_inline(target), print_rexpr_pretty(value, indent)),
        RStatement::Expr(expr) => print_rexpr_pretty(expr, indent),
        RStatement::Return(expr, _) => match expr {
            Some(expr) => format!("return {}", print_rexpr_pretty(expr, indent)),
            None => "return".to_string(),
        },
        RStatement::Break(_) => "break".to_string(),
        RStatement::For { slot, iter, body, .. } => format!(
            "for #{} in {} do\n{}\n{}end",
            slot,
            print_rexpr_inline(iter),
            print_rblock(body, indent + 1),
            tabs(indent)
        ),
        RStatement::While { cond, body, .. } => format!(
            "while {} do\n{}\n{}end",
            print_rexpr_inline(cond),
            print_rblock(body, indent + 1),
            tabs(indent)
        ),
        RStatement::IllFormed => "***ill-formed***".to_string(),
    }
}

fn print_rblock_inline(block: &[RStatement]) -> String {
    block.iter().map(print_rstmt_inline).collect::<Vec<_>>().join("; ")
}

fn print_rstmt_inline(stmt: &RStatement) -> String {
    match stmt {
        RStatement::LetSlot { slot, value } => format!("#{} = {}", slot, print_rexpr_inline(value)),
        RStatement::Assign { target, value, .. } => format!("{} = {}", print_rexpr_inline(target), print_rexpr_inline(value)),
        RStatement::Expr(expr) => print_rexpr_inline(expr),
        RStatement::Return(expr, _) => match expr {
            Some(expr) => format!("return {}", print_rexpr_inline(expr)),
            None => "return".to_string(),
        },
        RStatement::Break(_) => "break".to_string(),
        RStatement::For { slot, iter, body, .. } => format!("for #{} in {} do {} end", slot, print_rexpr_inline(iter), print_rblock_inline(body)),
        RStatement::While { cond, body, .. } => format!("while {} do {} end", print_rexpr_inline(cond), print_rblock_inline(body)),
        RStatement::IllFormed => "***ill-formed***".to_string(),
    }
}

pub fn print_rexpr_pretty(expr: &RExpr, indent: usize) -> String {
    match &expr.kind {
        RExprKind::Array(items) => {
            if items.is_empty() { return "[]".to_string(); }
            let inner = items.iter().map(|item| format!("{}{}", tabs(indent + 1), print_rexpr_pretty(item, indent + 1))).collect::<Vec<_>>().join(",\n");
            format!("[\n{}\n{}]", inner, tabs(indent))
        }
        RExprKind::Dict(pairs) => {
            if pairs.is_empty() { return "@[]".to_string(); }
            let inner = pairs.iter().map(|(k, v)| format!("{}{}: {}", tabs(indent + 1), String::from_utf8_lossy(k), print_rexpr_pretty(v, indent + 1))).collect::<Vec<_>>().join(",\n");
            format!("@[\n{}\n{}]", inner, tabs(indent))
        }
        RExprKind::FunctionValue(fun) => print_resolved_function_pretty(fun, indent),
        RExprKind::If(if_expr) => {
            let mut out = format!("if {} then", print_rexpr_inline(&if_expr.cond));
            if !if_expr.then_block.is_empty() {
                out.push('\n');
                out.push_str(&print_rblock(&if_expr.then_block, indent + 1));
            }
            if let Some(else_block) = &if_expr.else_block {
                if !else_block.is_empty() {
                    out.push('\n');
                    out.push_str(&tabs(indent));
                    out.push_str("else\n");
                    out.push_str(&print_rblock(else_block, indent + 1));
                }
            }
            out.push('\n');
            out.push_str(&tabs(indent));
            out.push_str("end");
            out
        }
        RExprKind::Command(block) => print_command_block_r_pretty(block, indent),
        _ => print_rexpr_inline(expr),
    }
}

fn print_resolved_function_pretty(fun: &ResolvedFunction, indent: usize) -> String {
    let decls = print_slot_decls(&fun.slots, indent + 1);
    let body = print_rblock(&fun.body, indent + 1);
    format!("function({})\n{}\n{}\n{}end", fun.param_count, decls, body, tabs(indent))
}

fn print_resolved_function_inline(fun: &ResolvedFunction) -> String {
    let decls = fun
        .slots
        .iter()
        .enumerate()
        .map(|(idx, decl)| {
            let desc = match decl {
                SlotDecl::Auto => "auto".to_string(),
                SlotDecl::Capture(parent) => format!("capture #{}", parent),
                SlotDecl::AutoSelf => "auto self".to_string(),
            };
            format!("let #{}: {}", idx, desc)
        })
        .collect::<Vec<_>>()
        .join("; ");
    let body = print_rblock_inline(&fun.body);
    let combined = match (decls.is_empty(), body.is_empty()) {
        (false, false) => format!("{}  {}", decls, body),
        (false, true) => format!("{} ", decls),
        (true, false) => format!(" {}", body),
        (true, true) => String::new(),
    };
    format!("function({}) {} end", fun.param_count, combined)
}

pub fn print_rexpr_inline(expr: &RExpr) -> String {
    match &expr.kind {
        RExprKind::Nil => "nil".to_string(),
        RExprKind::Bool(b) => b.to_string(),
        RExprKind::Int(i) => i.to_string(),
        RExprKind::Float(x) => format_float(*x),
        RExprKind::Str(bytes) => format_string_literal(bytes),
