pub struct Lexer {
    data: Vec<u8>,
    index: usize,
    line: u32,
    column: u32,
    source: Rc<String>,
    command_mode: bool,
    pub items: Vec<LexItem>,
    pub errors: Vec<ErrorItem>,
}

impl Lexer {
    pub fn new(data: Vec<u8>, source: Rc<String>) -> Self {
        Self { data, index: 0, line: 1, column: 0, source, command_mode: false, items: Vec::new(), errors: Vec::new() }
    }

    fn pos(&self) -> SourcePos { SourcePos::new(self.source.clone(), self.line, self.column) }

    fn peek(&self) -> Option<u8> { self.data.get(self.index).copied() }
    fn peek_at(&self, offset: usize) -> Option<u8> { self.data.get(self.index + offset).copied() }

    fn bump(&mut self) -> Option<u8> {
