                        bare_literal_all.push(value);
                        push_literal(&mut segments, &[value], false);
                    } else {
                        let mut displayed = String::new();
                        displayed.push(escaped_byte as char);
                        self.error_at(escape_pos, format!("invalid escape sequence '\\{}'.", displayed));
