        let mut name = vec![first];
        self.bump();
        while let Some(byte) = self.peek() {
            if byte.is_ascii_alphanumeric() || byte == b'_' {
                name.push(byte);
                self.bump();
            } else { break; }
        }
        let valid = is_valid_identifier(&name);
        if !valid {
            self.error_at(expansion_pos.clone(), format!("invalid identifier '{}'.", String::from_utf8_lossy(&name)));
        }
        let display = format!("${{{{{{}}}}}}}", String::from_utf8_lossy(&name));
        Some((TemplateSegment::Var { name, pos: expansion_pos, invalid: !valid }, display))
    }
}

fn is_valid_identifier(name: &[u8]) -> bool {
    !name.is_empty()
        && (name[0].is_ascii_alphabetic() || name[0] == b'_')
        && name.iter().all(|b| b.is_ascii_alphanumeric() || *b == b'_')
}
EOF
"}

