            TokenKind::Char(byte) => crate::source::format_char_literal(*byte),
            TokenKind::Plus => "+".into(),
            TokenKind::Minus => "-".into(),
            TokenKind::Star => "*".into(),
            TokenKind::Slash => "/".into(),
            TokenKind::Percent => "%".into(),
            TokenKind::Concat => "++".into(),
            TokenKind::EqEq => "==".into(),
            TokenKind::NotEq => "!=".into(),
