#[derive(Clone, Debug)]
pub enum LexItem {
    Token(Token),
    Error(ErrorItem),
}

pub fn rust_crash_expansion(line: u32) -> ! {
    let pid = std::process::id();
    eprintln!("\nthread 'main' ({}) panicked at src/syntax/lexer/automata/expansion.rs:{}:17:\nnot yet implemented\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace", pid, line);
    std::process::exit(101);
}

pub struct Lexer {
    data: Vec<u8>,
    index: usize,
    line: u32,
    column: u32,
    source: Rc<String>,
    command_mode: bool,
    pub items: Vec<LexItem>,
    pub errors: Vec<ErrorItem>,
}

impl Lexer {
    pub fn new(data: Vec<u8>, source: Rc<String>) -> Self {
        Self { data, index: 0, line: 1, column: 0, source, command_mode: false, items: Vec::new(), errors: Vec::new() }
    }

    fn pos(&self) -> SourcePos { SourcePos::new(self.source.clone(), self.line, self.column) }

    fn peek(&self) -> Option<u8> { self.data.get(self.index).copied() }
    fn peek_at(&self, offset: usize) -> Option<u8> { self.data.get(self.index + offset).copied() }

    fn bump(&mut self) -> Option<u8> {
        let byte = self.peek()?;
        self.index += 1;
        if byte == b'\n' {
            self.line += 1;
            self.column = 0;
        } else {
            self.column += 1;
        }
        Some(byte)
    }

    fn push_token(&mut self, kind: TokenKind, pos: SourcePos) {
        self.items.push(LexItem::Token(Token { kind, pos }));
    }

    fn push_error(&mut self, error: ErrorItem) {
        self.errors.push(error.clone());
        self.items.push(LexItem::Error(error));
    }

    fn error_at(&mut self, pos: SourcePos, message: String) {
        let err = ErrorItem::with_pos(pos, message);
        self.push_error(err);
    }

    fn skip_space_and_comments(&mut self) {
        loop {
            match self.peek() {
                Some(b' ') | Some(b'\t') | Some(b'\n') | Some(b'\r') | Some(0x0c) => { self.bump(); }
                Some(b'#') => {
                    while let Some(byte) = self.peek() {
                        if byte == b'\n' { break; }
                        self.bump();
                    }
                }
                _ => break,
            }
        }
    }

    pub fn lex(mut self) -> (Vec<Token>, Vec<ErrorItem>, Vec<LexItem>) {
        loop {
            self.skip_space_and_comments();
            let Some(byte) = self.peek() else { break };
            if self.command_mode {
                self.lex_command_token(byte);
            } else {
                self.lex_program_token(byte);
            }
        }
        let tokens = self
            .items
            .iter()
            .filter_map(|item| match item { LexItem::Token(t) => Some(t.clone()), LexItem::Error(_) => None })
            .collect();
        (tokens, self.errors.clone(), self.items.clone())
    }

    fn lex_program_token(&mut self, byte: u8) {
        let pos = self.pos();
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'_' => {
                let mut name = Vec::new();
                while let Some(b) = self.peek() {
                    if b.is_ascii_alphanumeric() || b == b'_' { name.push(b); self.bump(); } else { break; }
                }
                let kind = match name.as_slice() {
                    b"let" => TokenKind::Let,
                    b"function" => TokenKind::Function,
                    b"return" => TokenKind::Return,
                    b"if" => TokenKind::If,
                    b"then" => TokenKind::Then,
                    b"else" => TokenKind::Else,
                    b"elseif" => TokenKind::ElseIf,
                    b"for" => TokenKind::For,
                    b"in" => TokenKind::In,
                    b"do" => TokenKind::Do,
                    b"while" => TokenKind::While,
                    b"break" => TokenKind::Break,
                    b"end" => TokenKind::End,
                    b"not" => TokenKind::Not,
                    b"and" => TokenKind::And,
                    b"or" => TokenKind::Or,
                    b"nil" => TokenKind::Nil,
                    b"true" => TokenKind::True,
                    b"false" => TokenKind::False,
                    b"self" => TokenKind::SelfKw,
                    _ => TokenKind::Ident(name),
                };
                self.push_token(kind, pos);
            }
            b'0'..=b'9' => self.lex_number(),
            b'"' => {
                if let Some(bytes) = self.lex_string() {
                    self.push_token(TokenKind::Str(bytes), pos);
                }
            }
            b'\'' => {
                if let Some(byte) = self.lex_char() {
                    self.push_token(TokenKind::Char(byte), pos);
                }
            }
            b'@' => {
                if self.peek_at(1) == Some(b'[') {
                    self.bump(); self.bump();
                    self.push_token(TokenKind::DictStart, pos);
                } else {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(byte)));
                }
            }
            b'&' => {
                if self.peek_at(1) == Some(b'{') {
                    self.bump(); self.bump();
                    self.push_token(TokenKind::AsyncStart, pos);
                    self.command_mode = true;
                } else {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(byte)));
                }
            }
            b'$' => {
                if self.peek_at(1) == Some(b'{') {
                    self.bump(); self.bump();
                    self.push_token(TokenKind::CaptureStart, pos);
                    self.command_mode = true;
                } else {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(byte)));
                }
            }
            b'{' => {
                self.bump();
                self.push_token(TokenKind::CommandStart, pos);
                self.command_mode = true;
            }
            b'}' => { self.bump(); self.push_token(TokenKind::RBrace, pos); }
            b'+' => {
                self.bump();
                if self.peek() == Some(b'+') { self.bump(); self.push_token(TokenKind::Concat, pos); }
                else { self.push_token(TokenKind::Plus, pos); }
            }
            b'-' => { self.bump(); self.push_token(TokenKind::Minus, pos); }
            b'*' => { self.bump(); self.push_token(TokenKind::Star, pos); }
            b'/' => { self.bump(); self.push_token(TokenKind::Slash, pos); }
            b'%' => { self.bump(); self.push_token(TokenKind::Percent, pos); }
            b'=' => {
                self.bump();
                if self.peek() == Some(b'=') { self.bump(); self.push_token(TokenKind::EqEq, pos); }
                else { self.push_token(TokenKind::Assign, pos); }
            }
            b'!' => {
                if self.peek_at(1) == Some(b'=') {
                    self.bump(); self.bump(); self.push_token(TokenKind::NotEq, pos);
                } else {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(byte)));
                }
            }
            b'<' => {
                self.bump();
                if self.peek() == Some(b'=') { self.bump(); self.push_token(TokenKind::LtEq, pos); }
                else { self.push_token(TokenKind::Lt, pos); }
            }
            b'>' => {
                self.bump();
                if self.peek() == Some(b'=') { self.bump(); self.push_token(TokenKind::GtEq, pos); }
                else { self.push_token(TokenKind::Gt, pos); }
            }
            b'(' => { self.bump(); self.push_token(TokenKind::LParen, pos); }
            b')' => { self.bump(); self.push_token(TokenKind::RParen, pos); }
            b'[' => { self.bump(); self.push_token(TokenKind::LBracket, pos); }
            b']' => { self.bump(); self.push_token(TokenKind::RBracket, pos); }
            b',' => { self.bump(); self.push_token(TokenKind::Comma, pos); }
            b'.' => { self.bump(); self.push_token(TokenKind::Dot, pos); }
            b':' => { self.bump(); self.push_token(TokenKind::Colon, pos); }
            b'?' => { self.bump(); self.push_token(TokenKind::Question, pos); }
            _ => {
                self.bump();
                self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(byte)));
            }
        }
    }

    fn lex_number(&mut self) {
        let pos = self.pos();
        let start = self.index;
        while matches!(self.peek(), Some(b'0'..=b'9')) { self.bump(); }
        let mut is_float = false;
        if self.peek() == Some(b'.') {
            self.bump();
            match self.peek() {
                None => {
                    self.error_at(pos, "unexpected end of file.".to_string());
                    return;
                }
                Some(b'0'..=b'9') => {
                    is_float = true;
                    while matches!(self.peek(), Some(b'0'..=b'9')) { self.bump(); }
                }
                Some(other) => {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(other)));
                    return;
                }
            }
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.bump();
            match self.peek() {
                None => {
                    self.error_at(pos, "unexpected end of file.".to_string());
                    return;
                }
                Some(b'0'..=b'9') => {
                    is_float = true;
                    while matches!(self.peek(), Some(b'0'..=b'9')) { self.bump(); }
                }
                Some(other) => {
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(other)));
                    return;
                }
            }
        }
        let raw = String::from_utf8_lossy(&self.data[start..self.index]).into_owned();
        if is_float {
            match raw.parse::<f64>() {
                Ok(value) => self.push_token(TokenKind::Float(value), pos),
                Err(_) => self.error_at(pos, format!("invalid number '{}'.", raw)),
            }
        } else {
            match raw.parse::<i64>() {
                Ok(value) => self.push_token(TokenKind::Int(value), pos),
                Err(_) => self.error_at(pos, format!("invalid number '{}'.", raw)),
            }
        }
    }

    fn parse_escape(&mut self) -> Option<u8> {
        // The backslash is the current character.
        let pos = self.pos();
        self.bump();
        let escaped = self.peek()?;
        self.bump();
        match escaped {
            b'n' => Some(b'\n'),
            b't' => Some(b'\t'),
            b'0' => Some(0),
            b'\\' => Some(b'\\'),
            b'\'' => Some(b'\''),
            b'"' => Some(b'"'),
            _ => {
                let mut displayed = String::new();
                displayed.push(escaped as char);
                self.error_at(pos, format!("invalid escape sequence '\\{}'.", displayed));
                None
            }
        }
    }

    fn lex_string(&mut self) -> Option<Vec<u8>> {
        // current is opening quote
        self.bump();
        let mut bytes = Vec::new();
        loop {
            let byte = self.peek()?;
            match byte {
                b'"' => { self.bump(); return Some(bytes); }
                b'\\' => {
                    if let Some(escaped) = self.parse_escape() { bytes.push(escaped); }
                    if self.peek().is_none() {
                        let pos = self.pos();
                        self.error_at(pos, "unexpected end of file.".to_string());
                        return None;
                    }
                }
                _ => { bytes.push(byte); self.bump(); }
            }
            if self.peek().is_none() {
                let pos = self.pos();
                self.error_at(pos, "unexpected end of file.".to_string());
                return None;
            }
        }
    }

    fn lex_char(&mut self) -> Option<u8> {
        let start_pos = self.pos();
        self.bump(); // '
        let first = self.peek()?;
        if first == b'\'' {
            self.error_at(start_pos, "empty char literal.".to_string());
            self.bump();
            return None;
        }
        let result = if first == b'\\' {
            match self.parse_escape() {
                Some(byte) => byte,
                None => 0,
            }
        } else {
            self.bump();
            first
        };
        // Consume/discourage any bytes until the closing quote.
        loop {
            match self.peek() {
                None => {
                    let pos = self.pos();
                    self.error_at(pos, "unexpected end of file.".to_string());
                    return None;
                }
                Some(b'\'') => { self.bump(); return Some(result); }
                Some(other) => {
                    let pos = self.pos();
                    self.bump();
                    self.error_at(pos, format!("unexpected '{}'.", escape_debug_byte(other)));
                }
            }
        }
    }

    fn lex_command_token(&mut self, byte: u8) {
        let pos = self.pos();
        match byte {
            b'}' => {
                self.bump();
                self.push_token(TokenKind::RBrace, pos);
                self.command_mode = false;
            }
            b';' => { self.bump(); self.push_token(TokenKind::Semi, pos); }
            b'|' => { self.bump(); self.push_token(TokenKind::Pipe, pos); }
            b'>' => {
                self.bump();
                if self.peek() == Some(b'>') { self.bump(); self.push_token(TokenKind::GtGt, pos); }
                else { self.push_token(TokenKind::Gt, pos); }
            }
            b'<' => {
                self.bump();
                if self.peek() == Some(b'<') { self.bump(); self.push_token(TokenKind::LtLt, pos); }
                else { self.push_token(TokenKind::Lt, pos); }
            }
            b'?' => { self.bump(); self.push_token(TokenKind::Question, pos); }
            _ => {
                if let Some((template, display)) = self.lex_command_word() {
                    self.push_token(TokenKind::Word(template, display), pos);
                }
            }
        }
    }

    fn lex_command_word(&mut self) -> Option<(Template, String)> {
        let start_pos = self.pos();
        let mut segments: Vec<TemplateSegment> = Vec::new();
        let mut display_parts: Vec<String> = Vec::new();
        let mut bare_literal_all: Vec<u8> = Vec::new();
        let mut is_single_bare_literal = true;
        let mut fragment_count = 0usize;

        fn push_literal(segments: &mut Vec<TemplateSegment>, bytes: &[u8], glob: bool) {
            if bytes.is_empty() { return; }
            if let Some(TemplateSegment::Literal { bytes: current, glob: current_glob }) = segments.last_mut() {
                if *current_glob == glob {
                    current.extend_from_slice(bytes);
                    return;
                }
            }
            segments.push(TemplateSegment::Literal { bytes: bytes.to_vec(), glob });
        }

        loop {
            let Some(byte) = self.peek() else { break };
            match byte {
                b' ' | b'\t' | b'\n' | b'\r' | 0x0c | b';' | b'<' | b'>' | b'?' | b'}' | b'#' => break,
                b'[' => rust_crash_expansion(87),
                b'{' => rust_crash_expansion(91),
                b'\'' => {
                    is_single_bare_literal = false;
                    fragment_count += 1;
                    self.bump();
                    let mut value = Vec::new();
                    let mut closed = false;
                    while let Some(inner) = self.peek() {
                        if inner == b'\'' { self.bump(); closed = true; break; }
                        if inner == b'\\' {
                            if let Some(escaped) = self.parse_escape() { value.push(escaped); }
                        } else {
                            value.push(inner);
                            self.bump();
                        }
                    }
                    if !closed {
                        let pos = self.pos();
                        self.error_at(pos, "unexpected end of file.".to_string());
                        return None;
                    }
                    display_parts.push(format!("'{}'", crate::source::escape_string_contents(&value)));
                    push_literal(&mut segments, &value, false);
                }
                b'"' => {
                    is_single_bare_literal = false;
                    fragment_count += 1;
                    self.bump();
                    let mut display = String::from("\"");
                    let mut closed = false;
                    while let Some(inner) = self.peek() {
                        if inner == b'"' { self.bump(); closed = true; break; }
                        if inner == b'\\' {
                            if let Some(escaped) = self.parse_escape() {
                                display.push_str(&crate::source::escape_string_contents(&[escaped]));
                                push_literal(&mut segments, &[escaped], false);
                            }
                        } else if inner == b'$' {
                            let (seg, display_seg) = self.parse_command_expansion()?;
                            display.push_str(&display_seg);
                            match seg {
                                TemplateSegment::Literal { bytes, .. } => push_literal(&mut segments, &bytes, false),
                                other => segments.push(other),
                            }
                        } else {
                            display.push_str(&crate::source::escape_string_contents(&[inner]));
                            push_literal(&mut segments, &[inner], false);
                            self.bump();
                        }
                    }
                    if !closed {
                        let pos = self.pos();
                        self.error_at(pos, "unexpected end of file.".to_string());
                        return None;
                    }
                    display.push('"');
                    display_parts.push(display);
                }
                b'$' => {
                    is_single_bare_literal = false;
                    fragment_count += 1;
                    let (seg, display_seg) = self.parse_command_expansion()?;
                    display_parts.push(display_seg);
                    segments.push(seg);
                }
                b'\\' => {
                    fragment_count += 1;
                    let escape_pos = self.pos();
                    self.bump();
                    let Some(escaped_byte) = self.peek() else {
                        let pos = self.pos();
                        self.error_at(pos, "unexpected end of file.".to_string());
                        return None;
                    };
                    self.bump();
                    let mapped = match escaped_byte {
                        b'n' => Some(b'\n'),
                        b't' => Some(b'\t'),
                        b'0' => Some(0),
                        b'\\' => Some(b'\\'),
                        b'\'' => Some(b'\''),
                        b'"' => Some(b'"'),
                        b' ' | b';' | b'<' | b'>' | b'?' | b'$' => Some(escaped_byte),
                        _ => None,
                    };
                    if let Some(value) = mapped {
                        bare_literal_all.push(value);
                        push_literal(&mut segments, &[value], false);
                    } else {
                        let mut displayed = String::new();
                        displayed.push(escaped_byte as char);
                        self.error_at(escape_pos, format!("invalid escape sequence '\\{}'.", displayed));
                        // Recovery: drop the escape sequence.
                    }
                }
                _ => {
                    fragment_count += 1;
                    bare_literal_all.push(byte);
                    push_literal(&mut segments, &[byte], true);
                    self.bump();
                }
            }
        }

        if fragment_count == 0 {
            return None;
        }

        let empty_quoted = segments.is_empty() && !is_single_bare_literal;
        let bare_literal = if is_single_bare_literal && segments.iter().all(|seg| matches!(seg, TemplateSegment::Literal { glob: true, .. })) {
            Some(bare_literal_all.clone())
        } else { None };

        // Build the lexeme display from semantic segments if no explicit
        // fragment display was accumulated.  For bare/quoted fragments the
        // display_parts already record the original quoting style.
        let display = if display_parts.is_empty() {
            let mut out = String::new();
            for seg in &segments {
                match seg {
                    TemplateSegment::Literal { bytes, .. } => out.push_str(&crate::source::escape_string_contents(bytes)),
                    TemplateSegment::Var { name, .. } => {
                        out.push_str("${{");
                        out.push_str(&String::from_utf8_lossy(name));
                        out.push_str("}}");
                    }
                }
            }
            out
        } else {
            display_parts.concat()
        };

        Some((
            Template {
                segments,
                pos: start_pos,
                bare_literal,
                empty_quoted,
                quoted: !is_single_bare_literal,
            },
            display,
        ))
    }

    fn parse_command_expansion(&mut self) -> Option<(TemplateSegment, String)> {
        let expansion_pos = self.pos();
        self.bump(); // $
        if self.peek() == Some(b'{') {
            self.bump();
