                        b'n' => Some(b'\n'),
                        b't' => Some(b'\t'),
                        b'0' => Some(0),
                        b'\\' => Some(b'\\'),
                        b'\'' => Some(b'\''),
                        b'"' => Some(b'"'),
                        b' ' | b';' | b'<' | b'>' | b'?' | b'$' => Some(escaped_byte),
                        _ => None,
                    };
