        // fragment display was accumulated.  For bare/quoted fragments the
        // display_parts already record the original quoting style.
        let display = if display_parts.is_empty() {
            let mut out = String::new();
            for seg in &segments {
                match seg {
                    TemplateSegment::Literal { bytes, .. } => out.push_str(&crate::source::escape_string_contents(bytes)),
                    TemplateSegment::Var { name, .. } => {
                        out.push_str("${{");
                        out.push_str(&String::from_utf8_lossy(name));
                        out.push_str("}}");
                    }
                }
            }
            out
        } else {
            display_parts.concat()
        };

        Some((
            Template {
                segments,
                pos: start_pos,
                bare_literal,
                empty_quoted,
                quoted: !is_single_bare_literal,
            },
            display,
        ))
    }

    fn parse_command_expansion(&mut self) -> Option<(TemplateSegment, String)> {
        let expansion_pos = self.pos();
        self.bump(); // $
        if self.peek() == Some(b'{') {
            self.bump();
            let mut contents = Vec::new();
            let mut closed = false;
            while let Some(byte) = self.peek() {
                if byte == b'}' { self.bump(); closed = true; break; }
                contents.push(byte);
                self.bump();
            }
            if !closed {
                let pos = self.pos();
                self.error_at(pos, "unexpected end of file.".to_string());
                return None;
            }
            let valid = is_valid_identifier(&contents);
            if !valid {
                self.error_at(expansion_pos.clone(), format!("invalid identifier '{}'.", String::from_utf8_lossy(&contents)));
            }
            let display = format!("${{{{{{}}}}}}}", String::from_utf8_lossy(&contents));
            return Some((TemplateSegment::Var { name: contents, pos: expansion_pos, invalid: !valid }, display));
        }
        // Take one byte as the candidate identifier start, then identifier chars.
        let first = self.peek()?;
        let mut name = vec![first];
        self.bump();
        while let Some(byte) = self.peek() {
            if byte.is_ascii_alphanumeric() || byte == b'_' {
                name.push(byte);
                self.bump();
            } else { break; }
        }
        let valid = is_valid_identifier(&name);
        if !valid {
            self.error_at(expansion_pos.clone(), format!("invalid identifier '{}'.", String::from_utf8_lossy(&name)));
        }
        let display = format!("${{{{{{}}}}}}}", String::from_utf8_lossy(&name));
        Some((TemplateSegment::Var { name, pos: expansion_pos, invalid: !valid }, display))
    }
}

fn is_valid_identifier(name: &[u8]) -> bool {
    !name.is_empty()
        && (name[0].is_ascii_alphabetic() || name[0] == b'_')
        && name.iter().all(|b| b.is_ascii_alphanumeric() || *b == b'_')
}
EOF
