{"command":"cat > src/parser.rs <<'EOF'
use crate::ast::*;
use crate::lexer::{Token, TokenKind};
use crate::source::{ErrorItem, SourcePos};
use std::rc::Rc;

#[derive(Clone, Copy, PartialEq, Eq)]
enum BlockContext { Top, Function, IfThen, IfElse, Loop }

pub struct Parser {
    tokens: Vec<Token>,
    index: usize,
    source: Rc<String>,
    pub errors: Vec<ErrorItem>,
}

impl Parser {
    pub fn new(tokens: Vec<Token>, source: Rc<String>) -> Self {
        Self { tokens, index: 0, source, errors: Vec::new() }
    }

    fn peek(&self) -> Option<&Token> { self.tokens.get(self.index) }
    fn peek_at(&self, offset: usize) -> Option<&Token> { self.tokens.get(self.index + offset) }
    fn peek_kind(&self) -> Option<&TokenKind> { self.peek().map(|t| &t.kind) }
    fn at_eof(&self) -> bool { self.index >= self.tokens.len() }

    fn bump(&mut self) -> Option<Token> {
        let token = self.peek().cloned();
        if token.is_some() { self.index += 1; }
        token
    }

    fn check(&self, kind: &TokenKind) -> bool { self.peek_kind() == Some(kind) }

    fn error_expected(&mut self, expected: &str) {
        match self.peek().cloned() {
            Some(token) => {
                let message = format!("unexpected '{}', expected {}", token.display(), expected);
                self.errors.push(ErrorItem::with_pos(token.pos, message));
            }
            None => {
                self.errors.push(ErrorItem::without_pos("unexpected end of file".to_string()));
            }
        }
    }

    fn error_at(&mut self, pos: SourcePos, message: String) {
        self.errors.push(ErrorItem::with_pos(pos, message));
    }

    fn expect(&mut self, kind: &TokenKind, expected: &str) -> bool {
        if self.check(kind) { self.bump(); true } else { self.error_expected(expected); false }
    }

    fn expect_identifier(&mut self) -> Option<(Vec<u8>, SourcePos)> {
        match self.peek().cloned() {
            Some(Token { kind: TokenKind::Ident(name), pos }) => {
                self.bump();
                Some((name, pos))
            }
            _ => { self.error_expected("identifier"); None }
        }
    }

    pub fn parse_program(&mut self) -> Block {
        let (block, _) = self.parse_block(BlockContext::Top);
        block
    }

    fn is_terminator(&self, context: BlockContext) -> bool {
        match self.peek_kind() {
            None => true,
            Some(kind) => match context {
                BlockContext::Top => false,
                BlockContext::Function | BlockContext::IfElse | BlockContext::Loop => matches!(kind, TokenKind::End),
                BlockContext::IfThen => matches!(kind, TokenKind::End | TokenKind::Else | TokenKind::ElseIf),
            },
        }
    }

    fn parse_block(&mut self, context: BlockContext) -> (Block, bool) {
        let mut statements = Vec::new();
        let mut poisoned = false;
        loop {
            if self.at_eof() || self.is_terminator(context) { break; }
            // At the top level stray End/Else tokens are statements via
            // expression parsing; for non-top blocks terminators stop us.
            let stmt = self.parse_statement();
            if matches!(stmt, Statement::Return(..)) {
                match context {
                    BlockContext::Top => {
                        if self.at_eof() {
                            statements.push(stmt);
                            break;
                        } else {
                            // The original discards everything up to a
                            // top-level return when more code follows.
                            statements.clear();
                            continue;
                        }
                    }
                    _ => {
                        statements.push(stmt);
                        if !(self.at_eof() || self.is_terminator(context)) {
                            let expected = if context == BlockContext::IfThen { "end, else or elseif" } else { "'end'" };
                            self.error_expected(expected);
                            poisoned = true;
                            while !self.at_eof() && !self.is_terminator(context) { self.bump(); }
                        }
                        break;
                    }
                }
            } else {
                statements.push(stmt);
            }
        }
        (statements, poisoned)
    }

    fn parse_statement(&mut self) -> Statement {
        match self.peek_kind().cloned() {
            Some(TokenKind::Let) => {
                self.bump();
                let (name, name_pos) = match self.expect_identifier() {
                    Some(pair) => pair,
                    None => (Vec::new(), self.peek().map(|t| t.pos.clone()).unwrap_or(SourcePos::new(self.source.clone(), 1, 0))),
                };
                let init = if self.check(&TokenKind::Assign) {
                    self.bump();
                    Some(self.parse_expr())
                } else { None };
                Statement::Let { name, name_pos, init }
            }
            Some(TokenKind::Function) => {
                if matches!(self.peek_at(1).map(|t| &t.kind), Some(TokenKind::Ident(_))) {
                    // Named function declaration.
                    self.bump();
                    let (name, name_pos) = self.expect_identifier().unwrap();
                    let fun = self.parse_function_tail();
                    match fun {
                        Some(expr) => Statement::Let { name, name_pos, init: Some(expr) },
                        None => Statement::IllFormed,
                    }
                } else {
                    self.parse_expr_statement()
                }
            }
            Some(TokenKind::Return) => {
                let token = self.bump().unwrap();
                let value = if self.can_start_expr() {
                    Some(self.parse_expr())
                } else if self.at_eof() {
                    // `return` alone at EOF is an error in the original.
                    Some(self.parse_expr())
                } else {
                    None
                };
                Statement::Return(value, token.pos)
            }
            Some(TokenKind::Break) => {
                let token = self.bump().unwrap();
                Statement::Break(token.pos)
            }
            Some(TokenKind::For) => self.parse_for(),
            Some(TokenKind::While) => self.parse_while(),
            _ => self.parse_expr_statement(),
        }
    }

    fn can_start_expr(&self) -> bool {
        match self.peek_kind() {
            Some(kind) => matches!(
                kind,
                TokenKind::Ident(_)
                    | TokenKind::Int(_)
                    | TokenKind::Float(_)
                    | TokenKind::Str(_)
                    | TokenKind::Char(_)
                    | TokenKind::Nil
                    | TokenKind::True
                    | TokenKind::False
                    | TokenKind::SelfKw
                    | TokenKind::LParen
                    | TokenKind::LBracket
                    | TokenKind::DictStart
                    | TokenKind::Function
                    | TokenKind::If
                    | TokenKind::CommandStart
                    | TokenKind::CaptureStart
                    | TokenKind::AsyncStart
                    | TokenKind::Minus
                    | TokenKind::Not
            ),
            None => false,
        }
    }

    fn parse_expr_statement(&mut self) -> Statement {
        let expr = self.parse_expr();
        if self.check(&TokenKind::Assign) {
            let eq = self.bump().unwrap();
            let value = self.parse_expr();
            Statement::Assign { target: expr, value, eq_pos: eq.pos }
        } else {
            Statement::Expr(expr)
        }
    }

    fn parse_for(&mut self) -> Statement {
        let start = self.bump().unwrap(); // for
        let (name, name_pos) = match self.expect_identifier() {
            Some(pair) => pair,
            None => (Vec::new(), start.pos.clone()),
        };
        self.expect(&TokenKind::In, "'in'");
        let iter = self.parse_expr();
        self.expect(&TokenKind::Do, "'do'");
        let (body, poisoned) = self.parse_block(BlockContext::Loop);
        self.expect(&TokenKind::End, "'end'");
        if poisoned {
            Statement::Expr(Expr { kind: ExprKind::IllFormed, pos: start.pos })
        } else {
            Statement::For { name, name_pos, iter, body, pos: start.pos }
        }
    }

    fn parse_while(&mut self) -> Statement {
        let start = self.bump().unwrap(); // while
        let cond = self.parse_expr();
        self.expect(&TokenKind::Do, "'do'");
        let (body, poisoned) = self.parse_block(BlockContext::Loop);
        self.expect(&TokenKind::End, "'end'");
        if poisoned {
            Statement::Expr(Expr { kind: ExprKind::IllFormed, pos: start.pos })
        } else {
            Statement::While { cond, body, pos: start.pos }
        }
    }

    // Parses `(params) body end` after `function` (and optional name) has
    // been consumed.  Returns None when the body block was poisoned.
    fn parse_function_tail(&mut self) -> Option<Expr> {
        let function_pos = SourcePos::new(self.source.clone(), 1, 0);
        // We don't have the function token pos here in all paths; the
        // caller for expression functions handles positioning separately.
        let _ = function_pos;
        self.expect(&TokenKind::LParen, "'('");
        let mut params = Vec::new();
        loop {
            if self.check(&TokenKind::RParen) || self.at_eof() { break; }
            match self.expect_identifier() {
                Some(pair) => params.push(pair),
                None => {
                    // Recover from a stray comma.
                    if self.check(&TokenKind::Comma) { self.bump(); continue; } else { break; }
                }
            }
            if self.check(&TokenKind::Comma) { self.bump(); continue; }
            break;
        }
        self.expect(&TokenKind::RParen, "')'");
        let (body, poisoned) = self.parse_block(BlockContext::Function);
        self.expect(&TokenKind::End, "'end'");
        if poisoned { return None; }
        Some(Expr { kind: ExprKind::Function(FunctionExpr { params, body }), pos: SourcePos::new(self.source.clone(), 1, 0) })
    }

    fn parse_function_expr(&mut self) -> Expr {
        let start = self.bump().unwrap(); // function
        self.expect(&TokenKind::LParen, "'('");
        let mut params = Vec::new();
        loop {
            if self.check(&TokenKind::RParen) || self.at_eof() { break; }
            match self.expect_identifier() {
                Some(pair) => params.push(pair),
                None => {
                    if self.check(&TokenKind::Comma) { self.bump(); continue; } else { break; }
                }
            }
            if self.check(&TokenKind::Comma) { self.bump(); continue; }
            break;
        }
        self.expect(&TokenKind::RParen, "')'");
        let (body, poisoned) = self.parse_block(BlockContext::Function);
        self.expect(&TokenKind::End, "'end'");
        if poisoned {
            Expr { kind: ExprKind::IllFormed, pos: start.pos }
        } else {
            Expr { kind: ExprKind::Function(FunctionExpr { params, body }), pos: start.pos }
        }
    }

    fn parse_if_expr(&mut self) -> Expr {
        let start = self.bump().unwrap(); // if / consumed by caller pattern
        self.parse_if_tail(start.pos)
    }

    fn parse_if_tail(&mut self, start_pos: SourcePos) -> Expr {
        let cond = self.parse_expr();
        self.expect(&TokenKind::Then, "'then'");
        let (then_block, then_poisoned) = self.parse_block(BlockContext::IfThen);
        let mut else_block = None;
        let mut consumed_end = false;
        let mut poisoned = then_poisoned;
        if self.check(&TokenKind::ElseIf) {
            self.bump();
            let nested_pos = self.peek().map(|t| t.pos.clone()).unwrap_or(start_pos.clone());
            let nested = self.parse_if_tail(nested_pos);
            else_block = Some(vec![Statement::Expr(nested)]);
            consumed_end = true;
        } else if self.check(&TokenKind::Else) {
            self.bump();
            let (block, else_poisoned) = self.parse_block(BlockContext::IfElse);
            poisoned = poisoned || else_poisoned;
            else_block = Some(block);
        }
        if !consumed_end {
            self.expect(&TokenKind::End, "'end'");
        }
        if poisoned {
            Expr { kind: ExprKind::IllFormed, pos: start_pos }
        } else {
            Expr { kind: ExprKind::If(Box::new(IfExpr { cond, then_block, else_block })), pos: start_pos }
        }
    }

    pub fn parse_expr(&mut self) -> Expr { self.parse_binary_level(0) }

    fn parse_binary_level(&mut self, level: usize) -> Expr {
        // Levels: 0 or, 1 and, 2 equality, 3 relational, 4 concat,
        // 5 additive, 6 multiplicative, 7 unary/postfix.
        if level >= 7 {
            return self.parse_unary();
        }
        let ops: &[TokenKind] = match level {
            0 => &[TokenKind::Or],
            1 => &[TokenKind::And],
            2 => &[TokenKind::EqEq, TokenKind::NotEq],
            3 => &[TokenKind::Lt, TokenKind::LtEq, TokenKind::Gt, TokenKind::GtEq],
            4 => &[TokenKind::Concat],
            5 => &[TokenKind::Plus, TokenKind::Minus],
            _ => &[TokenKind::Star, TokenKind::Slash, TokenKind::Percent],
        };
        let mut left = self.parse_binary_level(level + 1);
        loop {
            let Some(kind) = self.peek_kind().cloned() else { break };
            if !ops.contains(&kind) { break; }
            let operator = self.bump().unwrap();
            let bin_op = match kind {
                TokenKind::Or => BinOp::Or,
                TokenKind::And => BinOp::And,
                TokenKind::EqEq => BinOp::Eq,
                TokenKind::NotEq => BinOp::NotEq,
                TokenKind::Lt => BinOp::Lt,
                TokenKind::LtEq => BinOp::LtEq,
                TokenKind::Gt => BinOp::Gt,
                TokenKind::GtEq => BinOp::GtEq,
                TokenKind::Concat => BinOp::Concat,
                TokenKind::Plus => BinOp::Add,
                TokenKind::Minus => BinOp::Sub,
                TokenKind::Star => BinOp::Mul,
                TokenKind::Slash => BinOp::Div,
                TokenKind::Percent => BinOp::Mod,
                _ => unreachable!(),
            };
            let right = self.parse_binary_level(level + 1);
            let pos = left.pos.clone();
            left = Expr { kind: ExprKind::Binary(bin_op, Box::new(left), Box::new(right), operator.pos), pos };
        }
        left
    }

    fn parse_unary(&mut self) -> Expr {
        match self.peek_kind().cloned() {
            Some(TokenKind::Minus) => {
                let operator = self.bump().unwrap();
                let inner = self.parse_unary();
                Expr { kind: ExprKind::Unary(UnOp::Neg, Box::new(inner)), pos: operator.pos }
            }
            Some(TokenKind::Not) => {
                let operator = self.bump().unwrap();
                let inner = self.parse_unary();
                Expr { kind: ExprKind::Unary(UnOp::Not, Box::new(inner)), pos: operator.pos }
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Expr {
        let mut expr = self.parse_primary();
        loop {
            match self.peek_kind().cloned() {
                Some(TokenKind::Dot) => {
                    self.bump();
                    match self.expect_identifier() {
                        Some((name, pos)) => {
                            let base_pos = expr.pos.clone();
                            expr = Expr { kind: ExprKind::Field(Box::new(expr), name, pos), pos: base_pos };
                        }
                        None => {
                            // Leave the offending token for upper levels.
                            break;
                        }
                    }
                }
                Some(TokenKind::LBracket) => {
                    self.bump();
                    let index = self.parse_expr();
                    self.expect(&TokenKind::RBracket, "']'");
                    let base_pos = expr.pos.clone();
                    expr = Expr { kind: ExprKind::Index(Box::new(expr), Box::new(index)), pos: base_pos };
                }
                Some(TokenKind::LParen) => {
                    let lparen = self.bump().unwrap();
                    let mut args = Vec::new();
                    if !self.check(&TokenKind::RParen) {
                        loop {
                            args.push(self.parse_expr());
                            if self.check(&TokenKind::Comma) {
                                self.bump();
                                if self.check(&TokenKind::RParen) { break; }
                                continue;
                            }
                            break;
                        }
                    }
                    self.expect(&TokenKind::RParen, "')'");
                    let base_pos = expr.pos.clone();
                    expr = Expr { kind: ExprKind::Call(Box::new(expr), args, lparen.pos), pos: base_pos };
                }
                _ => break,
            }
        }
        expr
    }

    fn parse_primary(&mut self) -> Expr {
        let Some(token) = self.peek().cloned() else {
            self.errors.push(ErrorItem::without_pos("unexpected end of file".to_string()));
            return Expr { kind: ExprKind::IllFormed, pos: SourcePos::new(self.source.clone(), 1, 0) };
        };
        match token.kind.clone() {
            TokenKind::Int(value) => { self.bump(); Expr { kind: ExprKind::Int(value), pos: token.pos } }
            TokenKind::Float(value) => { self.bump(); Expr { kind: ExprKind::Float(value), pos: token.pos } }
            TokenKind::Str(bytes) => { self.bump(); Expr { kind: ExprKind::Str(bytes), pos: token.pos } }
            TokenKind::Char(byte) => { self.bump(); Expr { kind: ExprKind::Char(byte), pos: token.pos } }
            TokenKind::Nil => { self.bump(); Expr { kind: ExprKind::Nil, pos: token.pos } }
            TokenKind::True => { self.bump(); Expr { kind: ExprKind::Bool(true), pos: token.pos } }
            TokenKind::False => { self.bump(); Expr { kind: ExprKind::Bool(false), pos: token.pos } }
            TokenKind::SelfKw => { self.bump(); Expr { kind: ExprKind::SelfKw, pos: token.pos } }
            TokenKind::Ident(name) => { self.bump(); Expr { kind: ExprKind::Var(name), pos: token.pos } }
            TokenKind::LParen => {
                self.bump();
                let expr = self.parse_expr();
                self.expect(&TokenKind::RParen, "')'");
                expr
            }
            TokenKind::LBracket => {
                self.bump();
                let mut items = Vec::new();
                while !self.check(&TokenKind::RBracket) && !self.at_eof() {
                    items.push(self.parse_expr());
                    if self.check(&TokenKind::Comma) { self.bump(); continue; }
                    break;
                }
                self.expect(&TokenKind::RBracket, "']'");
                Expr { kind: ExprKind::Array(items), pos: token.pos }
            }
            TokenKind::DictStart => {
                self.bump();
                let mut pairs = Vec::new();
                while !self.check(&TokenKind::RBracket) && !self.at_eof() {
                    let key_pos = self.peek().map(|t| t.pos.clone()).unwrap_or(token.pos.clone());
                    let key = match self.expect_identifier() {
                        Some((name, _)) => name,
                        None => Vec::new(),
                    };
                    self.expect(&TokenKind::Colon, "':'");
                    let value = self.parse_expr();
                    pairs.push(DictPair { key, key_pos, value });
                    if self.check(&TokenKind::Comma) { self.bump(); continue; }
                    break;
                }
                self.expect(&TokenKind::RBracket, "']'");
                Expr { kind: ExprKind::Dict(pairs), pos: token.pos }
            }
            TokenKind::Function => self.parse_function_expr(),
            TokenKind::If => self.parse_if_expr(),
            TokenKind::CommandStart => self.parse_command_block(CommandBlockKind::Plain),
            TokenKind::CaptureStart => self.parse_command_block(CommandBlockKind::Capture),
            TokenKind::AsyncStart => self.parse_command_block(CommandBlockKind::Async),
            _ => {
                self.error_expected("expression");
                self.bump();
                Expr { kind: ExprKind::IllFormed, pos: token.pos }
            }
        }
    }

    // Command blocks -------------------------------------------------------

    fn parse_command_block(&mut self, kind: CommandBlockKind) -> Expr {
        let start = self.bump().unwrap();
        if self.check(&TokenKind::RBrace) {
            let pos = self.peek().unwrap().pos.clone();
            self.error_at(pos, "empty command block".to_string());
            self.bump();
            return Expr {
                kind: ExprKind::Command(Box::new(CommandBlock { kind, pipelines: vec![Pipeline { commands: Vec::new(), ill_formed: true }], ill_formed_block: true })),
                pos: start.pos,
            };
        }
        let mut pipelines = Vec::new();
        loop {
            let pipeline = self.parse_pipeline();
            pipelines.push(pipeline);
            if self.check(&TokenKind::Semi) {
                self.bump();
                if self.check(&TokenKind::RBrace) { break; }
                if self.at_eof() { break; }
                continue;
            }
            break;
        }
        self.expect(&TokenKind::RBrace, "'}'");
        Expr { kind: ExprKind::Command(Box::new(CommandBlock { kind, pipelines, ill_formed_block: false })), pos: start.pos }
    }

    fn parse_pipeline(&mut self) -> Pipeline {
        let mut commands = Vec::new();
        let mut ill_formed = false;
        loop {
            let command = self.parse_command();
            if command.ill_formed_program { ill_formed = true; }
            commands.push(command);
            if self.check(&TokenKind::Pipe) { self.bump(); continue; }
            break;
        }
        Pipeline { commands, ill_formed }
    }

    fn parse_command(&mut self) -> Command {
        let start_pos = self.peek().map(|t| t.pos.clone()).unwrap_or(SourcePos::new(self.source.clone(), 1, 0));
        let program = match self.parse_command_argument() {
            Some(template) => template,
            None => {
                return Command {
                    program: Template { segments: Vec::new(), pos: start_pos.clone(), bare_literal: None, empty_quoted: false, quoted: false },
                    args: Vec::new(),
                    redirects: Vec::new(),
                    extra_ill_formed: 0,
                    question: false,
                    pos: start_pos,
                    ill_formed_program: true,
                };
            }
        };
        let command_pos = program.pos.clone();
        let mut command = Command {
            program,
            args: Vec::new(),
            redirects: Vec::new(),
            extra_ill_formed: 0,
            question: false,
            pos: command_pos,
            ill_formed_program: false,
        };

        let mut redirects_only = false;
        loop {
            match self.peek_kind().cloned() {
                None | Some(TokenKind::Pipe) | Some(TokenKind::Semi) | Some(TokenKind::RBrace) => break,
                Some(TokenKind::Question) => {
                    self.bump();
                    command.question = true;
                    break;
                }
                _ => {}
            }
            // FD-prefixed output redirect or a plain redirect operator?
            if self.redirect_operator_ahead() {
                redirects_only = true;
                self.parse_redirect(&mut command);
                continue;
            }
            if self.integer_input_redirect_ahead() {
                // e.g. `0<file`: report both the operator and the target.
                self.bump(); // integer word
                self.error_expected("output redirection");
                self.bump(); // '<' / '<<'
                command.extra_ill_formed += 1;
                redirects_only = true;
                // The next argument token will trigger the second error
                // through the redirects_only branch below.
                continue;
            }
            if redirects_only {
                self.error_expected("output redirection");
                self.bump();
                command.extra_ill_formed += 1;
                break;
            }
            match self.parse_command_argument() {
                Some(argument) => command.args.push(argument),
                None => {
                    command.ill_formed_program = true;
                    break;
                }
            }
        }
        command
    }

    fn redirect_operator_ahead(&self) -> bool {
        match self.peek_kind() {
            Some(TokenKind::Gt) | Some(TokenKind::GtGt) | Some(TokenKind::Lt) | Some(TokenKind::LtLt) => true,
            _ => {
                // integer word followed by > or >>
                if let (Some(Token { kind: TokenKind::Word(template, _), .. }), Some(next)) = (self.peek(), self.peek_at(1)) {
                    if template.bare_literal.as_ref().map(|lit| parse_integer_literal(lit).is_some()).unwrap_or(false)
                        && matches!(next.kind, TokenKind::Gt | TokenKind::GtGt)
                    {
                        return true;
                    }
                }
                false
            }
        }
    }

    fn integer_input_redirect_ahead(&self) -> bool {
        if let (Some(Token { kind: TokenKind::Word(template, _), .. }), Some(next)) = (self.peek(), self.peek_at(1)) {
            return template.bare_literal.as_ref().map(|lit| parse_integer_literal(lit).is_some()).unwrap_or(false)
                && matches!(next.kind, TokenKind::Lt | TokenKind::LtLt);
        }
        false
    }

    fn parse_redirect(&mut self, command: &mut Command) {
        let mut source_fd = None;
        // Optional FD prefix.
        if let Some(Token { kind: TokenKind::Word(template, _), .. }) = self.peek().cloned() {
            if let (Some(literal), Some(next)) = (template.bare_literal.clone(), self.peek_at(1)) {
                if matches!(next.kind, TokenKind::Gt | TokenKind::GtGt) {
                    source_fd = parse_integer_literal(&literal);
                    self.bump();
                }
            }
        }
        let operator = self.bump();
        let Some(operator) = operator else { return };
        let kind = match operator.kind {
            TokenKind::Gt => RedirectKind::Output,
            TokenKind::GtGt => RedirectKind::Append,
            TokenKind::Lt => RedirectKind::Input,
            TokenKind::LtLt => RedirectKind::InputString,
            _ => return,
        };
        let target = match self.parse_command_argument() {
            Some(template) => {
                if kind == RedirectKind::Output {
                    if let Some(literal) = template.bare_literal.clone() {
                        if let Some(fd) = parse_integer_literal(&literal) {
                            RedirectTarget::Fd(fd)
                        } else {
                            RedirectTarget::File(template)
                        }
                    } else {
                        RedirectTarget::File(template)
                    }
                } else {
                    RedirectTarget::File(template)
                }
            }
            None => RedirectTarget::IllFormed,
        };
        command.redirects.push(Redirect { source_fd, kind, target });
    }

    fn parse_command_argument(&mut self) -> Option<Template> {
        let token = self.peek().cloned()?;
        match token.kind.clone() {
            TokenKind::Word(template, _) => { self.bump(); Some(template) }
            TokenKind::Str(bytes) => {
                self.bump();
                Some(Template::literal(bytes, token.pos))
            }
            TokenKind::Char(byte) => {
                self.bump();
                Some(Template::literal(vec![byte], token.pos))
            }
            TokenKind::Int(value) => {
                self.bump();
                Some(Template::literal(value.to_string().into_bytes(), token.pos))
            }
            TokenKind::Float(value) => {
                self.bump();
                Some(Template::literal(crate::value::format_float(value).into_bytes(), token.pos))
            }
            _ => {
                self.error_expected("argument");
                None
            }
        }
    }
}

pub fn parse_integer_literal(literal: &[u8]) -> Option<i64> {
    if literal.is_empty() { return None; }
    let text = std::str::from_utf8(literal).ok()?;
    // Only a plain (optionally signed) decimal integer counts.
    let digits = text.strip_prefix('-').or_else(|| text.strip_prefix('+')).unwrap_or(text);
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) { return None; }
    text.parse::<i64>().ok().or(Some(0))
}
EOF
