{"command":"cat > src/resolver.rs <<'EOF'
use crate::ast::*;
use crate::source::{ErrorItem, SourcePos};
use std::collections::HashMap;
use std::rc::Rc;

struct DeclInfo {
    frame: usize,
    slot: usize,
}

struct FrameContext {
    scopes: Vec<HashMap<Vec<u8>, usize>>,
    slots: Vec<SlotDecl>,
    captures: HashMap<usize, usize>, // parent slot -> this slot
    self_slot: Option<usize>,
    loop_depth: usize,
}

impl FrameContext {
    fn new() -> Self {
        Self { scopes: vec![HashMap::new()], slots: Vec::new(), captures: HashMap::new(), self_slot: None, loop_depth: 0 }
    }
    fn allocate(&mut self) -> usize {
        self.slots.push(SlotDecl::Auto);
        self.slots.len() - 1
    }
}

pub struct Resolver {
    pub errors: Vec<ErrorItem>,
    frames: Vec<FrameContext>,
}

impl Resolver {
    pub fn new() -> Self { Self { errors: Vec::new(), frames: Vec::new() } }

    fn error(&mut self, pos: SourcePos, message: String) {
        self.errors.push(ErrorItem::with_pos(pos, message));
    }

    pub fn resolve_program(&mut self, block: &Block) -> ResolvedProgram {
        let mut frame = FrameContext::new();
        // std is slot 0 in the global scope.
        let std_slot = frame.allocate();
        debug_assert_eq!(std_slot, 0);
        frame.scopes[0].insert(b"std".to_vec(), std_slot);
        self.frames.push(frame);
        let body = self.resolve_block(block, false);
        let frame = self.frames.pop().unwrap();
        ResolvedProgram {
            function: ResolvedFunction {
                param_count: 0,
                slots: frame.slots,
                body,
                display_pos: SourcePos::new(Rc::new("<stdin>".to_string()), 1, 0),
            },
        }
    }

    fn current_frame_index(&self) -> usize { self.frames.len() - 1 }

    fn declare(&mut self, name: &[u8], name_pos: &SourcePos) -> usize {
        let frame_index = self.current_frame_index();
        let frame = &mut self.frames[frame_index];
        let slot = frame.allocate();
        let scope = frame.scopes.last_mut().unwrap();
        if scope.contains_key(name) {
            let message = format!("duplicate variable '{}'", String::from_utf8_lossy(name));
            self.errors.push(ErrorItem::with_pos(name_pos.clone(), message));
        }
        scope.insert(name.to_vec(), slot);
        slot
    }

    fn lookup(&mut self, name: &[u8]) -> Option<DeclInfo> {
        // Search the current frame's scopes.
        let current = self.current_frame_index();
        for scope in self.frames[current].scopes.iter().rev() {
            if let Some(slot) = scope.get(name) {
                return Some(DeclInfo { frame: current, slot: *slot });
            }
        }
        // Search ancestor frames from nearest to farthest.
        for frame_index in (0..current).rev() {
            let found = {
                let frame = &self.frames[frame_index];
                let mut result = None;
                for scope in frame.scopes.iter().rev() {
                    if let Some(slot) = scope.get(name) { result = Some(*slot); break; }
                }
                result
            };
            if let Some(mut remote_slot) = found {
                // Build the capture chain through each intermediate frame.
                for intermediate in (frame_index + 1)..=current {
                    let existing = self.frames[intermediate].captures.get(&remote_slot).copied();
                    let slot = match existing {
                        Some(slot) => slot,
                        None => {
                            let frame = &mut self.frames[intermediate];
                            let slot = frame.slots.len();
                            frame.slots.push(SlotDecl::Capture(remote_slot));
                            frame.captures.insert(remote_slot, slot);
                            slot
                        }
                    };
                    remote_slot = slot;
                }
                return Some(DeclInfo { frame: current, slot: remote_slot });
            }
        }
        None
    }

    fn self_slot(&mut self, pos: &SourcePos) -> Option<usize> {
        if self.frames.len() <= 1 {
            self.error(pos.clone(), "self keyword outside function".to_string());
            return None;
        }
        let frame_index = self.current_frame_index();
        let frame = &mut self.frames[frame_index];
        if let Some(slot) = frame.self_slot { return Some(slot); }
        let slot = frame.slots.len();
        frame.slots.push(SlotDecl::AutoSelf);
        frame.self_slot = Some(slot);
        Some(slot)
    }

    fn resolve_block(&mut self, block: &Block, scoped: bool) -> Vec<RStatement> {
        if scoped {
            let frame = &mut self.frames[self.current_frame_index()];
            frame.scopes.push(HashMap::new());
        }
        let mut out = Vec::new();
        for stmt in block {
            self.resolve_stmt(stmt, &mut out);
        }
        if scoped {
            let frame = &mut self.frames[self.current_frame_index()];
            frame.scopes.pop();
        }
        out
    }

    fn resolve_stmt(&mut self, stmt: &Statement, out: &mut Vec<RStatement>) {
        match stmt {
            Statement::Let { name, name_pos, init } => {
                let slot = self.declare(name, name_pos);
                let value = match init {
                    Some(expr) => self.resolve_expr(expr),
                    None => RExpr { kind: RExprKind::Nil, pos: name_pos.clone() },
                };
                out.push(RStatement::LetSlot { slot, value });
            }
            Statement::Assign { target, value, eq_pos } => {
                let resolved_target = self.resolve_expr(target);
                let resolved_value = self.resolve_expr(value);
                if !is_assignable(target) {
                    self.error(eq_pos.clone(), "invalid assignment".to_string());
                }
                out.push(RStatement::Assign { target: resolved_target, value: resolved_value, eq_pos: eq_pos.clone() });
            }
            Statement::Expr(expr) => out.push(RStatement::Expr(self.resolve_expr(expr))),
            Statement::Return(expr, pos) => {
                if self.frames.len() <= 1 {
                    self.error(pos.clone(), "return statement outside function".to_string());
                }
                let value = expr.as_ref().map(|e| self.resolve_expr(e));
                out.push(RStatement::Return(value, pos.clone()));
            }
            Statement::Break(pos) => {
                let in_loop = self.frames.last().map(|f| f.loop_depth > 0).unwrap_or(false);
                if !in_loop {
                    self.error(pos.clone(), "break statement outside loop".to_string());
                }
                out.push(RStatement::Break(pos.clone()));
            }
            Statement::For { name, name_pos, iter, body, pos } => {
                let iter = self.resolve_expr(iter);
                // The loop variable lives in the body scope.
                let frame = &mut self.frames[self.current_frame_index()];
                frame.scopes.push(HashMap::new());
                let slot = self.declare(name, name_pos);
                self.frames[self.current_frame_index()].loop_depth += 1;
                let body = self.resolve_block(body, false);
                self.frames[self.current_frame_index()].loop_depth -= 1;
                let frame = &mut self.frames[self.current_frame_index()];
                frame.scopes.pop();
                out.push(RStatement::For { slot, iter, body, pos: pos.clone() });
            }
            Statement::While { cond, body, pos } => {
                let cond = self.resolve_expr(cond);
                self.names[self.current_frame_index()].loop_depth += 1;
                let body = self.resolve_block(body, true);
                self.frames[self.current_frame_index()].loop_depth -= 1;
                out.push(RStatement::While { cond, body, pos: pos.clone() });
            }
            Statement::IllFormed => out.push(RStatement::IllFormed),
        }
    }

    fn resolve_expr(&mut self, expr: &Expr) -> RExpr {
        let resolved_kind = match &expr.kind {
            ExprKind::Nil => RExprKind::Nil,
            ExprKind::Bool(b) => RExprKind::Bool(*b),
            ExprKind::Int(i) => RExprKind::Int(*i),
            ExprKind::Float(x) => RExprKind::Float(*x),
            ExprKind::Str(bytes) => RExprKind::Str(bytes.clone()),
            ExprKind::Char(b) => RExprKind::Char(*b),
            ExprKind::Var(name) => match self.lookup(name) {
                Some(decl) => RExprKind::Slot(decl.slot),
                None => {
                    self.error(expr.pos.clone(), format!("undeclared variable '{}'", String::from_utf8_lossy(name)));
                    RExprKind::IllFormed
                }
            },
            ExprKind::SelfKw => match self.self_slot(&expr.pos) {
                Some(slot) => RExprKind::Slot(slot),
                None => RExprKind::IllFormed,
            },
            ExprKind::Array(items) => RExprKind::Array(items.iter().map(|e| self.resolve_expr(e)).collect()),
            ExprKind::Dict(pairs) => {
                // Duplicate keys are checked here (semantic phase).
                let mut seen: Vec<&Vec<u8>> = Vec::new();
                for pair in pairs {
                    if seen.contains(&&pair.key) {
                        self.error(pair.key_pos.clone(), format!("duplicate key '{}'", String::from_utf8_lossy(&pair.key)));
                    } else {
                        seen.push(&pair.key);
                    }
                }
                RExprKind::Dict(pairs.iter().map(|p| (p.key.clone(), self.resolve_expr(&p.value))).collect())
            }
            ExprKind::Function(fun) => {
                let function = self.resolve_function(fun, expr.pos.clone());
                RExprKind::FunctionValue(std::sync::Arc::new(function))
            }
            ExprKind::If(if_expr) => {
                let cond = self.resolve_expr(&if_expr.cond);
                let then_block = self.resolve_block(&if_expr.then_block, true);
                let else_block = if_expr.else_block.as_ref().map(|block| self.resolve_block(block, true));
                RExprKind::If(Box::new(RIfExpr { cond, then_block, else_block }))
            }
            ExprKind::Command(block) => RExprKind::Command(Box::new(self.resolve_command_block(block))),
            ExprKind::Unary(op, inner) => RExprKind::Unary(*op, Box::new(self.resolve_expr(inner))),
            ExprKind::Binary(op, left, right, op_pos) => RExprKind::Binary(
                *op,
                Box::new(self.resolve_expr(left)),
                Box::new(self.resolve_expr(right)),
                op_pos.clone(),
            ),
            ExprKind::Call(callee, args, lparen_pos) => RExprKind::Call(
                Box::new(self.resolve_expr(callee)),
                args.iter().map(|e| self.resolve_expr(e)).collect(),
                lparen_pos.clone(),
            ),
            ExprKind::Index(base, index) => RExprKind::Index(Box::new(self.resolve_expr(base)), Box::new(self.resolve_expr(index))),
            ExprKind::Field(base, name, name_pos) => RExprKind::Field(Box::new(self.resolve_expr(base)), name.clone(), name_pos.clone()),
            ExprKind::IllFormed => RExprKind::IllFormed,
        };
        RExpr { kind: resolved_kind, pos: expr.pos.clone() }
    }

    fn resolve_function(&mut self, fun: &FunctionExpr, display_pos: SourcePos) -> ResolvedFunction {
        let mut frame = FrameContext::new();
        self.frames.push(frame);
        let frame_index = self.current_frame_index();
        for (name, name_pos) in &fun.params {
            // Parameters are declared in the function's top scope.
            let slot = {
                let frame = &mut self.frames[frame_index];
                let slot = frame.allocate();
                let scope = frame.scopes.last_mut().unwrap();
                if scope.contains_key(name) {
                    // report below after releasing the borrow
                    Some((slot, true))
                } else {
                    scope.insert(name.clone(), slot);
                    Some((slot, false))
                }
            };
            if let Some((slot, duplicate)) = slot {
                if duplicate {
                    self.error(name_pos.clone(), format!("duplicate variable '{}'", String::from_utf8_lossy(name)));
                    // The duplicate parameter still shadows (matching the
                    // declaration behaviour for `let`).
                    self.names[frame_index].scopes.last_mut().unwrap().insert(name.clone(), slot);
                }
            }
            let _ = name_pos;
        }
        let body = self.resolve_block(&fun.body, false);
        let frame = self.frames.pop().unwrap();
        ResolvedFunction { param_count: fun.params.len(), slots: frame.slots, body, display_pos }
    }

    fn resolve_command_block(&mut self, block: &CommandBlock) -> CommandBlockR {
        CommandBlockR {
            kind: block.kind,
            pipelines: block.pipelines.iter().map(|pipeline| PipelineR {
                ill_formed: pipeline.ill_formed,
                commands: pipeline.commands.iter().map(|command| self.resolve_command(command)).collect(),
            }).collect(),
            ill_formed_block: block.ill_formed_block,
        }
    }

    fn resolve_command(&mut self, command: &Command) -> CommandR {
        CommandR {
            program: self.resolve_template(&command.program),
            args: command.args.iter().map(|t| self.resolve_template(t)).collect(),
            redirects: command.redirects.iter().map(|redirect| RedirectR {
                source_fd: redirect.source_fd,
                kind: redirect.kind,
                target: match &redirect.target {
                    RedirectTarget::File(t) => RedirectTargetR::File(self.resolve_template(t)),
                    RedirectTarget::Fd(fd) => RedirectTargetR::Fd(*fd),
                    RedirectTarget::IllFormed => RedirectTargetR::IllFormed,
                },
            }).collect(),
            extra_ill_formed: command.extra_ill_formed,
            question: command.question,
            pos: command.pos.clone(),
            ill_formed_program: command.ill_formed_program,
        }
    }

    fn resolve_template(&mut self, template: &Template) -> TemplateR {
        TemplateR {
            segments: template.segments.iter().map(|segment| match segment {
                TemplateSegment::Literal { bytes, glob } => TemplateSegmentR::Literal { bytes: bytes.clone(), glob: *glob },
                TemplateSegment::Var { name, pos, invalid } => {
                    if *invalid {
                        TemplateSegmentR::Slot { slot: usize::MAX, pos: pos.clone(), invalid: true }
                    } else {
                        match self.lookup(name) {
                            Some(decl) => TemplateSegmentR::Slot { slot: decl.slot, pos: pos.clone(), invalid: false },
                            None => {
                                self.error(pos.clone(), format!("undeclared variable '{}'", String::from_utf8_lossy(name)));
                                TemplateSegmentR::Slot { slot: usize::MAX, pos: pos.clone(), invalid: true }
                            }
                        }
                    }
                }
            }).collect(),
            pos: template.pos.clone(),
            bare_literal: template.bare_literal.clone(),
            empty_quoted: template.empty_quoted,
            quoted: template.quoted,
        }
    }
}

fn is_assignable(expr: &Expr) -> bool {
    matches!(expr.kind, ExprKind::Var(_) | ExprKind::Index(..) | ExprKind::Field(..))
}
