use crate::ast::*;
use crate::source::{ErrorItem, SourcePos};
use std::collections::HashMap;
use std::rc::Rc;

struct DeclInfo {
    frame: usize,
    slot: usize,
}

struct FrameContext {
    scopes: Vec<HashMap<Vec<u8>, usize>>,
    slots: Vec<SlotDecl>,
    captures: HashMap<usize, usize>, // parent slot -> this slot
    self_slot: Option<usize>,
    loop_depth: usize,
}

impl FrameContext {
    fn new() -> Self {
        Self { scopes: vec![HashMap::new()], slots: Vec::new(), captures: HashMap::new(), self_slot: None, loop_depth: 0 }
    }
    fn allocate(&mut self) -> usize {
        self.slots.push(SlotDecl::Auto);
        self.slots.len() - 1
    }
}

pub struct Resolver {
    pub errors: Vec<ErrorItem>,
    frames: Vec<FrameContext>,
}

impl Resolver {
    pub fn new() -> Self { Self { errors: Vec::new(), frames: Vec::new() } }

    fn error(&mut self, pos: SourcePos, message: String) {
        self.errors.push(ErrorItem::with_pos(pos, message));
    }

    pub fn resolve_program(&mut self, block: &Block) -> ResolvedProgram {
        let mut frame = FrameContext::new();
        // std is slot 0 in the global scope.
        let std_slot = frame.allocate();
        debug_assert_eq!(std_slot, 0);
        frame.scopes[0].insert(b"std".to_vec(), std_slot);
        self.frames.push(frame);
        let body = self.resolve_block(block, false);
        let frame = self.frames.pop().unwrap();
        ResolvedProgram {
            function: ResolvedFunction {
                param_count: 0,
                slots: frame.slots,
                body,
                display_pos: SourcePos::new(Rc::new("<stdin>".to_string()), 1, 0),
            },
        }
    }

    fn current_frame_index(&self) -> usize { self.frames.len() - 1 }

    fn declare(&mut self, name: &[u8], name_pos: &SourcePos) -> usize {
        let frame_index = self.current_frame_index();
        let frame = &mut self.frames[frame_index];
        let slot = frame.allocate();
        let scope = frame.scopes.last_mut().unwrap();
        if scope.contains_key(name) {
            let message = format!("duplicate variable '{}'", String::from_utf8_lossy(name));
            self.errors.push(ErrorItem::with_pos(name_pos.clone(), message));
        }
        scope.insert(name.to_vec(), slot);
        slot
    }

    fn lookup(&mut self, name: &[u8]) -> Option<DeclInfo> {
        // Search the current frame's scopes.
        let current = self.current_frame_index();
        for scope in self.frames[current].scopes.iter().rev() {
            if let Some(slot) = scope.get(name) {
                return Some(DeclInfo { frame: current, slot: *slot });
            }
        }
        // Search ancestor frames from nearest to farthest.
        for frame_index in (0..current).rev() {
            let found = {
                let frame = &self.frames[frame_index];
                let mut result = None;
                for scope in frame.scopes.iter().rev() {
                    if let Some(slot) = scope.get(name) { result = Some(*slot); break; }
                }
                result
            };
            if let Some(mut remote_slot) = found {
                // Build the capture chain through each intermediate frame.
                for intermediate in (frame_index + 1)..=current {
                    let existing = self.frames[intermediate].captures.get(&remote_slot).copied();
                    let slot = match existing {
                        Some(slot) => slot,
                        None => {
                            let frame = &mut self.frames[intermediate];
                            let slot = frame.slots.len();
                            frame.slots.push(SlotDecl::Capture(remote_slot));
                            frame.captures.insert(remote_slot, slot);
                            slot
                        }
                    };
                    remote_slot = slot;
                }
                return Some(DeclInfo { frame: current, slot: remote_slot });
            }
        }
        None
    }

    fn self_slot(&mut self, pos: &SourcePos) -> Option<usize> {
        if self.frames.len() <= 1 {
            self.error(pos.clone(), "self keyword outside function".to_string());
            return None;
        }
        let frame_index = self.current_frame_index();
        let frame = &mut self.frames[frame_index];
        if let Some(slot) = frame.self_slot { return Some(slot); }
        let slot = frame.slots.len();
        frame.slots.push(SlotDecl::AutoSelf);
        frame.self_slot = Some(slot);
        Some(slot)
    }

    fn resolve_block(&mut self, block: &Block, scoped: bool) -> Vec<RStatement> {
        if scoped {
            let frame = &mut self.frames[self.current_frame_index()];
            frame.scopes.push(HashMap::new());
        }
        let mut out = Vec::new();
        for stmt in block {
            self.resolve_stmt(stmt, &mut out);
        }
        if scoped {
            let frame = &mut self.frames[self.current_frame_index()];
            frame.scopes.pop();
        }
        out
    }

    fn resolve_stmt(&mut self, stmt: &Statement, out: &mut Vec<RStatement>) {
        match stmt {
            Statement::Let { name, name_pos, init } => {
                let slot = self.declare(name, name_pos);
                let value = match init {
                    Some(expr) => self.resolve_expr(expr),
                    None => RExpr { kind: RExprKind::Nil, pos: name_pos.clone() },
                };
                out.push(RStatement::LetSlot { slot, value });
            }
            Statement::Assign { target, value, eq_pos } => {
                let resolved_target = self.resolve_expr(target);
                let resolved_value = self.resolve_expr(value);
                if !is_assignable(target) {
                    self.error(eq_pos.clone(), "invalid assignment".to_string());
                }
                out.push(RStatement::Assign { target: resolved_target, value: resolved_value, eq_pos: eq_pos.clone() });
            }
            Statement::Expr(expr) => out.push(RStatement::Expr(self.resolve_expr(expr))),
            Statement::Return(expr, pos) => {
                if self.frames.len() <= 1 {
                    self.error(pos.clone(), "return statement outside function".to_string());
                }
                let value = expr.as_ref().map(|e| self.resolve_expr(e));
                out.push(RStatement::Return(value, pos.clone()));
            }
            Statement::Break(pos) => {
                let in_loop = self.frames.last().map(|f| f.loop_depth > 0).unwrap_or(false);
                if !in_loop {
                    self.error(pos.clone(), "break statement outside loop".to_string());
                }
                out.push(RStatement::Break(pos.clone()));
            }
            Statement::For { name, name_pos, iter, body, pos } => {
                let iter = self.resolve_expr(iter);
                // The loop variable lives in the body scope.
                let frame = &mut self.frames[self.current_frame_index()];
                frame.scopes.push(HashMap::new());
                let slot = self.declare(name, name_pos);
                self.frames[self.current_frame_index()].loop_depth += 1;
                let body = self.resolve_block(body, false);
                self.frames[self.current_frame_index()].loop_depth -= 1;
                let frame = &mut self.frames[self.current_frame_index()];
                frame.scopes.pop();
                out.push(RStatement::For { slot, iter, body, pos: pos.clone() });
            }
            Statement::While { cond, body, pos } => {
                let cond = self.resolve_expr(cond);
                self.names[self.current_frame_index()].loop_depth += 1;
                let body = self.resolve_block(body, true);
                self.frames[self.current_frame_index()].loop_depth -= 1;
                out.push(RStatement::While { cond, body, pos: pos.clone() });
            }
            Statement::IllFormed => out.push(RStatement::IllFormed),
        }
    }

    fn resolve_expr(&mut self, expr: &Expr) -> RExpr {
        let resolved_kind = match &expr.kind {
            ExprKind::Nil => RExprKind::Nil,
            ExprKind::Bool(b) => RExprKind::Bool(*b),
            ExprKind::Int(i) => RExprKind::Int(*i),
            ExprKind::Float(x) => RExprKind::Float(*x),
            ExprKind::Str(bytes) => RExprKind::Str(bytes.clone()),
            ExprKind::Char(b) => RExprKind::Char(*b),
            ExprKind::Var(name) => match self.lookup(name) {
                Some(decl) => RExprKind::Slot(decl.slot),
