                    } else {
                        seen.push(&pair.key);
                    }
                }
                RExprKind::Dict(pairs.iter().map(|p| (p.key.clone(), self.resolve_expr(&p.value))).collect())
            }
            ExprKind::Function(fun) => {
                let function = self.resolve_function(fun, expr.pos.clone());
                RExprKind::FunctionValue(std::sync::Arc::new(function))
            }
            ExprKind::If(if_expr) => {
                let cond = self.resolve_expr(&if_expr.cond);
                let then_block = self.resolve_block(&if_expr.then_block, true);
                let else_block = if_expr.else_block.as_ref().map(|block| self.resolve_block(block, true));
                RExprKind::If(Box::new(RIfExpr { cond, then_block, else_block }))
            }
            ExprKind::Command(block) => RExprKind::Command(Box::new(self.resolve_command_block(block))),
            ExprKind::Unary(op, inner) => RExprKind::Unary(*op, Box::new(self.resolve_expr(inner))),
            ExprKind::Binary(op, left, right, op_pos) => RExprKind::Binary(
                *op,
                Box::new(self.resolve_expr(left)),
                Box::new(self.resolve_expr(right)),
                op_pos.clone(),
