            }).collect(),
            ill_formed_block: block.ill_formed_block,
        }
    }

    fn resolve_command(&mut self, command: &Command) -> CommandR {
        CommandR {
            program: self.resolve_template(&command.program),
            args: command.args.iter().map(|t| self.resolve_template(t)).collect(),
            redirects: command.redirects.iter().map(|redirect| RedirectR {
