            question: command.question,
            pos: command.pos.clone(),
            ill_formed_program: command.ill_formed_program,
        }
    }

    fn resolve_template(&mut self, template: &Template) -> TemplateR {
        TemplateR {
            segments: template.segments.iter().map(|segment| match segment {
                TemplateSegment::Literal { bytes, glob } => TemplateSegmentR::Literal { bytes: bytes.clone(), glob: *glob },
                TemplateSegment::Var { name, pos, invalid } => {
