            RExprKind::Call(callee, args, lparen_pos) => {
                // Determine self from an index/field callee.
                let (function, self_value) = match &callee.kind {
                    RExprKind::Index(base, index) => {
                        let base_value = self.eval_expr(base, env)?;
                        let index_value = self.eval_expr(index, env)?;
                        let function = self.index_value(base_value.clone(), index_value, base.pos.clone(), index.pos.clone())?;
                        (function, base_value)
                    }
                    RExprKind::Field(base, name, name_pos) => {
                        let base_value = self.eval_expr(base, env)?;
                        let function = self.index_value(base_value.clone(), Value::Str(name.clone()), base.pos.clone(), name_pos.clone())?;
                        (function, base_value)
                    }
                    _ => (self.eval_expr(callee, env)?, Value::Nil),
                };
                let mut values = Vec::new();
                for arg in args { values.push(self.eval_expr(arg, env)?); }
                self.call_value(function, values, self_value, lparen_pos.clone(), Some(callee.pos.clone()), env)
            }
            RExprKind::Index(base, index) => {
                let base_value = self.eval_expr(base, env)?;
                let index_value = self.eval_expr(index, env)?;
                self.index_value(base_value, index_value, base.pos.clone(), index.pos.clone())
            }
            RExprKind::Field(base, name, name_pos) => {
                let base_value = self.eval_expr(base, env)?;
                self.index_value(base_value, Value::Str(name.clone()), base.pos.clone(), name_pos.clone())
            }
            RExprKind::IllFormed => Ok(Value::Nil),
        }
    }

    fn eval_binary(&mut self, op: BinOp, left: &RExpr, right: &RExpr, op_pos: &SourcePos, env: &Env) -> EvalResult<Value> {
        match op {
            BinOp::And => {
                let left_value = self.eval_expr(left, env)?;
                let left_bool = match &left_value {
                    Value::Bool(b) => *b,
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected bool", left_value.display())),
                };
                if !left_bool { return Ok(Value::Bool(false)); }
                let right_value = self.eval_expr(right, env)?;
                return match &right_value {
                    Value::Bool(b) => Ok(Value::Bool(*b)),
                    _ => panic(right.pos.clone(), format!("value ({}) has unexpected type, expected bool", right_value.display())),
                };
            }
            BinOp::Or => {
                let left_value = self.eval_expr(left, env)?;
                let left_bool = match &left_value {
                    Value::Bool(b) => *b,
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected bool", left_value.display())),
                };
                if left_bool { return Ok(Value::Bool(true)); }
                let right_value = self.eval_expr(right, env)?;
                return match &right_value {
                    Value::Bool(b) => Ok(Value::Bool(*b)),
                    _ => panic(right.pos.clone(), format!("value ({}) has unexpected type, expected bool", right_value.display())),
                };
            }
            _ => {}
        }

        let left_value = self.eval_expr(left, env)?;
        let right_value = self.eval_expr(right, env)?;

        match op {
            BinOp::Eq => return Ok(Value::Bool(left_value.equals(&right_value))),
            BinOp::NotEq => return Ok(Value::Bool(!left_value.equals(&right_value))),
            BinOp::Concat => {
                let left_bytes = match &left_value {
                    Value::Str(bytes) => bytes.clone(),
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected string", left_value.display())),
                };
                let right_bytes = match &right_value {
                    Value::Str(bytes) => bytes.clone(),
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected string", right_value.display())),
                };
                let mut out = left_bytes;
                out.extend_from_slice(&right_bytes);
                return Ok(Value::Str(out));
            }
            BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                return self.eval_comparison(op, left_value, right_value, left, right);
            }
            _ => {}
        }

        // Arithmetic.
        match &left_value {
            Value::Int(a) => {
                let b = match &right_value {
                    Value::Int(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected int", right_value.display())),
                };
                let result = match op {
                    BinOp::Add => a.checked_add(b),
                    BinOp::Sub => a.checked_sub(b),
                    BinOp::Mul => a.checked_mul(b),
                    BinOp::Div => {
                        if b == 0 || (*a == i64::MIN && b == -1) {
                            return panic(op_pos.clone(), "division by zero".to_string());
                        }
                        a.checked_div(b)
                    }
                    BinOp::Mod => {
                        if b == 0 || (*a == i64::MIN && b == -1) {
                            return panic(op_pos.clone(), "division by zero".to_string());
                        }
                        // Rust % -- sign of the dividend.
                        Some(a % b)
                    }
                    _ => unreachable!(),
                };
                match result {
                    Some(value) => Ok(Value::Int(value)),
                    None => panic(op_pos.clone(), "integer overflow".to_string()),
                }
            }
            Value::Float(a) => {
                let b = match &right_value {
                    Value::Float(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected float", right_value.display())),
                };
                let value = match op {
                    BinOp::Add => a + b,
                    BinOp::Sub => a - b,
                    BinOp::Mul => a * b,
                    BinOp::Div => a / b,
                    BinOp::Mod => a % b,
                    _ => unreachable!(),
                };
                Ok(Value::Float(value))
            }
            _ => panic(left.pos.clone(), format!("value ({}) has unexpected type, expected int or float", left_value.display())),
        }
    }

    fn eval_comparison(&mut self, op: BinOp, left_value: Value, right_value: Value, left: &RExpr, right: &RExpr) -> EvalResult<Value> {
        let ordering = match (&left_value, &right_value) {
            (Value::Int(a), _) => {
                let b = match &right_value {
                    Value::Int(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected int", right_value.display())),
                };
                a.cmp(&b)
            }
            (Value::Float(a), _) => {
                let b = match &right_value {
                    Value::Float(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected float", right_value.display())),
                };
                a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::Char(a), _) => {
                let b = match &right_value {
                    Value::Char(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected char", right_value.display())),
                };
                a.cmp(&b)
            }
            (Value::Str(a), _) => {
                let b = match &right_value {
                    Value::Str(b) => b.clone(),
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected string", right_value.display())),
                };
                a.cmp(&b)
            }
            _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected int, float, byte or string", left_value.display())),
        };
        let result = match op {
            BinOp::Lt => ordering == std::cmp::Ordering::Less,
            BinOp::LtEq => ordering != std::cmp::Ordering::Greater,
            BinOp::Gt => ordering == std::cmp::Ordering::Greater,
            BinOp::GtEq => ordering != std::cmp::Ordering::Less,
            _ => unreachable!(),
        };
        Ok(Value::Bool(result))
    }

    pub fn index_value(&mut self, base: Value, index: Value, base_pos: SourcePos, index_pos: SourcePos) -> EvalResult<Value> {
        match &base {
            Value::Str(bytes) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                if i < 0 || i as usize >= bytes.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                Ok(Value::Char(bytes[i as usize]))
            }
            Value::Array(items) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                let items = items.lock().unwrap();
                if i < 0 || i as usize >= items.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                Ok(items[i as usize].clone())
            }
            Value::Dict(map) => {
                let key = DictKey::from_value(&index);
                let map = map.lock().unwrap();
                match map.get(&key) {
                    Some(entry) => Ok(entry.value.clone()),
                    None => panic(index_pos, format!("index ({}) out of bounds", index.display())),
                }
            }
            Value::Error(error) => {
                if let Value::Str(bytes) = &index {
                    if bytes == b"description" {
                        return Ok(Value::Str(error.description.clone()));
                    }
                }
                panic(index_pos, format!("index ({}) out of bounds", index.display()))
            }
            _ => panic(base_pos, format!("value ({}) has unexpected type, expected string, array, dict or error", base.display())),
        }
    }

    pub fn assign_index(&mut self, base: Value, index: Value, value: Value, base_pos: SourcePos, index_pos: SourcePos) -> EvalResult<()> {
        match &base {
            Value::Array(items) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                let mut items = items.lock().unwrap();
                if i < 0 || i as usize >= items.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                items[i as usize] = value;
                Ok(())
            }
            Value::Dict(map) => {
                let key = DictKey::from_value(&index);
                let mut map = map.lock().unwrap();
                map.insert(key, crate::value::DictEntry { key: index, value });
                Ok(())
            }
            Value::Error(_) => panic(index_pos, format!("attempt to assign field ({}), which is readonly", index.display())),
            _ => panic(base_pos, format!("value ({}) has unexpected type, expected array, dict or error", base.display())),
        }
    }

    pub fn call_value(
        &mut self,
        function: Value,
        args: Vec<Value>,
        self_value: Value,
        call_pos: SourcePos,
        callee_pos: Option<SourcePos>,
        env: &Env,
    ) -> EvalResult<Value> {
        let function_data = match &function {
            Value::Function(data) => data.clone(),
            _ => {
                let pos = callee_pos.unwrap_or_else(|| call_pos.clone());
                return panic(pos, format!("attempt to call ({}), which is not a function", function.display()));
            }
        };
        match &function_data.kind {
            FunctionKind::User { def, captured, source_path, .. } => {
                if args.len() != def.param_count {
                    return panic(call_pos, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), def.param_count));
                }
                let mut cells: Vec<Cell> = Vec::new();
                for decl in &def.slots {
                    match decl {
                        SlotDecl::Auto => cells.push(new_cell(Value::Nil)),
                        SlotDecl::AutoSelf => cells.push(new_cell(self_value.clone())),
                        SlotDecl::Capture(parent) => cells.push(captured.get(*parent).cloned().unwrap_or_else(|| new_cell(Value::Nil))),
                    }
                }
                for (index, arg) in args.into_iter().enumerate() {
                    if index < cells.len() {
                        *cells[index].lock().unwrap() = arg;
                    }
                }
                let call_env = Env { cells, source_path: source_path.clone() };
                match self.exec_block(&def.body, &call_env) {
                    Ok(value) => Ok(value),
                    Err(Signal::Return(value)) => Ok(value),
                    Err(other) => Err(other),
                }
            }
            FunctionKind::Native { native, .. } => self.call_native(native, function.clone(), args, self_value, call_pos, env),
        }
    }

    fn eval_command_block(&mut self, block: &CommandBlockR, env: &Env) -> EvalResult<Value> {
        match block.kind {
            CommandBlockKind::Plain => crate::commands::execute_command_block(self, block, crate::commands::CommandMode::Plain, env),
            CommandBlockKind::Capture => crate::commands::execute_command_block(self, block, crate::commands::CommandMode::Capture, env),
            CommandBlockKind::Async => {
                let block = block.clone();
                let env_clone = env.clone();
                let runtime = self.runtime.clone();
                let shared = Arc::new(JoinShared { state: Mutex::new(JoinState::Taken) });
                let shared_for_thread = shared.clone();
                let handle = std::thread::spawn(move || {
                    let mut executor = Executor::new(runtime);
                    let env = env_clone;
                    match crate::commands::execute_command_block(&mut executor, &block, crate::commands::CommandMode::Plain, &env) {
                        Ok(value) => Ok(value),
                        Err(Signal::Panic(p)) => Err(JoinError::Panic(p)),
                        Err(Signal::Exit(code)) => Err(JoinError::Exit(code)),
                        Err(Signal::Return(value)) => Ok(value),
                        Err(Signal::Break) => Ok(Value::Nil),
                    }
                });
                *shared.state.lock().unwrap() = JoinState::Running(handle);
                let join_function = Value::Function(Arc::new(FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::Native {
                        name: "<command>.join".to_string(),
                        native: NativeKind::Join(shared),
                    },
                }));
                let dict = Value::dict_from_entries(vec![(Value::Str(b"join".to_vec()), join_function)]);
                Ok(dict)
            }
        }
    }
}

fn expect_index_int(index: &Value, pos: SourcePos) -> EvalResult<i64> {
    match index {
        Value::Int(i) => Ok(*i),
        _ => panic(pos, format!("value ({}) has unexpected type, expected int", index.display())),
    }
}

pub fn expect_type<T>(pos: SourcePos, message: String) -> EvalResult<T> { panic(pos, message) }

pub fn type_error(pos: SourcePos, value: &Value, expected: &str) -> Panic {
    Panic::new(pos, format!("value ({}) has unexpected type, expected {}", value.display(), expected))
}

pub fn arity_error(pos: SourcePos, supplied: usize, expected: usize) -> Panic {
    Panic::new(pos, format!("incorrect amount of function parameters -- supplied {}, expected {}", supplied, expected))
}

pub fn check_arity(pos: &SourcePos, args: &[Value], expected: usize) -> EvalResult<()> {
    if args.len() != expected {
        return Err(Signal::Panic(arity_error(pos.clone(), args.len(), expected)));
    }
    Ok(())
}

pub fn stdout_write(bytes: &[u8]) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(bytes);
}

pub fn stdout_flush() {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.flush();
}

