#[derive(Clone)]
pub struct Panic {
    pub pos: SourcePos,
    pub message: String,
}

impl Panic {
    pub fn new(pos: SourcePos, message: impl Into<String>) -> Self { Self { pos, message: message.into() } }
    pub fn format(&self) -> String { format!("Panic in {}: {}", self.pos, self.message) }
}

pub enum Signal {
    Panic(Panic),
    Exit(i32),
    Return(Value),
    Break,
}

pub type EvalResult<T> = Result<T, Signal>;

fn panic<T>(pos: SourcePos, message: impl Into<String>) -> EvalResult<T> {
    Err(Signal::Panic(Panic::new(pos, message)))
}

pub struct Runtime {
    pub std: Value,
    pub script_args: Vec<Value>,
    pub rng: Mutex<ChaCha8Rng>,
}

impl Runtime {
    pub fn new(script_args: Vec<Vec<u8>>) -> Runtime {
        let std = create_std();
        Runtime {
            std,
            script_args: script_args.into_iter().map(Value::Str).collect(),
            rng: Mutex::new(ChaCha8Rng::from_entropy()),
        }
    }
}

#[derive(Clone)]
pub struct Env {
    pub cells: Vec<Cell>,
    pub source_path: Rc<String>,
}

pub struct Executor {
    pub runtime: Arc<Runtime>,
}

#[derive(Clone)]
pub enum NumberValue { Int(i64), Float(f64) }

pub struct RangeState {
    pub current: NumberValue,
    pub end: NumberValue,
    pub step: NumberValue,
}

pub enum IterCollection {
    Str(Vec<u8>),
    Array(Vec<Value>),
    Dict(Vec<(Value, Value)>),
}

pub struct IterState {
    pub collection: IterCollection,
    pub index: usize,
}

pub struct JoinShared {
    pub state: Mutex<JoinState>,
}

pub enum JoinState {
    Running(std::thread::JoinHandle<Result<Value, JoinError>>),
    Taken,
}

#[derive(Clone)]
pub enum JoinError {
    Panic(Panic),
    Exit(i32),
}

impl Executor {
    pub fn new(runtime: Arc<Runtime>) -> Self { Self { runtime } }

    pub fn execute_program(&mut self, program: &ResolvedProgram, source_path: Rc<String>) -> EvalResult<Value> {
        let env = self.frame_for_function(&program.function, Vec::new(), Value::Nil, None, source_path.clone());
        // slot 0 is std
        if !env.cells.is_empty() {
            *env.cells[0].lock().unwrap() = self.runtime.std.clone();
        }
        self.exec_block(&program.function.body, &env)
    }

    fn frame_for_function(
        &self,
        def: &ResolvedFunction,
        args: Vec<Value>,
        self_value: Value,
        closure: Option<&FunctionData>,
        source_path: Rc<String>,
    ) -> Env {
        let mut cells: Vec<Cell> = Vec::new();
        for decl in &def.slots {
            match decl {
                SlotDecl::Auto => cells.push(new_cell(Value::Nil)),
                SlotDecl::AutoSelf => cells.push(new_cell(self_value.clone())),
                SlotDecl::Capture(parent) => {
                    let cell = closure
                        .and_then(|fun| match &fun.kind {
                            FunctionKind::User { captured, .. } => captured.get(*parent).cloned(),
                            _ => None,
                        })
                        .unwrap_or_else(|| new_cell(Value::Nil));
                    cells.push(cell);
                }
            }
        }
        for (index, arg) in args.into_iter().enumerate() {
            if index < cells.len() {
                *cells[index].lock().unwrap() = arg;
            }
        }
        Env { cells, source_path }
    }

    pub fn exec_block(&mut self, block: &[RStatement], env: &Env) -> EvalResult<Value> {
        let mut last = Value::Nil;
        for statement in block {
            last = self.exec_stmt(statement, env)?;
        }
        Ok(last)
    }

    fn exec_stmt(&mut self, stmt: &RStatement, env: &Env) -> EvalResult<Value> {
        match stmt {
            RStatement::LetSlot { slot, value } => {
                let value = self.eval_expr(value, env)?;
                if let Some(cell) = env.cells.get(*slot) {
                    *cell.lock().unwrap() = value;
                }
                Ok(Value::Nil)
            }
            RStatement::Assign { target, value, .. } => {
                let value = self.eval_expr(value, env)?;
                self.assign_target(target, value, env)?;
                Ok(Value::Nil)
            }
            RStatement::Expr(expr) => self.eval_expr(expr, env),
            RStatement::Return(expr, _) => {
                let value = match expr {
                    Some(expr) => self.eval_expr(expr, env)?,
                    None => Value::Nil,
                };
                Err(Signal::Return(value))
            }
            RStatement::Break(_) => Err(Signal::Break),
            RStatement::While { cond, body, .. } => {
                loop {
                    let condition = self.eval_expr(cond, env)?;
                    let flag = match &condition {
                        Value::Bool(b) => *b,
                        _ => return panic(cond.pos.clone(), format!("condition ({}) is not a boolean", condition.display())),
                    };
                    if !flag { break; }
                    match self.exec_block(body, env) {
                        Ok(_) => {}
                        Err(Signal::Break) => break,
                        Err(other) => return Err(other),
                    }
                }
                Ok(Value::Nil)
            }
            RStatement::For { slot, iter, body, .. } => {
                let iterator = self.eval_expr(iter, env)?;
                if !matches!(iterator, Value::Function(_)) {
                    return panic(iter.pos.clone(), format!("value ({}) has unexpected type, expected function", iterator.display()));
                }
                loop {
                    let iteration = self.call_value(iterator.clone(), Vec::new(), Value::Nil, iter.pos.clone(), Some(iter.pos.clone()), env)?;
                    let dict = match &iteration {
                        Value::Dict(_) => iteration.clone(),
                        _ => return panic(iter.pos.clone(), format!("value ({}) has unexpected type, expected dict", iteration.display())),
                    };
                    let finished_value = self.index_value(dict.clone(), Value::Str(b"finished".to_vec()), iter.pos.clone(), iter.pos.clone())?;
                    let finished = match &finished_value {
                        Value::Bool(b) => *b,
                        _ => return panic(iter.pos.clone(), format!("value ({}) has unexpected type, expected bool", finished_value.display())),
                    };
                    if finished { break; }
                    let item = self.index_value(dict, Value::Str(b"value".to_vec()), iter.pos.clone(), iter.pos.clone())?;
                    if let Some(cell) = env.cells.get(*slot) {
                        *cell.lock().unwrap() = item;
                    }
                    match self.exec_block(body, env) {
                        Ok(_) => {}
                        Err(Signal::Break) => break,
                        Err(other) => return Err(other),
                    }
                }
                Ok(Value::Nil)
            }
            RStatement::IllFormed => Ok(Value::Nil),
        }
    }

    fn assign_target(&mut self, target: &RExpr, value: Value, env: &Env) -> EvalResult<()> {
        match &target.kind {
            RExprKind::Slot(slot) => {
                if let Some(cell) = env.cells.get(*slot) {
                    *cell.lock().unwrap() = value;
                }
                Ok(())
            }
            RExprKind::Index(base, index) => {
                let base_value = self.eval_expr(base, env)?;
                let index_value = self.eval_expr(index, env)?;
                self.assign_index(base_value, index_value, value, base.pos.clone(), index.pos.clone())
            }
            RExprKind::Field(base, name, name_pos) => {
                let base_value = self.eval_expr(base, env)?;
                self.assign_index(base_value, Value::Str(name.clone()), value, base.pos.clone(), name_pos.clone())
            }
            _ => Ok(()),
        }
    }

    pub fn eval_expr(&mut self, expr: &RExpr, env: &Env) -> EvalResult<Value> {
        match &expr.kind {
            RExprKind::Nil => Ok(Value::Nil),
            RExprKind::Bool(value) => Ok(Value::Bool(*value)),
            RExprKind::Int(value) => Ok(Value::Int(*value)),
            RExprKind::Float(value) => Ok(Value::Float(*value)),
            RExprKind::Str(bytes) => Ok(Value::Str(bytes.clone())),
            RExprKind::Char(byte) => Ok(Value::Char(*byte)),
            RExprKind::Slot(slot) => Ok(env.cells.get(*slot).map(|cell| cell.lock().unwrap().clone()).unwrap_or(Value::Nil)),
            RExprKind::Array(items) => {
                let mut values = Vec::new();
                for item in items { values.push(self.eval_expr(item, env)?); }
                Ok(Value::new_array(values))
            }
            RExprKind::Dict(pairs) => {
                let mut entries = Vec::new();
                for (key, value) in pairs {
                    let value = self.eval_expr(value, env)?;
                    entries.push((Value::Str(key.clone()), value));
                }
                Ok(Value::dict_from_entries(entries))
            }
            RExprKind::FunctionValue(def) => {
                let fun = FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::User {
                        def: def.clone(),
                        captured: env.cells.clone(),
                        source_path: env.source_path.clone(),
                        display_pos: def.display_pos.clone(),
                    },
                };
                Ok(Value::Function(Arc::new(fun)))
            }
            RExprKind::Function(_) => Ok(Value::Nil),
            RExprKind::If(if_expr) => {
                let condition = self.eval_expr(&if_expr.cond, env)?;
                let flag = match &condition {
                    Value::Bool(b) => *b,
                    _ => return panic(if_expr.cond.pos.clone(), format!("condition ({}) is not a boolean", condition.display())),
                };
                if flag {
                    self.exec_block(&if_expr.then_block, env)
                } else if let Some(else_block) = &if_expr.else_block {
                    self.exec_block(else_block, env)
                } else {
                    Ok(Value::Nil)
                }
            }
            RExprKind::Command(block) => self.eval_command_block(block, env),
            RExprKind::Unary(op, inner) => {
                let value = self.eval_expr(inner, env)?;
                match op {
                    UnOp::Neg => match value {
                        Value::Int(i) => Ok(Value::Int(i.wrapping_neg())),
                        Value::Float(x) => Ok(Value::Float(-x)),
                        _ => panic(inner.pos.clone(), format!("value ({}) has unexpected type, expected int or float", value.display())),
                    },
                    UnOp::Not => match value {
                        Value::Bool(b) => Ok(Value::Bool(!b)),
                        _ => panic(inner.pos.clone(), format!("value ({}) has unexpected type, expected bool", value.display())),
                    },
                }
            }
            RExprKind::Binary(op, left, right, op_pos) => self.eval_binary(*op, left, right, op_pos, env),
            RExprKind::Call(callee, args, lparen_pos) => {
                // Determine self from an index/field callee.
                let (function, self_value) = match &callee.kind {
                    RExprKind::Index(base, index) => {
                        let base_value = self.eval_expr(base, env)?;
                        let index_value = self.eval_expr(index, env)?;
                        let function = self.index_value(base_value.clone(), index_value, base.pos.clone(), index.pos.clone())?;
                        (function, base_value)
                    }
                    RExprKind::Field(base, name, name_pos) => {
                        let base_value = self.eval_expr(base, env)?;
                        let function = self.index_value(base_value.clone(), Value::Str(name.clone()), base.pos.clone(), name_pos.clone())?;
                        (function, base_value)
                    }
                    _ => (self.eval_expr(callee, env)?, Value::Nil),
                };
                let mut values = Vec::new();
                for arg in args { values.push(self.eval_expr(arg, env)?); }
                self.call_value(function, values, self_value, lparen_pos.clone(), Some(callee.pos.clone()), env)
            }
            RExprKind::Index(base, index) => {
                let base_value = self.eval_expr(base, env)?;
                let index_value = self.eval_expr(index, env)?;
                self.index_value(base_value, index_value, base.pos.clone(), index.pos.clone())
            }
            RExprKind::Field(base, name, name_pos) => {
                let base_value = self.eval_expr(base, env)?;
                self.index_value(base_value, Value::Str(name.clone()), base.pos.clone(), name_pos.clone())
            }
            RExprKind::IllFormed => Ok(Value::Nil),
        }
    }

    fn eval_binary(&mut self, op: BinOp, left: &RExpr, right: &RExpr, op_pos: &SourcePos, env: &Env) -> EvalResult<Value> {
        match op {
            BinOp::And => {
                let left_value = self.eval_expr(left, env)?;
                let left_bool = match &left_value {
                    Value::Bool(b) => *b,
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected bool", left_value.display())),
                };
                if !left_bool { return Ok(Value::Bool(false)); }
                let right_value = self.eval_expr(right, env)?;
                return match &right_value {
                    Value::Bool(b) => Ok(Value::Bool(*b)),
                    _ => panic(right.pos.clone(), format!("value ({}) has unexpected type, expected bool", right_value.display())),
                };
            }
            BinOp::Or => {
                let left_value = self.eval_expr(left, env)?;
                let left_bool = match &left_value {
                    Value::Bool(b) => *b,
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected bool", left_value.display())),
                };
                if left_bool { return Ok(Value::Bool(true)); }
                let right_value = self.eval_expr(right, env)?;
                return match &right_value {
                    Value::Bool(b) => Ok(Value::Bool(*b)),
                    _ => panic(right.pos.clone(), format!("value ({}) has unexpected type, expected bool", right_value.display())),
                };
            }
            _ => {}
        }

        let left_value = self.eval_expr(left, env)?;
        let right_value = self.eval_expr(right, env)?;

        match op {
            BinOp::Eq => return Ok(Value::Bool(left_value.equals(&right_value))),
            BinOp::NotEq => return Ok(Value::Bool(!left_value.equals(&right_value))),
            BinOp::Concat => {
                let left_bytes = match &left_value {
                    Value::Str(bytes) => bytes.clone(),
                    _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected string", left_value.display())),
                };
                let right_bytes = match &right_value {
                    Value::Str(bytes) => bytes.clone(),
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected string", right_value.display())),
                };
                let mut out = left_bytes;
                out.extend_from_slice(&right_bytes);
                return Ok(Value::Str(out));
            }
            BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                return self.eval_comparison(op, left_value, right_value, left, right);
            }
            _ => {}
        }

        // Arithmetic.
        match &left_value {
            Value::Int(a) => {
                let b = match &right_value {
                    Value::Int(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected int", right_value.display())),
                };
                let result = match op {
                    BinOp::Add => a.checked_add(b),
                    BinOp::Sub => a.checked_sub(b),
                    BinOp::Mul => a.checked_mul(b),
                    BinOp::Div => {
                        if b == 0 || (*a == i64::MIN && b == -1) {
                            return panic(op_pos.clone(), "division by zero".to_string());
                        }
                        a.checked_div(b)
                    }
                    BinOp::Mod => {
                        if b == 0 || (*a == i64::MIN && b == -1) {
                            return panic(op_pos.clone(), "division by zero".to_string());
                        }
                        // Rust % -- sign of the dividend.
                        Some(a % b)
                    }
                    _ => unreachable!(),
                };
                match result {
                    Some(value) => Ok(Value::Int(value)),
                    None => panic(op_pos.clone(), "integer overflow".to_string()),
                }
            }
            Value::Float(a) => {
                let b = match &right_value {
                    Value::Float(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected float", right_value.display())),
                };
                let value = match op {
                    BinOp::Add => a + b,
                    BinOp::Sub => a - b,
                    BinOp::Mul => a * b,
                    BinOp::Div => a / b,
                    BinOp::Mod => a % b,
                    _ => unreachable!(),
                };
                Ok(Value::Float(value))
            }
            _ => panic(left.pos.clone(), format!("value ({}) has unexpected type, expected int or float", left_value.display())),
        }
    }

    fn eval_comparison(&mut self, op: BinOp, left_value: Value, right_value: Value, left: &RExpr, right: &RExpr) -> EvalResult<Value> {
        let ordering = match (&left_value, &right_value) {
            (Value::Int(a), _) => {
                let b = match &right_value {
                    Value::Int(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected int", right_value.display())),
                };
                a.cmp(&b)
            }
            (Value::Float(a), _) => {
                let b = match &right_value {
                    Value::Float(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected float", right_value.display())),
                };
                a.partial_cmp(&b).unwrap_or(std::cmp::Ordering::Equal)
            }
            (Value::Char(a), _) => {
                let b = match &right_value {
                    Value::Char(b) => *b,
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected char", right_value.display())),
                };
                a.cmp(&b)
            }
            (Value::Str(a), _) => {
                let b = match &right_value {
                    Value::Str(b) => b.clone(),
                    _ => return panic(right.pos.clone(), format!("value ({}) has unexpected type, expected string", right_value.display())),
                };
                a.cmp(&b)
            }
            _ => return panic(left.pos.clone(), format!("value ({}) has unexpected type, expected int, float, byte or string", left_value.display())),
        };
        let result = match op {
            BinOp::Lt => ordering == std::cmp::Ordering::Less,
            BinOp::LtEq => ordering != std::cmp::Ordering::Greater,
            BinOp::Gt => ordering == std::cmp::Ordering::Greater,
            BinOp::GtEq => ordering != std::cmp::Ordering::Less,
            _ => unreachable!(),
        };
        Ok(Value::Bool(result))
    }

    pub fn index_value(&mut self, base: Value, index: Value, base_pos: SourcePos, index_pos: SourcePos) -> EvalResult<Value> {
        match &base {
            Value::Str(bytes) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                if i < 0 || i as usize >= bytes.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                Ok(Value::Char(bytes[i as usize]))
            }
            Value::Array(items) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                let items = items.lock().unwrap();
                if i < 0 || i as usize >= items.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                Ok(items[i as usize].clone())
            }
            Value::Dict(map) => {
                let key = DictKey::from_value(&index);
                let map = map.lock().unwrap();
                match map.get(&key) {
                    Some(entry) => Ok(entry.value.clone()),
                    None => panic(index_pos, format!("index ({}) out of bounds", index.display())),
                }
            }
            Value::Error(error) => {
                if let Value::Str(bytes) = &index {
                    if bytes == b"description" {
                        return Ok(Value::Str(error.description.clone()));
                    }
                }
                panic(index_pos, format!("index ({}) out of bounds", index.display()))
            }
            _ => panic(base_pos, format!("value ({}) has unexpected type, expected string, array, dict or error", base.display())),
        }
    }

    pub fn assign_index(&mut self, base: Value, index: Value, value: Value, base_pos: SourcePos, index_pos: SourcePos) -> EvalResult<()> {
        match &base {
            Value::Array(items) => {
                let i = expect_index_int(&index, index_pos.clone())?;
                let mut items = items.lock().unwrap();
                if i < 0 || i as usize >= items.len() {
                    return panic(index_pos, format!("index ({}) out of bounds", index.display()));
                }
                items[i as usize] = value;
                Ok(())
            }
            Value::Dict(map) => {
                let key = DictKey::from_value(&index);
                let mut map = map.lock().unwrap();
                map.insert(key, crate::value::DictEntry { key: index, value });
                Ok(())
            }
            Value::Error(_) => panic(index_pos, format!("attempt to assign field ({}), which is readonly", index.display())),
            _ => panic(base_pos, format!("value ({}) has unexpected type, expected array, dict or error", base.display())),
        }
    }

    pub fn call_value(
        &mut self,
        function: Value,
        args: Vec<Value>,
        self_value: Value,
        call_pos: SourcePos,
        callee_pos: Option<SourcePos>,
        env: &Env,
    ) -> EvalResult<Value> {
        let function_data = match &function {
            Value::Function(data) => data.clone(),
            _ => {
                let pos = callee_pos.unwrap_or_else(|| call_pos.clone());
                return panic(pos, format!("attempt to call ({}), which is not a function", function.display()));
            }
        };
        match &function_data.kind {
            FunctionKind::User { def, captured, source_path, .. } => {
                if args.len() != def.param_count {
                    return panic(call_pos, format!("incorrect amount of function parameters -- supplied {}, expected {}", args.len(), def.param_count));
                }
                let mut cells: Vec<Cell> = Vec::new();
                for decl in &def.slots {
                    match decl {
                        SlotDecl::Auto => cells.push(new_cell(Value::Nil)),
                        SlotDecl::AutoSelf => cells.push(new_cell(self_value.clone())),
                        SlotDecl::Capture(parent) => cells.push(captured.get(*parent).cloned().unwrap_or_else(|| new_cell(Value::Nil))),
                    }
                }
                for (index, arg) in args.into_iter().enumerate() {
                    if index < cells.len() {
                        *cells[index].lock().unwrap() = arg;
                    }
                }
                let call_env = Env { cells, source_path: source_path.clone() };
                match self.exec_block(&def.body, &call_env) {
                    Ok(value) => Ok(value),
                    Err(Signal::Return(value)) => Ok(value),
                    Err(other) => Err(other),
                }
            }
            FunctionKind::Native { native, .. } => self.call_native(native, function.clone(), args, self_value, call_pos, env),
        }
    }

    fn eval_command_block(&mut self, block: &CommandBlockR, env: &Env) -> EvalResult<Value> {
        match block.kind {
            CommandBlockKind::Plain => crate::commands::execute_command_block(self, block, crate::commands::CommandMode::Plain, env),
            CommandBlockKind::Capture => crate::commands::execute_command_block(self, block, crate::commands::CommandMode::Capture, env),
            CommandBlockKind::Async => {
                let block = block.clone();
                let env_clone = env.clone();
                let runtime = self.runtime.clone();
                let shared = Arc::new(JoinShared { state: Mutex::new(JoinState::Taken) });
                let shared_for_thread = shared.clone();
                let handle = std::thread::spawn(move || {
                    let mut executor = Executor::new(runtime);
                    let env = env_clone;
                    match crate::commands::execute_command_block(&mut executor, &block, crate::commands::CommandMode::Plain, &env) {
                        Ok(value) => Ok(value),
                        Err(Signal::Panic(p)) => Err(JoinError::Panic(p)),
                        Err(Signal::Exit(code)) => Err(JoinError::Exit(code)),
                        Err(Signal::Return(value)) => Ok(value),
                        Err(Signal::Break) => Ok(Value::Nil),
                    }
                });
                *shared.state.lock().unwrap() = JoinState::Running(handle);
                let join_function = Value::Function(Arc::new(FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::Native {
                        name: "<command>.join".to_string(),
                        native: NativeKind::Join(shared),
                    },
                }));
                let dict = Value::dict_from_entries(vec![(Value::Str(b"join".to_vec()), join_function)]);
                Ok(dict)
            }
        }
    }
}

fn expect_index_int(index: &Value, pos: SourcePos) -> EvalResult<i64> {
    match index {
        Value::Int(i) => Ok(*i),
        _ => panic(pos, format!("value ({}) has unexpected type, expected int", index.display())),
    }
}

pub fn expect_type<T>(pos: SourcePos, message: String) -> EvalResult<T> { panic(pos, message) }

pub fn type_error(pos: SourcePos, value: &Value, expected: &str) -> Panic {
    Panic::new(pos, format!("value ({}) has unexpected type, expected {}", value.display(), expected))
}

pub fn arity_error(pos: SourcePos, supplied: usize, expected: usize) -> Panic {
    Panic::new(pos, format!("incorrect amount of function parameters -- supplied {}, expected {}", supplied, expected))
}

pub fn check_arity(pos: &SourcePos, args: &[Value], expected: usize) -> EvalResult<()> {
    if args.len() != expected {
        return Err(Signal::Panic(arity_error(pos.clone(), args.len(), expected)));
    }
    Ok(())
}

pub fn stdout_write(bytes: &[u8]) {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.write_all(bytes);
}

pub fn stdout_flush() {
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    let _ = lock.flush();
}

fn create_std() -> Value {
    let mut entries: Vec<(Value, Value)> = Vec::new();
    let mut add = |name: &str, function: StdFn, display_name: String| {
        let value = Value::Function(Arc::new(FunctionData {
            id: crate::value::next_function_id(),
            kind: FunctionKind::Native { name: display_name, native: NativeKind::Std(function) },
        }));
        entries.push((Value::Str(name.as_bytes().to_vec()), value));
    };
    add("print", StdFn::Print, "std.print".into());
    add("println", StdFn::Println, "std.println".into());
    add("args", StdFn::Args, "std.args".into());
    add("cwd", StdFn::Cwd, "std.cwd".into());
    add("cd", StdFn::Cd, "std.cd".into());
    add("env", StdFn::Env, "std.env".into());
    add("export", StdFn::Export, "std.export".into());
    add("read", StdFn::Read, "std.read".into());
    add("sleep", StdFn::Sleep, "std.sleep".into());
    add("exit", StdFn::Exit, "std.exit".into());
    add("panic", StdFn::Panic, "std.panic".into());
    add("assert", StdFn::Assert, "std.assert".into());
    add("error", StdFn::Error, "std.error".into());
    add("catch", StdFn::Catch, "std.catch".into());
    add("has_error", StdFn::HasError, "std.has_error".into());
    add("type", StdFn::Type, "std.type".into());
    add("len", StdFn::Len, "std.len".into());
    add("is_empty", StdFn::IsEmpty, "std.is_empty".into());
    add("push", StdFn::Push, "std.push".into());
    add("pop", StdFn::Pop, "std.pop".into());
    add("sort", StdFn::Sort, "std.sort".into());
    add("contains", StdFn::Contains, "std.contains".into());
    add("trim", StdFn::Trim, "std.trim".into());
    add("split", StdFn::Split, "std.split".into());
    add("replace", StdFn::Replace, "std.replace".into());
    add("substr", StdFn::Substr, "std.substr".into());
    add("bytes", StdFn::Bytes, "std.bytes".into());
    add("int", StdFn::Int, "std.int".into());
    add("float", StdFn::Float, "std.float".into());
    add("to_string", StdFn::ToString, "std.to_string".into());
    add("iter", StdFn::Iter, "std.iter".into());
    add("range", StdFn::Range, "std.range".into());
    add("rand", StdFn::Rand, "std.rand".into());
    add("randint", StdFn::RandInt, "std.randint".into());
    add("randseed", StdFn::RandSeed, "std.randseed".into());
    add("glob", StdFn::Glob, "std.glob".into());
    add("regex", StdFn::Regex, "std.regex".into());
    add("import", StdFn::Import, "std.import".into());
    add("bind", StdFn::Bind, "std.bind".into());
    add("typecheck", StdFn::Typecheck, "std.typecheck".into());
    add("try_typecheck", StdFn::TryTypecheck, "std.try_typecheck".into());

    let mut nested = |parent: &str, children: Vec<(&str, StdFn, String)>| {
        let dict = Value::dict_from_entries(
            children
                .into_iter()
                .map(|(name, function, display_name)| {
                    (
                        Value::Str(name.as_bytes().to_vec()),
                        Value::Function(Arc::new(FunctionData {
                            id: crate::value::next_function_id(),
                            kind: FunctionKind::Native { name: display_name, native: NativeKind::Std(function) },
                        })),
                    )
                })
                .collect(),
        );
        entries.push((Value::Str(parent.as_bytes().to_vec()), dict));
    };
    nested("json", vec![("encode", StdFn::JsonEncode, "std.json.encode".into()), ("decode", StdFn::JsonDecode, "std.json.decode".into())]);
    nested("base64", vec![("encode", StdFn::Base64Encode, "std.base64.encode".into()), ("decode", StdFn::Base64Decode, "std.base64.decode".into())]);
    nested("hex", vec![("encode", StdFn::HexEncode, "std.hex.encode".into()), ("decode", StdFn::HexDecode, "std.hex.decode".into())]);

    Value::dict_from_entries(entries)
}

pub fn value_to_string_bytes(value: &Value) -> Vec<u8> {
    match value {
        Value::Str(bytes) => bytes.clone(),
        Value::Char(byte) => vec![*byte],
        _ => value.display().into_bytes(),
    }
}

pub fn read_stdin_line() -> Vec<u8> {
    let stdin = std::io::stdin();
    let mut lock = stdin.lock();
    let mut bytes = Vec::new();
    let _ = lock.read_until(b'\n', &mut bytes);
    bytes
}

pub fn lossy(bytes: &[u8]) -> String { bytes_to_lossy_string(bytes) }
pub fn hash_map_snapshot(map: &Arc<Mutex<HashMap<DictKey, crate::value::DictEntry>>>) -> Vec<(Value, Value)> {
    let map = map.lock().unwrap();
    map.values().map(|entry| (entry.key.clone(), entry.value.clone())).collect()
}
