cat > src/stdlib.rs <<'EOF'
use crate::interp::*;
use crate::source::SourcePos;
use crate::value::{DictEntry, DictKey, ErrorData, FunctionData, FunctionKind, NativeKind, RegexKind, StdFn, Value};
use rand::Rng;
use rand::SeedableRng;
use rand_chacha::ChaCha8Rng;
use std::io::Write;
use std::sync::Arc;

fn err<T>(pos: &SourcePos, message: String) -> EvalResult<T> {
    Err(Signal::Panic(Panic::new(pos.clone(), message)))
}

fn unexpected<T>(pos: &SourcePos, value: &Value, expected: &str) -> EvalResult<T> {
    err(pos, format!("value ({}) has unexpected type, expected {}", value.display(), expected))
}

fn expect_string(pos: &SourcePos, value: &Value) -> EvalResult<Vec<u8>> {
    match value {
        Value::Str(bytes) => Ok(bytes.clone()),
        _ => unexpected(pos, value, "string"),
    }
}

fn expect_int(pos: &SourcePos, value: &Value) -> EvalResult<i64> {
    match value {
        Value::Int(value) => Ok(*value),
        _ => unexpected(pos, value, "int"),
    }
}

fn expect_function<'a>(pos: &SourcePos, value: &'a Value) -> EvalResult<&'a Arc<FunctionData>> {
    match value {
        Value::Function(data) => Ok(data),
        _ => unexpected(pos, value, "function"),
    }
}

fn make_error(description: Vec<u8>, cause: Value) -> Value {
    Value::Error(Arc::new(ErrorData { description, cause }))
}

impl Executor {
    pub fn call_native(
        &mut self,
        native: &NativeKind,
        _function: Value,
        args: Vec<Value>,
        self_value: Value,
        call_pos: SourcePos,
        env: &Env,
    ) -> EvalResult<Value> {
        match native {
            NativeKind::Std(std_fn) => self.call_std(*std_fn, args, self_value, call_pos, env),
            NativeKind::Range(state) => {
                check_arity(&call_pos, &args, 0)?;
                let mut state = state.lock().unwrap();
                let finished = match (&state.current, &state.end, &state.step) {
                    (NumberValue::Int(current), NumberValue::Int(end), NumberValue::Int(step)) => {
                        if (*step > 0 && current < end) || (*step < 0 && current > end) {
                            let value = *current;
                            state.current = NumberValue::Int(current.wrapping_add(*step));
                            return Ok(iteration_dict(Value::Int(value)));
                        }
                        true
                    }
                    _ => {
                        let current = as_f64(&state.current);
                        let end = as_f64(&state.end);
                        let step = as_f64(&state.step);
                        if (step > 0.0 && current < end) || (step < 0.0 && current > end) {
                            state.current = NumberValue::Float(current + step);
                            return Ok(iteration_dict(Value::Float(current)));
                        }
                        true
                    }
                };
                let _ = finished;
                Ok(finished_dict())
            }
            NativeKind::Iter(state) => {
                check_arity(&call_pos, &args, 0)?;
                let mut state = state.lock().unwrap();
                match &state.collection {
                    IterCollection::Str(bytes) => {
                        if state.index >= bytes.len() { return Ok(finished_dict()); }
                        let value = bytes[state.index];
                        state.index += 1;
                        Ok(iteration_dict(Value::Char(value)))
                    }
                    IterCollection::Array(items) => {
                        if state.index >= items.len() { return Ok(finished_dict()); }
                        let value = items[state.index].clone();
                        state.index += 1;
                        Ok(iteration_dict(value))
                    }
                    IterCollection::Dict(entries) => {
                        if state.index >= entries.len() { return Ok(finished_dict()); }
                        let (key, value) = entries[state.index].clone();
                        state.index += 1;
                        let pair = Value::dict_from_entries(vec![
                            (Value::Str(b"key".to_vec()), key),
                            (Value::Str(b"value".to_vec()), value),
                        ]);
                        Ok(iteration_dict(pair))
                    }
                }
            }
            NativeKind::Bind { target, bound_self } => {
                self.call_value(target.clone(), args, bound_self.clone(), call_pos, None, env)
            }
            NativeKind::RegexMethod { regex, kind } => match kind {
                RegexKind::Match => {
                    check_arity(&call_pos, &args, 1)?;
                    let text = expect_string(&call_pos, &args[0])?;
                    Ok(Value::Bool(regex.is_match(&crate::source::bytes_to_lossy_string(&text))))
                }
                RegexKind::Replace => {
                    check_arity(&call_pos, &args, 2)?;
                    let text = expect_string(&call_pos, &args[0])?;
                    let replacement = expect_string(&call_pos, &args[1])?;
                    let result = regex.replace_all(
                        &crate::source::bytes_to_lossy_string(&text),
                        crate::source::bytes_to_lossy_string(&replacement).as_str(),
                    );
                    Ok(Value::Str(result.into_owned().into_bytes()))
                }
                RegexKind::Split => {
                    check_arity(&call_pos, &args, 1)?;
                    let text = expect_string(&call_pos, &args[0])?;
                    let text_string = crate::source::bytes_to_lossy_string(&text);
                    let values = regex.split(&text_string).map(|part| Value::Str(part.as_bytes().to_vec())).collect();
                    Ok(Value::new_array(values))
                }
            },
            NativeKind::Join(shared) => {
                check_arity(&call_pos, &args, 0)?;
                let handle = {
                    let mut guard = shared.state.lock().unwrap();
                    match std::mem::replace(&mut *guard, JoinState::Taken) {
                        JoinState::Running(handle) => handle,
                        JoinState::Taken => {
                            return err(&call_pos, "attempt to call join more than once".to_string());
                        }
                    }
                };
                match handle.join() {
                    Ok(Ok(value)) => Ok(value),
                    Ok(Err(JoinError::Panic(p))) => Err(Signal::Panic(p)),
                    Ok(Err(JoinError::Exit(code))) => Err(Signal::Exit(code)),
                    Err(_) => err(&call_pos, "attempt to call join more than once".to_string()),
                }
            }
        }
    }

    fn call_std(
        &mut self,
        std_fn: StdFn,
        args: Vec<Value>,
        _self_value: Value,
        call_pos: SourcePos,
        env: &Env,
    ) -> EvalResult<Value> {
        match std_fn {
            StdFn::Print => {
                let mut out = Vec::new();
                for (index, arg) in args.iter().enumerate() {
                    if index > 0 { out.push(b'\t'); }
                    out.extend_from_slice(&arg.print_bytes());
                }
                stdout_write(&out);
                Ok(Value::Nil)
            }
            StdFn::Println => {
                let mut out = Vec::new();
                for (index, arg) in args.iter().enumerate() {
                    if index > 0 { out.push(b'\t'); }
                    out.extend_from_slice(&arg.print_bytes());
                }
                out.push(b'\n');
                stdout_write(&out);
                Ok(Value::Nil)
            }
            StdFn::Args => {
                check_arity(&call_pos, &args, 0)?;
                Ok(Value::new_array(self.runtime.script_args.clone()))
            }
            StdFn::Cwd => {
                check_arity(&call_pos, &args, 0)?;
                match std::env::current_dir() {
                    Ok(path) => Ok(Value::Str(path.as_os_str().as_encoded_bytes().to_vec())),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Nil)),
                }
            }
            StdFn::Cd => {
                check_arity(&call_pos, &args, 1)?;
                let path = expect_string(&call_pos, &args[0])?;
                match std::env::set_current_dir(std::path::Path::new(&crate::source::bytes_to_lossy_string(&path))) {
                    Ok(()) => Ok(Value::Nil),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Nil)),
                }
            }
            StdFn::Env => {
                check_arity(&call_pos, &args, 1)?;
                let name = expect_string(&call_pos, &args[0])?;
                match std::env::var_os(std::ffi::OsStr::from_bytes(&name)) {
                    Some(value) => Ok(Value::Str(value.as_encoded_bytes().to_vec())),
                    None => Ok(Value::Nil),
                }
            }
            StdFn::Export => {
                check_arity(&call_pos, &args, 2)?;
                let name = expect_string(&call_pos, &args[0])?;
                let value = expect_string(&call_pos, &args[1])?;
                std::env::set_var(std::ffi::OsStr::from_bytes(&name), std::ffi::OsStr::from_bytes(&value));
                Ok(Value::Nil)
            }
            StdFn::Read => {
                if args.len() > 1 {
                    return Err(Signal::Panic(arity_error(call_pos, args.len(), 1)));
                }
                if args.len() == 1 {
                    let prompt = expect_string(&call_pos, &args[0])?;
                    stdout_write(&prompt);
                    stdout_flush();
                }
                Ok(Value::Str(read_stdin_line()))
            }
            StdFn::Sleep => {
                check_arity(&call_pos, &args, 1)?;
                let duration = expect_int(&call_pos, &args[0])?;
                if duration < 0 {
                    return err(&call_pos, format!("invalid value ({}), expected positive integer", args[0].display()));
                }
                std::thread::sleep(std::time::Duration::from_millis(duration as u64));
                Ok(Value::Nil)
            }
            StdFn::Exit => {
                check_arity(&call_pos, &args, 1)?;
                let code = expect_int(&call_pos, &args[0])?;
                if !(0..=255).contains(&code) {
                    return err(&call_pos, format!("invalid value ({}), expected valid exit code", args[0].display()));
                }
                Err(Signal::Exit(code as i32))
            }
            StdFn::Panic => {
                check_arity(&call_pos, &args, 1)?;
                err(&call_pos, format!("std.panic({})", args[0].display()))
            }
            StdFn::Assert => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Bool(true) => Ok(Value::Nil),
                    Value::Bool(false) => err(&call_pos, "assertion failed".to_string()),
                    _ => unexpected(&call_pos, &args[0], "bool"),
                }
            }
            StdFn::Error => {
                check_arity(&call_pos, &args, 2)?;
                let description = expect_string(&call_pos, &args[0])?;
                Ok(make_error(description, args[1].clone()))
            }
            StdFn::Catch => {
                check_arity(&call_pos, &args, 1)?;
                let _ = expect_function(&call_pos, &args[0])?;
                match self.call_value(args[0].clone(), Vec::new(), Value::Nil, call_pos.clone(), None, env) {
                    Ok(value) => Ok(value),
                    Err(Signal::Panic(p)) => Ok(make_error(
                        format!("caught panic: {}", p.format()).into_bytes(),
                        Value::Str(b"panic".to_vec()),
                    )),
                    Err(other) => Err(other),
                }
            }
            StdFn::HasError => {
                check_arity(&call_pos, &args, 1)?;
                Ok(Value::Bool(matches!(args[0], Value::Error(_))))
            }
            StdFn::Type => {
                check_arity(&call_pos, &args, 1)?;
                Ok(Value::Str(args[0].type_name().as_bytes().to_vec()))
            }
            StdFn::Len => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
