                    let result = regex.replace_all(
                        &crate::source::bytes_to_lossy_string(&text),
                        crate::source::bytes_to_lossy_string(&replacement).as_str(),
                    );
                    Ok(Value::Str(result.into_owned().into_bytes()))
                }
                RegexKind::Split => {
                    check_arity(&call_pos, &args, 1)?;
                    let text = expect_string(&call_pos, &args[0])?;
                    let text_string = crate::source::bytes_to_lossy_string(&text);
                    let values = regex.split(&text_string).map(|part| Value::Str(part.as_bytes().to_vec())).collect();
                    Ok(Value::new_array(values))
                }
            },
            NativeKind::Join(shared) => {
                check_arity(&call_pos, &args, 0)?;
                let handle = {
                    let mut guard = shared.state.lock().unwrap();
                    match std::mem::replace(&mut *guard, JoinState::Taken) {
                        JoinState::Running(handle) => handle,
                        JoinState::Taken => {
                            return err(&call_pos, "attempt to call join more than once".to_string());
                        }
                    }
                };
                match handle.join() {
                    Ok(Ok(value)) => Ok(value),
                    Ok(Err(JoinError::Panic(p))) => Err(Signal::Panic(p)),
                    Ok(Err(JoinError::Exit(code))) => Err(Signal::Exit(code)),
                    Err(_) => err(&call_pos, "attempt to call join more than once".to_string()),
                }
            }
        }
    }

    fn call_std(
        &mut self,
        std_fn: StdFn,
        args: Vec<Value>,
        _self_value: Value,
        call_pos: SourcePos,
        env: &Env,
    ) -> EvalResult<Value> {
        match std_fn {
            StdFn::Print => {
                let mut out = Vec::new();
                for (index, arg) in args.iter().enumerate() {
                    if index > 0 { out.push(b'\t'); }
                    out.extend_from_slice(&arg.print_bytes());
                }
                stdout_write(&out);
                Ok(Value::Nil)
            }
            StdFn::Println => {
                let mut out = Vec::new();
                for (index, arg) in args.iter().enumerate() {
                    if index > 0 { out.push(b'\t'); }
                    out.extend_from_slice(&arg.print_bytes());
                }
                out.push(b'\n');
                stdout_write(&out);
                Ok(Value::Nil)
            }
            StdFn::Args => {
                check_arity(&call_pos, &args, 0)?;
                Ok(Value::new_array(self.runtime.script_args.clone()))
            }
            StdFn::Cwd => {
                check_arity(&call_pos, &args, 0)?;
                match std::env::current_dir() {
                    Ok(path) => Ok(Value::Str(path.as_os_str().as_encoded_bytes().to_vec())),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Nil)),
                }
            }
            StdFn::Cd => {
                check_arity(&call_pos, &args, 1)?;
                let path = expect_string(&call_pos, &args[0])?;
                match std::env::set_current_dir(std::path::Path::new(&crate::source::bytes_to_lossy_string(&path))) {
                    Ok(()) => Ok(Value::Nil),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Nil)),
                }
            }
            StdFn::Env => {
                check_arity(&call_pos, &args, 1)?;
                let name = expect_string(&call_pos, &args[0])?;
                match std::env::var_os(std::ffi::OsStr::from_bytes(&name)) {
                    Some(value) => Ok(Value::Str(value.as_encoded_bytes().to_vec())),
                    None => Ok(Value::Nil),
                }
            }
            StdFn::Export => {
                check_arity(&call_pos, &args, 2)?;
                let name = expect_string(&call_pos, &args[0])?;
                let value = expect_string(&call_pos, &args[1])?;
                std::env::set_var(std::ffi::OsStr::from_bytes(&name), std::ffi::OsStr::from_bytes(&value));
                Ok(Value::Nil)
            }
            StdFn::Read => {
                if args.len() > 1 {
                    return Err(Signal::Panic(arity_error(call_pos, args.len(), 1)));
                }
                if args.len() == 1 {
                    let prompt = expect_string(&call_pos, &args[0])?;
                    stdout_write(&prompt);
                    stdout_flush();
                }
                Ok(Value::Str(read_stdin_line()))
            }
            StdFn::Sleep => {
                check_arity(&call_pos, &args, 1)?;
                let duration = expect_int(&call_pos, &args[0])?;
                if duration < 0 {
                    return err(&call_pos, format!("invalid value ({}), expected positive integer", args[0].display()));
                }
                std::thread::sleep(std::time::Duration::from_millis(duration as u64));
                Ok(Value::Nil)
            }
            StdFn::Exit => {
                check_arity(&call_pos, &args, 1)?;
                let code = expect_int(&call_pos, &args[0])?;
                if !(0..=255).contains(&code) {
                    return err(&call_pos, format!("invalid value ({}), expected valid exit code", args[0].display()));
                }
                Err(Signal::Exit(code as i32))
            }
            StdFn::Panic => {
                check_arity(&call_pos, &args, 1)?;
                err(&call_pos, format!("std.panic({})", args[0].display()))
            }
            StdFn::Assert => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Bool(true) => Ok(Value::Nil),
                    Value::Bool(false) => err(&call_pos, "assertion failed".to_string()),
                    _ => unexpected(&call_pos, &args[0], "bool"),
                }
            }
            StdFn::Error => {
                check_arity(&call_pos, &args, 2)?;
                let description = expect_string(&call_pos, &args[0])?;
                Ok(make_error(description, args[1].clone()))
            }
            StdFn::Catch => {
                check_arity(&call_pos, &args, 1)?;
                let _ = expect_function(&call_pos, &args[0])?;
                match self.call_value(args[0].clone(), Vec::new(), Value::Nil, call_pos.clone(), None, env) {
                    Ok(value) => Ok(value),
                    Err(Signal::Panic(p)) => Ok(make_error(
                        format!("caught panic: {}", p.format()).into_bytes(),
                        Value::Str(b"panic".to_vec()),
                    )),
                    Err(other) => Err(other),
                }
            }
            StdFn::HasError => {
                check_arity(&call_pos, &args, 1)?;
                Ok(Value::Bool(matches!(args[0], Value::Error(_))))
            }
            StdFn::Type => {
                check_arity(&call_pos, &args, 1)?;
                Ok(Value::Str(args[0].type_name().as_bytes().to_vec()))
            }
            StdFn::Len => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Str(bytes) => Ok(Value::Int(bytes.len() as i64)),
                    Value::Array(items) => Ok(Value::Int(items.lock().unwrap().len() as i64)),
                    Value::Dict(map) => Ok(Value::Int(map.lock().unwrap().len() as i64)),
                    _ => unexpected(&call_pos, &args[0], "string, array or dict"),
                }
            }
            StdFn::IsEmpty => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Str(bytes) => Ok(Value::Bool(bytes.is_empty())),
                    Value::Array(items) => Ok(Value::Bool(items.lock().unwrap().is_empty())),
                    Value::Dict(map) => Ok(Value::Bool(map.lock().unwrap().is_empty())),
                    _ => unexpected(&call_pos, &args[0], "string, array or dict"),
                }
            }
            StdFn::Push => {
                check_arity(&call_pos, &args, 2)?;
                match &args[0] {
                    Value::Array(items) => {
                        items.lock().unwrap().push(args[1].clone());
                        Ok(Value::Nil)
                    }
                    _ => unexpected(&call_pos, &args[0], "array"),
                }
            }
            StdFn::Pop => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Array(items) => {
                        let mut items = items.lock().unwrap();
                        match items.pop() {
                            Some(value) => Ok(value),
                            None => err(&call_pos, "collection is empty".to_string()),
                        }
                    }
                    _ => unexpected(&call_pos, &args[0], "array"),
                }
            }
            StdFn::Sort => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Array(items) => {
                        let mut items = items.lock().unwrap();
                        items.sort_by(|a, b| a.compare(b));
                        Ok(Value::Nil)
                    }
                    _ => unexpected(&call_pos, &args[0], "array"),
                }
            }
            StdFn::Contains => {
                check_arity(&call_pos, &args, 2)?;
                match &args[0] {
                    Value::Str(bytes) => {
                        let needle = match &args[1] {
                            Value::Char(byte) => *byte,
                            _ => return unexpected(&call_pos, &args[1], "char"),
                        };
                        Ok(Value::Bool(bytes.contains(&needle)))
                    }
                    Value::Array(items) => {
                        let items = items.lock().unwrap();
                        Ok(Value::Bool(items.iter().any(|item| item.equals(&args[1]))))
                    }
                    Value::Dict(map) => {
                        let key = DictKey::from_value(&args[1]);
                        Ok(Value::Bool(map.lock().unwrap().contains_key(&key)))
                    }
                    _ => unexpected(&call_pos, &args[0], "string ,array or dict"),
                }
            }
            StdFn::Trim => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                let text = crate::source::bytes_to_lossy_string(&bytes);
                Ok(Value::Str(text.trim().as_bytes().to_vec()))
            }
            StdFn::Split => {
                check_arity(&call_pos, &args, 2)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                let pattern = expect_string(&call_pos, &args[1])?;
                let text = crate::source::bytes_to_lossy_string(&bytes);
                let pattern = crate::source::bytes_to_lossy_string(&pattern);
                let pieces = text.split(pattern.as_str()).map(|part| Value::Str(part.as_bytes().to_vec())).collect();
                Ok(Value::new_array(pieces))
            }
            StdFn::Replace => {
                check_arity(&call_pos, &args, 3)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                let from = expect_string(&call_pos, &args[1])?;
                let to = expect_string(&call_pos, &args[2])?;
                let text = crate::source::bytes_to_lossy_string(&bytes);
                let result = text.replace(&crate::source::bytes_to_lossy_string(&from), &crate::source::bytes_to_lossy_string(&to));
                Ok(Value::Str(result.into_bytes()))
            }
            StdFn::Substr => {
                check_arity(&call_pos, &args, 3)?;
                // The original treats an invalid length argument as an
                // arity error.
                if !matches!(args[2], Value::Int(_)) {
                    return Err(Signal::Panic(arity_error(call_pos.clone(), 3, 3)));
                }
                let bytes = expect_string(&call_pos, &args[0])?;
                let start = expect_int(&call_pos, &args[1])?;
                let length = expect_int(&call_pos, &args[2])?;
                if start < 0 || length < 0 {
                    return Ok(Value::Nil);
                }
                let text = crate::source::bytes_to_lossy_string(&bytes);
                let start = start as usize;
                let Some(end) = start.checked_add(length as usize) else { return Ok(Value::Nil) };
                match text.get(start..end) {
                    Some(part) => Ok(Value::Str(part.as_bytes().to_vec())),
                    None => Ok(Value::Nil),
                }
            }
            StdFn::Bytes => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                Ok(Value::new_array(bytes.into_iter().map(Value::Char).collect()))
            }
            StdFn::Int => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Int(value) => Ok(Value::Int(*value)),
                    Value::Float(value) => Ok(Value::Int(*value as i64)),
                    Value::Str(bytes) => {
                        let text = crate::source::bytes_to_lossy_string(bytes);
                        match text.parse::<i64>() {
                            Ok(value) => Ok(Value::Int(value)),
                            Err(_) => err(&call_pos, format!("invalid value ({}), expected valid integer", args[0].display())),
                        }
                    }
                    _ => unexpected(&call_pos, &args[0], "int, float or string"),
                }
            }
            StdFn::Float => {
                check_arity(&call_pos, &args, 1)?;
                match &args[0] {
                    Value::Int(value) => Ok(Value::Float(*value as f64)),
                    Value::Float(value) => Ok(Value::Float(*value)),
                    Value::Str(bytes) => {
                        let text = crate::source::bytes_to_lossy_string(bytes);
                        match text.parse::<f64>() {
                            Ok(value) => Ok(Value::Float(value)),
                            Err(_) => err(&call_pos, format!("invalid value ({}), expected valid integer", args[0].display())),
                        }
                    }
                    _ => unexpected(&call_pos, &args[0], "int, float or string"),
                }
            }
            StdFn::ToString => {
                check_arity(&call_pos, &args, 1)?;
                Ok(Value::Str(crate::interp::value_to_string_bytes(&args[0])))
            }
            StdFn::Iter => {
                check_arity(&call_pos, &args, 1)?;
                let collection = match &args[0] {
                    Value::Str(bytes) => IterCollection::Str(bytes.clone()),
                    Value::Array(items) => IterCollection::Array(items.lock().unwrap().clone()),
                    Value::Dict(map) => IterCollection::Dict(crate::interp::hash_map_snapshot(map)),
                    _ => return unexpected(&call_pos, &args[0], "string, array or dict"),
                };
                Ok(Value::Function(Arc::new(FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::Native {
                        name: "std.iter<impl>".to_string(),
                        native: NativeKind::Iter(Arc::new(std::sync::Mutex::new(IterState { collection, index: 0 }))),
                    },
                })))
            }
            StdFn::Range => {
                check_arity(&call_pos, &args, 3)?;
                for arg in &args {
                    if !matches!(arg, Value::Int(_) | Value::Float(_)) {
                        return unexpected(&call_pos, arg, "int or float");
                    }
                }
                let any_float = args.iter().any(|arg| matches!(arg, Value::Float(_)));
                let (current, end, step) = if any_float {
                    (
                        NumberValue::Float(number_as_f64(&args[0])),
                        NumberValue::Float(number_as_f64(&args[1])),
                        NumberValue::Float(number_as_f64(&args[2])),
                    )
                } else {
                    (
                        NumberValue::Int(number_as_i64(&args[0])),
                        NumberValue::Int(number_as_i64(&args[1])),
                        NumberValue::Int(number_as_i64(&args[2])),
                    )
                };
                Ok(Value::Function(Arc::new(FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::Native {
                        name: "std.range<impl>".to_string(),
                        native: NativeKind::Range(Arc::new(std::sync::Mutex::new(RangeState { current, end, step }))),
                    },
                })))
            }
            StdFn::Rand => {
                check_arity(&call_pos, &args, 0)?;
                let value = self.runtime.rng.lock().unwrap().gen::<f64>();
                Ok(Value::Float(value))
            }
            StdFn::RandInt => {
                check_arity(&call_pos, &args, 2)?;
                let low = match &args[0] {
                    Value::Int(value) => *value,
                    _ => return unexpected(&call_pos, &args[0], "int"),
                };
                let high = match &args[1] {
                    Value::Int(value) => *value,
                    _ => return unexpected(&call_pos, &args[0], "int"),
                };
                let value = self.runtime.rng.lock().unwrap().gen_range(low..=high);
                Ok(Value::Int(value))
            }
            StdFn::RandSeed => {
                check_arity(&call_pos, &args, 1)?;
                let seed = expect_int(&call_pos, &args[0])?;
                *self.runtime.rng.lock().unwrap() = ChaCha8Rng::seed_from_u64(seed as u64);
                Ok(Value::Nil)
            }
            StdFn::Glob => {
                check_arity(&call_pos, &args, 1)?;
                let pattern_bytes = expect_string(&call_pos, &args[0])?;
                let pattern = crate::source::bytes_to_lossy_string(&pattern_bytes);
                match glob::glob(&pattern) {
                    Ok(paths) => {
                        let mut values: Vec<Vec<u8>> = paths
                            .filter_map(|entry| entry.ok())
                            .map(|path| path.as_os_str().as_encoded_bytes().to_vec())
                            .collect();
                        values.sort();
                        Ok(Value::new_array(values.into_iter().map(Value::Str).collect()))
                    }
                    Err(error) => Ok(make_error(b"Invalid pattern".to_vec(), Value::Str(error.msg.as_bytes().to_vec()))),
                }
            }
            StdFn::Regex => {
                check_arity(&call_pos, &args, 1)?;
                let pattern_bytes = expect_string(&call_pos, &args[0])?;
                let pattern = crate::source::bytes_to_lossy_string(&pattern_bytes);
                match regex::Regex::new(&pattern) {
                    Ok(regex) => {
                        let regex = Arc::new(regex);
                        let make = |name: &str, kind: RegexKind| {
                            Value::Function(Arc::new(FunctionData {
                                id: crate::value::next_function_id(),
                                kind: FunctionKind::Native {
                                    name: name.to_string(),
                                    native: NativeKind::RegexMethod { regex: regex.clone(), kind },
                                },
                            }))
                        };
                        Ok(Value::dict_from_entries(vec![
                            (Value::Str(b"match".to_vec()), make("std.regex<match>", RegexKind::Match)),
                            (Value::Str(b"replace".to_vec()), make("std.regex<replace>", RegexKind::Replace)),
                            (Value::Str(b"split".to_vec()), make("std.regex<split>", RegexKind::Split)),
                        ]))
                    }
                    Err(error) => Ok(make_error(b"invalid regex".to_vec(), Value::Str(error.to_string().into_bytes()))),
                }
            }
            StdFn::Import => {
                check_arity(&call_pos, &args, 1)?;
                let path = expect_string(&call_pos, &args[0])?;
                crate::import::import_module(self, &path, env, call_pos)
            }
            StdFn::Bind => {
                check_arity(&call_pos, &args, 2)?;
                let _ = expect_function(&call_pos, &args[1])?;
                Ok(Value::Function(Arc::new(FunctionData {
                    id: crate::value::next_function_id(),
                    kind: FunctionKind::Native {
                        name: "std.bind<impl>".to_string(),
                        native: NativeKind::Bind { target: args[1].clone(), bound_self: args[0].clone() },
                    },
                })))
            }
            StdFn::Typecheck => {
                check_arity(&call_pos, &args, 2)?;
                let type_name = expect_string(&call_pos, &args[1])?;
                let type_name_text = crate::source::bytes_to_lossy_string(&type_name);
                if !is_valid_type_name(&type_name_text) {
                    return err(&call_pos, format!("invalid value ({}), expected valid type", args[1].display()));
                }
                if args[0].type_name() != type_name_text {
                    return unexpected(&call_pos, &args[0], &type_name_text);
                }
                Ok(args[0].clone())
            }
            StdFn::TryTypecheck => {
                check_arity(&call_pos, &args, 2)?;
                let type_name = expect_string(&call_pos, &args[1])?;
                let type_name_text = crate::source::bytes_to_lossy_string(&type_name);
                if !is_valid_type_name(&type_name_text) {
                    return err(&call_pos, format!("invalid value ({}), expected valid type", args[1].display()));
                }
                if args[0].type_name() != type_name_text {
                    let description = format!(
                        "type error: expected {}, got {} ({})",
                        type_name_text,
                        args[0].type_name(),
                        args[0].display()
                    );
                    return Ok(make_error(description.into_bytes(), args[0].clone()));
                }
                Ok(Value::Nil)
            }
            StdFn::JsonEncode => {
                check_arity(&call_pos, &args, 1)?;
                match value_to_json(&args[0]) {
                    Some(value) => Ok(Value::Str(serde_json::to_string_pretty(&value).unwrap_or_default().into_bytes())),
                    None => err(&call_pos, format!("invalid value ({}), expected nil, bool, byte, int, float, string, array or dict", args[0].display())),
                }
            }
            StdFn::JsonDecode => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                let text = crate::source::bytes_to_lossy_string(&bytes);
                match serde_json::from_str::<serde_json::Value>(&text) {
                    Ok(value) => match json_to_value(&value, &text) {
                        Ok(value) => Ok(value),
                        Err(message) => Ok(make_error(message.into_bytes(), Value::Str(bytes))),
                    },
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Str(bytes))),
                }
            }
            StdFn::Base64Encode => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                use base64::Engine;
                Ok(Value::Str(base64_engine().encode(bytes).into_bytes()))
            }
            StdFn::Base64Decode => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                use base64::Engine;
                match base64_engine().decode(&bytes) {
                    Ok(decoded) => Ok(Value::Str(decoded)),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Str(bytes))),
                }
            }
            StdFn::HexEncode => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                Ok(Value::Str(hex::encode(bytes).into_bytes()))
            }
            StdFn::HexDecode => {
                check_arity(&call_pos, &args, 1)?;
                let bytes = expect_string(&call_pos, &args[0])?;
                match hex::decode(crate::source::bytes_to_lossy_string(&bytes)) {
                    Ok(decoded) => Ok(Value::Str(decoded)),
                    Err(error) => Ok(make_error(error.to_string().into_bytes(), Value::Str(bytes))),
                }
            }
        }
    }
}

fn iteration_dict(value: Value) -> Value {
    Value::dict_from_entries(vec![
        (Value::Str(b"finished".to_vec()), Value::Bool(false)),
        (Value::Str(b"value".to_vec()), value),
    ])
}

fn finished_dict() -> Value {
    Value::dict_from_entries(vec![(Value::Str(b"finished".to_vec()), Value::Bool(true))])
}

fn as_f64(value: &NumberValue) -> f64 {
    match value { NumberValue::Int(i) => *i as f64, NumberValue::Float(x) => *x }
}

fn number_as_f64(value: &Value) -> f64 {
    match value { Value::Int(i) => *i as f64, Value::Float(x) => *x, _ => 0.0 }
}

fn number_as_i64(value: &Value) -> i64 {
    match value { Value::Int(i) => *i, _ => 0 }
}

fn is_valid_type_name(name: &str) -> bool {
    matches!(name, "nil" | "bool" | "int" | "float" | "char" | "string" | "array" | "dict" | "function" | "error")
}

fn value_to_json(value: &Value) -> Option<serde_json::Value> {
    match value {
        Value::Nil => Some(serde_json::Value::Null),
        Value::Bool(b) => Some(serde_json::Value::Bool(*b)),
        Value::Int(i) => Some(serde_json::Value::Number((*i).into())),
        Value::Float(x) => Some(match serde_json::Number::from_f64(*x) {
            Some(number) => serde_json::Value::Number(number),
            None => serde_json::Value::Null,
        }),
        Value::Char(byte) => {
            let mut text = String::new();
            text.push(*byte as char);
            Some(serde_json::Value::String(text))
        }
        Value::Str(bytes) => Some(serde_json::Value::String(crate::source::bytes_to_lossy_string(bytes))),
        Value::Array(items) => {
            let items = items.lock().unwrap().clone();
            let mut values = Vec::new();
            for item in &items { values.push(value_to_json(item)?); }
            Some(serde_json::Value::Array(values))
        }
        Value::Dict(map) => {
            let entries = crate::interp::hash_map_snapshot(map);
            let mut object = serde_json::Map::new();
            for (key, value) in &entries {
                let key_text = match key {
                    Value::Str(bytes) => crate::source::bytes_to_lossy_string(bytes),
                    _ => return None,
                };
                object.insert(key_text, value_to_json(value)?);
            }
            Some(serde_json::Value::Object(object))
        }
        _ => None,
    }
}

fn json_to_value(value: &serde_json::Value, source_text: &str) -> Result<Value, String> {
    match value {
        serde_json::Value::Null => Ok(Value::Nil),
        serde_json::Value::Bool(b) => Ok(Value::Bool(*b)),
        serde_json::Value::Number(number) => {
            if let Some(i) = number.as_i64 {
                Ok(Value::Int(i))
            } else if number.as_u64().is_some() {
                // Find the position at the end of this number literal.
                let number_text = number.to_string();
                let mut line = 1usize;
                let mut column = 0usize;
                if let Some(index) = source_text.find(&number_text) {
                    let end = index + number_text.len();
                    for ch in source_text[..end].chars() {
                        if ch == '\n' { line += 1; column = 0; } else { column += 1; }
                    }
                }
                Err(format!("out of range integral type conversion attempted at line {} column {}", line, column))
            } else {
                Ok(Value::Float(number.as_f64().unwrap_or(0.0)))
            }
        }
        serde_json::Value::String(text) => Ok(Value::Str(text.as_bytes().to_vec())),
        serde_json::Value::Array(items) => {
            let mut values = Vec::new();
            for item in items { values.push(json_to_value(item, source_text)?); }
            Ok(Value::new_array(values))
        }
        serde_json::Value::Object(map) => {
            let entries = map
                .iter()
                .map(|(key, value)| Ok((Value::Str(key.as_bytes().to_vec()), json_to_value(value, source_text)?)))
                .collect::<Result<Vec<_>, String>>()?;
            Ok(Value::dict_from_entries(entries))
        }
    }
}

fn base64_engine() -> base64::engine::GeneralPurpose {
    base64::engine::GeneralPurpose::new(
        &base64::alphabet::STANDARD,
        base64::engine::GeneralPurposeConfig::new().with_decode_padding_mode(base64::engine::DecodePaddingMode::Indifferent),
    )
}

use std::os::unix::ffi::OsStrExt;
EOF
"}

