use crate::parser::Parser;
use crate::resolver::Resolver;
use crate::source::SourcePos;
use std::path::PathBuf;
use std::rc::Rc;

pub fn import_module(executor: &mut Executor, path_bytes: &[u8], env: &Env, call_pos: SourcePos) -> EvalResult<Value> {
    let requested = crate::source::bytes_to_lossy_string(path_bytes);
    let importer = env.source_path.as_str();
    let base = std::path::Path::new(importer).parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from(""));
    let candidate = base.join(&requested);
    let canonical = match std::fs::canonicalize(&candidate) {
        Ok(path) => path,
        Err(error) => return Err(Signal::Panic(Panic::new(call_pos, error.to_string()))),
    };
    let data = match std::fs::read(&canonical) {
        Ok(data) => data,
        Err(error) => return Err(Signal::Panic(Panic::new(call_pos, error.to_string()))),
    };
    let canonical_display = canonical.to_string_lossy().into_owned();
    let source_name = Rc::new(canonical_display.clone());
    let (tokens, lex_errors, _items) = Lexer::new(data, source_name.clone()).lex();
    let mut parser = Parser::new(tokens, source_name.clone());
    let ast = parser.parse_program();
    let mut syntax_errors = lex_errors;
    syntax_errors.extend(parser.errors.iter().cloned());
    let mut resolver = Resolver::new();
    let program = resolver.resolve_program(&ast);

    let mut all_errors = syntax_errors.clone();
    all_errors.extend(resolver.errors.iter().cloned());

    if !all_errors.is_empty() {
        for error in &all_errors {
            eprint!("{}", error.format_main());
        }
        return Err(Signal::Panic(Panic::new(
            call_pos,
            format!("failed to import module ({})", canonical_display),
        )));
    }

    let mut module_executor = Executor::new(executor.runtime.clone());
    module_executor.execute_program(&program, source_name)
}
