    args: Vec<Vec<u8>>,
    question: bool,
    pos: SourcePos,
    failure: Option<Value>,
    io: [IoDesc; 3],
    prepared_redirects: Vec<PreparedRedirect>,
}

pub fn execute_command_block(
    executor: &mut Executor,
    block: &CommandBlockR,
    mode: CommandMode,
    env: &Env,
) -> EvalResult<Value> {
    if block.ill_formed_block {
        return Ok(Value::Nil);
    }
    let capture = match mode {
        CommandMode::Capture => Some(CaptureContext::new()),
        CommandMode::Plain => None,
    };

    let mut accumulated: Vec<Value> = Vec::new();
    let mut stop = false;

    for pipeline in &block.pipelines {
        if stop { break; }
        if pipeline.ill_formed { continue; }
        // Prepare commands from last to first.
        let mut prepared: Vec<Option<PreparedCommand>> = Vec::new();
        prepared.resize_with(pipeline.commands.len(), || None);
        for index in (0..pipeline.commands.len()).rev() {
            prepared[index] = Some(prepare_command(executor, &pipeline.commands[index], index + 1 == pipeline.commands.len(), mode, env)?);
        }
        let prepared: Vec<PreparedCommand> = prepared.into_iter().map(|item| item.unwrap()).collect();
        let stage_results = run_pipeline(prepared, mode, capture.as_ref());
        let failures: Vec<(usize, Value)> = stage_results
            .into_iter()
            .enumerate()
            .filter_map(|(index, result)| result.map(|error| (index, error)))
            .collect();
        if !failures.is_empty() {
            let should_stop = failures.iter().any(|(index, _)| !pipeline.commands[*index].question);
            let errors: Vec<Value> = failures.iter().map(|(_, error)| error.clone()).collect();
            let entry = if errors.len() == 1 {
                errors[0].clone()
            } else {
                error_value(b"Some commands failed in the pipeline".to_vec(), Value::new_array(errors))
            };
            accumulated.push(entry);
            if should_stop { stop = true; }
        }
    }

    let result_error = if accumulated.is_empty() {
        None
    } else if accumulated.len() == 1 {
        Some(accumulated[0].clone())
    } else {
        Some(error_value(b"Some commands failed in the block".to_vec(), Value::new_array(accumulated)))
    };

    match mode {
        CommandMode::Plain => Ok(result_error.unwrap_or(Value::Nil)),
        CommandMode::Capture => {
            let capture = capture.unwrap();
            let (stdout, stderr) = capture.finish();
            match result_error {
                None => Ok(Value::dict_from_entries(vec![
                    (Value::Str(b"stdout".to_vec()), Value::Str(stdout)),
                    (Value::Str(b"stderr".to_vec()), Value::Str(stderr)),
                ])),
                Some(error) => {
                    if let Value::Error(data) = &error {
                        let cause = Value::dict_from_entries(vec![
                            (Value::Str(b"stdout".to_vec()), Value::Str(stdout)),
                            (Value::Str(b"stderr".to_vec()), Value::Str(stderr)),
                            (Value::Str(b"error".to_vec()), data.cause.clone()),
                        ]);
                        Ok(error_value(data.description.clone(), cause))
                    } else {
                        Ok(error)
                    }
                }
            }
        }
    }
}

fn error_value(description: Vec<u8>, cause: Value) -> Value {
    Value::Error(Arc::new(ErrorData { description, cause }))
}

fn command_error(description: Vec<u8>, pos: &SourcePos, status: i64) -> Value {
    let cause = Value::dict_from_entries(vec![
        (Value::Str(b"pos".to_vec()), Value::Str(pos.to_string().into_bytes())),
        (Value::Str(b"status".to_vec()), Value::Int(status)),
    ]);
    error_value(description, cause)
}

struct CaptureContext {
    out_read: Option<std::fs::File>,
    out_write: Arc<std::fs::File>,
    err_read: Option<std::fs::File>,
    err_write: Arc<std::fs::File>,
}

impl CaptureContext {
    fn new() -> Self {
        let (out_read, out_write) = make_pipe();
        let (err_read, err_write) = make_pipe();
        Self {
            out_read: Some(out_read),
            out_write: Arc::new(out_write),
            err_read: Some(err_read),
            err_write: Arc::new(err_write),
        }
    }
    fn finish(mut self) -> (Vec<u8>, Vec<u8>) {
        // Spawn readers now (all writers except our stored write ends are
        // closed by dropping those ends).
        let out_read = self.out_read.take().unwrap();
        let err_read = self.err_read.take().unwrap();
        let out_thread = std::thread::spawn(move || {
            let mut file = out_read;
            let mut data = Vec::new();
            let _ = file.read_to_end(&mut data);
            data
        });
        let err_thread = std::thread::spawn(move || {
            let mut file = err_read;
            let mut data = Vec::new();
            let _ = file.read_to_end(&mut data);
            data
        });
        drop(self.out_write);
        drop(self.err_write);
        (
            out_thread.join().unwrap_or_default(),
            err_thread.join().unwrap_or_default(),
        )
    }
}

fn prepare_command(
    executor: &mut Executor,
    command: &CommandR,
    is_last: bool,
    mode: CommandMode,
    env: &Env,
) -> EvalResult<PreparedCommand> {
    let program = expand_single(executor, &command.program, &command.pos, "program", env)?;
    let mut args = Vec::new();
    for argument in &command.args {
        args.extend(expand_argument(executor, argument, &command.pos, env)?);
    }

    // Open all file targets first (in source order).
    let mut prepared_redirects = Vec::new();
    for redirect in &command.redirects {
        match &redirect.target {
            RedirectTargetR::IllFormed => prepared_redirects.push(PreparedRedirect::IllFormed),
            RedirectTargetR::Fd(fd) => prepared_redirects.push(PreparedRedirect::Fd { source_fd: redirect.source_fd, target_fd: *fd }),
            RedirectTargetR::File(template) => {
                let target = expand_single(executor, template, &command.pos, "redirection", env)?;
                match redirect.kind {
                    RedirectKind::InputString => prepared_redirects.push(PreparedRedirect::InputString { content: target }),
                    RedirectKind::Input => {
                        let result = std::fs::File::open(bytes_to_path(&target)).map(Arc::new).map_err(|e| e.to_string());
                        prepared_redirects.push(PreparedRedirect::File { source_fd: redirect.source_fd, kind: redirect.kind, result });
                    }
                    RedirectKind::Output => {
                        let result = std::fs::OpenOptions::new().write(true).create(true).truncate(true).open(bytes_to_path(&target)).map(Arc::new).map_err(|e| e.to_string());
                        prepared_redirects.push(PreparedRedirect::File { source_fd: redirect.source_fd, kind: redirect.kind, result });
                    }
                    RedirectKind::Append => {
                        let result = std::fs::OpenOptions::new().write(true).create(true).append(true).open(bytes_to_path(&target)).map(Arc::new).map_err(|e| e.to_string());
                        prepared_redirects.push(PreparedRedirect::File { source_fd: redirect.source_fd, kind: redirect.kind, result });
                    }
                }
            }
        }
    }

    let default_out = if !is_last {
        IoDesc::PipeNext
    } else {
        match mode { CommandMode::Plain => IoDesc::InitialOut, CommandMode::Capture => IoDesc::CaptureOut }
    };
    let default_err = match mode { CommandMode::Plain => IoDesc::InitialErr, CommandMode::Capture => IoDesc::CaptureErr };
    let mut io = [IoDesc::DefaultIn, default_out, default_err];
    let mut failure = None;

    for redirect in &command.redirects {
        // Find the corresponding prepared redirect by position in the list:
        // the loop below re-derives it from the prepared vector using an
        // index tracked separately.
        let _ = redirect;
        break;
    }
    // Apply prepared redirects in order.
    for (redirect, prepared) in command.redirects.iter().zip(prepared_redirects.iter()) {
        match prepared {
            PreparedRedirect::IllFormed => {}
            PreparedRedirect::InputString { content } => {
                io[0] = IoDesc::StringInput(content.clone());
            }
            PreparedRedirect::Fd { source_fd, target_fd } => {
                let source = source_fd.unwrap_or(1);
                if !(1..=2).contains(&source) {
                    return Err(Signal::Panic(Panic::new(command.pos.clone(), format!("unsupported file descriptor ({})", source))));
                }
                if !(1..=2).contains(target_fd) {
                    return Err(Signal::Panic(Panic::new(command.pos.clone(), format!("unsupported file descriptor ({})", target_fd))));
                }
                io[source as usize] = io[*target_fd as usize].clone();
            }
            PreparedRedirect::File { source_fd, kind, result } => match kind {
                RedirectKind::Input => match result {
                    Ok(file) => io[0] = IoDesc::File(file.clone()),
                    Err(message) => {
                        failure = Some(command_error(message.clone().into_bytes(), &command.pos, 127));
                        break;
                    }
                },
                RedirectKind::InputString => unreachable!(),
                RedirectKind::Output | RedirectKind::Append => {
                    let source = source_fd.unwrap_or(1);
                    match result {
                        Ok(file) => {
                            if !(1..=2).contains(&source) {
                                return Err(Signal::Panic(Panic::new(command.pos.clone(), format!("unsupported file descriptor ({})", source))));
                            }
                            io[source as usize] = IoDesc::File(file.clone());
                        }
                        Err(message) => {
                            failure = Some(command_error(message.clone().into_bytes(), &command.pos, 127));
                            break;
                        }
                    }
                }
            },
        }
        let _ = redirect;
    }

    Ok(PreparedCommand {
        program,
        args,
        question: command.question,
        pos: command.pos.clone(),
        failure,
        io,
        prepared_redirects,
    })
}

fn bytes_to_path(bytes: &[u8]) -> std::path::PathBuf {
    std::ffi::OsString::from_vec(bytes.to_vec()).into()
}

fn expand_argument(
    executor: &mut Executor,
    template: &TemplateR,
    command_pos: &SourcePos,
    env: &Env,
) -> EvalResult<Vec<Vec<u8>>> {
    if template.empty_quoted && template.segments.is_empty() {
        return Ok(vec![Vec::new()]);
    }
    let words = expand_low(executor, template, env)?;
    let mut out = Vec::new();
    for word in words {
        out.extend(glob_expand(word, command_pos)?);
    }
    Ok(out)
}

fn expand_single(
    executor: &mut Executor,
    template: &TemplateR,
    command_pos: &SourcePos,
    kind: &str,
    env: &Env,
) -> EvalResult<Vec<u8>> {
    let words = expand_low(executor, template, env)?;
    if words.is_empty() {
        return Err(Signal::Panic(Panic::new(
            template.pos.clone(),
            format!("{} expansion resulted in 0 items", kind),
        )));
    }
    if words.len() > 1 {
        return Err(Signal::Panic(Panic::new(
            template.pos.clone(),
            format!("{} expansion resulted in {} items", kind, words.len() - 1),
        )));
    }
    let matches = glob_expand(words.into_iter().next().unwrap(), command_pos)?;
    if matches.len() != 1 {
        return Err(Signal::Panic(Panic::new(
            command_pos.clone(),
            format!("{} expansion resulted in {} items", kind, matches.len()),
        )));
    }
    Ok(matches.into_iter().next().unwrap())
}

fn expand_low(executor: &mut Executor, template: &TemplateR, env: &Env) -> EvalResult<Vec<StageWord>> {
    if template.empty_quoted && template.segments.is_empty() {
        return Ok(Vec::new());
    }
    let mut results = vec![StageWord { bytes: Vec::new(), units: Vec::new(), has_glob: false }];
    let mut first_segment = true;
    for segment in &template.segments {
        let alternatives: Vec<StageWord> = match segment {
            TemplateSegmentR::Literal { bytes, glob } => {
                let mut literal_bytes = bytes.clone();
                let mut units: Vec<PatternUnit> = Vec::new();
                if first_segment && *glob && literal_bytes.starts_with(b"~/") {
                    let home = std::env::var_os("HOME").map(|v| v.as_encoded_bytes().to_vec()).unwrap_or_default();
                    if home.is_empty() {
                        literal_bytes = literal_bytes[2..].to_vec();
                    } else {
                        let mut combined = home.clone();
                        combined.extend_from_slice(&literal_bytes[1..]);
                        literal_bytes = combined;
                    }
                    for byte in &literal_bytes { units.push(PatternUnit::Literal(*byte)); }
                } else {
                    for byte in &literal_bytes {
                        units.push(if *glob && *byte == b'*' { PatternUnit::Star } else if *glob && *byte == b'%' { PatternUnit::Percent } else { PatternUnit::Literal(*byte) });
                    }
                }
                vec![StageWord { has_glob: units.iter().any(|u| matches!(u, PatternUnit::Star | PatternUnit::Percent)), bytes: literal_bytes, units }]
            }
            TemplateSegmentR::Slot { slot, pos, invalid } => {
                if *invalid {
                    vec![StageWord { bytes: Vec::new(), units: Vec::new(), has_glob: false }]
                } else {
                    let value = env.cells.get(*slot).map(|cell| cell.lock().unwrap().clone()).unwrap_or(Value::Nil);
                    match value {
                        Value::Array(items) => {
                            let items = items.lock().unwrap().clone();
                            let mut values = Vec::new();
                            for item in &items {
                                values.push(stage_from_scalar(item, pos)?);
                            }
                            if values.is_empty() { return Ok(Vec::new()); }
                            values
                        }
                        other => vec![stage_from_scalar(&other, pos)?],
                    }
                }
            }
        };
        // Earlier segments vary fastest.
        let mut combined = Vec::new();
        for alternative in &alternatives {
            for existing in &results {
                let mut bytes = existing.bytes.clone();
                bytes.extend_from_slice(&alternative.bytes);
                let mut units = existing.units.clone();
                units.extend(alternative.units.iter().cloned());
                combined.push(StageWord { bytes, units, has_glob: existing.has_glob || alternative.has_glob });
            }
        }
        results = combined;
        first_segment = false;
    }
    Ok(results)
}

fn stage_from_scalar(value: &Value, pos: &SourcePos) -> EvalResult<StageWord> {
    let bytes = match value {
        Value::Nil => Vec::new(),
        Value::Bool(b) => b.to_string().into_bytes(),
        Value::Int(i) => i.to_string().into_bytes(),
        Value::Float(x) => crate::value::format_float(*x).into_bytes(),
        Value::Char(b) => vec![*b],
        Value::Str(bytes) => bytes.clone(),
        _ => {
            return Err(Signal::Panic(Panic::new(
                pos.clone(),
                format!("value ({}) has unexpected type, expected nil, bool, int, float, byte or string", value.display()),
            )));
        }
    };
    let units = bytes.iter().map(|b| PatternUnit::Literal(*b)).collect::<Vec<_>>();
    Ok(StageWord { bytes, units, has_glob: false })
}

fn glob_expand(word: StageWord, command_pos: &SourcePos) -> EvalResult<Vec<Vec<u8>>> {
    if !word.has_glob {
        return Ok(vec![word.bytes]);
    }
    // Validate recursive wildcards.
    {
        let mut components: Vec<Vec<&PatternUnit>> = vec![Vec::new()];
        for unit in &word.units {
            if matches!(unit, PatternUnit::Literal(b'/')) {
                components.push(Vec::new());
            } else {
                components.last_mut().unwrap().push(unit);
            }
        }
        for component in components {
            let stars = component.iter().filter(|u| matches!(u, PatternUnit::Star)).count();
            if stars >= 2 && !(component.len() == 2 && stars == 2) {
                return Err(Signal::Panic(Panic::new(
                    command_pos.clone(),
                    format!("pattern ({}) has invalid UTF-8", crate::source::format_string_literal(&word.bytes)),
                )));
            }
        }
    }

    let absolute = word.bytes.first() == Some(&b'/');
    let mut pattern = String::new();
    if !absolute { pattern.push_str("./"); }
    for unit in &word.units {
        match unit {
            PatternUnit::Star => pattern.push('*'),
            PatternUnit::Percent => pattern.push('?'),
            PatternUnit::Literal(byte) => match byte {
                b'*' => pattern.push_str("[*]"),
                b'?' => pattern.push_str("[?]"),
                b'[' => pattern.push_str("[[]"),
                b']' => pattern.push_str("[]]"),
                b'\\' => pattern.push_str("[\\\\]"),
                _ => pattern.push(*byte as char),
            },
        }
    }
    match glob::glob(&pattern) {
        Ok(paths) => {
            let mut values: Vec<Vec<u8>> = paths.filter_map(|entry| entry.ok()).map(|path| path.as_os_str().as_encoded_bytes().to_vec()).collect();
            values.sort();
            values.dedup();
            Ok(values)
        }
        Err(_) => Err(Signal::Panic(Panic::new(
            command_pos.clone(),
            format!("pattern ({}) has invalid UTF-8", crate::source::format_string_literal(&word.bytes)),
        ))),
    }
}

fn run_pipeline(
    prepared: Vec<PreparedCommand>,
    mode: CommandMode,
    capture: Option<&CaptureContext>,
) -> Vec<Option<Value>> {
    let count = prepared.len();
    let mut children: Vec<Option<std::process::Child>> = Vec::new();
    let mut results: Vec<Option<Value>> = vec![None; count];
    let mut writer_threads: Vec<std::thread::JoinHandle<()>> = Vec::new();
    let mut previous_pipe_read: Option<std::fs::File> = None;

    for (index, command) in prepared.iter().enumerate() {
        if let Some(error) = &command.failure {
            results[index] = Some(error.clone());
        }
        let is_last = index + 1 == count;
        let next_pipe = if is_last { None } else { Some(make_pipe()) };
        let mut next_read = next_pipe.as_ref().map(|(read, _)| clone_file(read));

        if command.failure.is_none() {
            let mut process = std::process::Command::new(std::ffi::OsString::from_vec(command.program.clone()));
            process.args(command.args.iter().map(|arg| std::ffi::OsString::from_vec(arg.clone())));

            // stdin
            match &command.io[0] {
                IoDesc::DefaultIn => {
                    if index == 0 {
                        process.stdin(std::process::Stdio::inherit());
                    } else if let Some(read) = previous_pipe_read.take() {
                        process.stdin(std::process::Stdio::from(read));
                    } else {
                        process.stdin(std::process::Stdio::null());
                    }
                }
                IoDesc::File(file) => {
                    let _ = previous_pipe_read.take();
                    if let Ok(file) = file.try_clone() { process.stdin(std::process::Stdio::from(file)); }
                }
                IoDesc::StringInput(content) => {
                    let _ = previous_pipe_read.take();
                    let (read, mut write) = make_pipe();
                    process.stdin(std::process::Stdio::from(read));
                    let content = content.clone();
                    writer_threads.push(std::thread::spawn(move || {
                        let mut data = content;
                        data.push(b'\n');
                        let _ = write.write_all(&data);
                    }));
                }
                _ => { process.stdin(std::process::Stdio::inherit()); }
            }

            process.stdout(desc_to_stdio(&command.io[1], next_pipe.as_ref(), capture, mode));
            process.stderr(desc_to_stdio(&command.io[2], next_pipe.as_ref(), capture, mode));

            match process.spawn() {
                Ok(child) => children.push(Some(child)),
                Err(error) => {
                    results[index] = Some(command_error(error.to_string().into_bytes(), &command.pos, 127));
                    children.push(None);
                }
            }
        } else {
            children.push(None);
        }

        // Set up the next stage's input.
        if let Some((_, write)) = next_pipe {
            // The original write end is dropped here; children that use the
            // pipe received clones through their stdio.
            drop(write);
        }
        previous_pipe_read = next_read.take();
        if let Some(read) = previous_pipe_read.take() {
            previous_pipe_read = Some(read);
        }
        // Simplify: previous_pipe_read now holds next_read if any.
        if is_last {
            previous_pipe_read = None;
        }
    }

    for (index, child) in children.into_iter().enumerate() {
        if let Some(mut child) = child {
            if let Ok(status) = child.wait() {
                let (status_code, success) = status_info(status);
                if !success && results[index].is_none() {
                    results[index] = Some(command_error(b"command returned non-zero".to_vec(), &prepared[index].pos, status_code));
                }
            }
        }
    }
    for thread in writer_threads { let _ = thread.join(); }
    results
}

fn status_info(status: std::process::ExitStatus) -> (i64, bool) {
    use std::os::unix::process::ExitStatusExt;
    if let Some(code) = status.code() {
        (code as i64, code == 0)
    } else if let Some(signal) = status.signal() {
        (255 + signal as i64, false)
    } else {
        (255, false)
    }
}

fn desc_to_stdio(
    desc: &IoDesc,
    next_pipe: Option<&(std::fs::File, std::fs::File)>,
    capture: Option<&CaptureContext>,
    mode: CommandMode,
) -> std::process::Stdio {
    match desc {
        IoDesc::InitialOut => match mode {
            CommandMode::Capture => capture
                .and_then(|ctx| ctx.out_write.try_clone().ok())
                .map(std::process::Stdio::from)
                .unwrap_or_else(|| std::process::Stdio::inherit()),
            CommandMode::Plain => std::process::Stdio::inherit(),
        },
        IoDesc::InitialErr => match mode {
            CommandMode::Capture => capture
                .and_then(|ctx| ctx.err_write.try_clone().ok())
                .map(std::process::Stdio::from)
                .unwrap_or_else(|| std::process::Stdio::inherit()),
            CommandMode::Plain => std::process::Stdio::inherit(),
        },
        IoDesc::CaptureOut => capture
            .and_then(|ctx| ctx.out_write.try_clone().ok())
            .map(std::process::Stdio::from)
            .unwrap_or_else(|| std::process::Stdio::inherit()),
        IoDesc::CaptureErr => capture
            .and_then(|ctx| ctx.err_write.try_clone().ok())
            .map(std::process::Stdio::from)
            .unwrap_or_else(|| std::process::Stdio::inherit()),
        IoDesc::PipeNext => next_pipe
            .and_then(|(_, write)| write.try_clone().ok())
            .map(std::process::Stdio::from)
            .unwrap_or_else(|| std::process::Stdio::null()),
        IoDesc::File(file) => file
            .try_clone()
            .map(std::process::Stdio::from)
            .unwrap_or_else(|| std::process::Stdio::null()),
        _ => std::process::Stdio::inherit(),
    }
}

fn make_pipe() -> (std::fs::File, std::fs::File) {
    let mut fds = [0i32; 2];
    unsafe {
        libc::pipe2(fds.as_mut_ptr(), libc::O_CLOEXEC);
        (
            std::fs::File::from_raw_fd(fds[0]),
            std::fs::File::from_raw_fd(fds[1]),
        )
    }
}

fn clone_file(file: &std::fs::File) -> std::fs::File {
    file.try_clone().unwrap()
}
EOF
"}

