        let bytes = arg.as_encoded_bytes();
        if positional_started {
            positional.push(arg.clone());
            continue;
        }
        if bytes == b"--" {
            positional_started = true;
            continue;
        }
        if bytes.starts_with(b"--") && bytes.len() > 2 {
            // Long flag, possibly --name=value.
            let after = &bytes[2..];
            if after.first() == Some(&b'-') {
                // e.g. --- : reported as '--' by the original parser.
                return cli_unknown(&bin, "--", &counts);
            }
            if std::str::from_utf8(after).is_err() {
                clap_invalid_utf8();
            }
            let name_end = after.iter().position(|b| *b == b'=').unwrap_or(after.len());
            let name = std::str::from_utf8(&after[..name_end]).unwrap_or("");
            match name {
                "help" => {
                    print!("{}", help_text(&bin));
                    return CliOutcome::Exit(0);
                }
                "version" => {
                    println!("Hush 0.1.4");
                    return CliOutcome::Exit(0);
                }
                "ast" => { flags.ast = true; counts.push("ast"); }
                "check" => { flags.check = true; counts.push("check"); }
                "lex" => { flags.lex = true; counts.push("lex"); }
                "program" => { flags.program = true; counts.push("program"); }
                _ => {
                    let suggestion = did_you_mean(name);
                    return cli_unknown_long(&bin, name, suggestion, &counts);
                }
            }
            continue;
        }
        if bytes.starts_with(b"-") && bytes.len() > 1 {
            // Short flag cluster.
            let mut index = 1;
            let mut unknown: Option<u8> = None;
            while index < bytes.len() {
                let byte = bytes[index];
                if byte == b'h' {
                    print!("{}", help_text(&bin));
                    return CliOutcome::Exit(0);
                }
                if byte == b'V' {
                    println!("Hush 0.1.4");
                    return CliOutcome::Exit(0);
                }
                if byte > 0x7f {
                    clap_invalid_utf8();
                }
                unknown = Some(byte);
                break;
            }
            if let Some(byte) = unknown {
                let displayed = format!("-{}", byte as char);
                return cli_unknown(&bin, &displayed, &counts);
            }
            continue;
        }
        positional_started = true;
        positional.push(arg.clone());
    }

    // Duplicate flag detection: the first repeated flag.
    let mut seen: Vec<&'static str> = Vec::new();
    for name in &counts {
        if seen.contains(name) {
            let mut usage_flags: Vec<&'static str> = seen.clone();
            if !usage_flags.contains(name) { usage_flags.push(name); }
            // Usage lists every distinct flag that was supplied, in the
            // canonical order ast, check, lex, program.
            let mut all: Vec<&'static str> = Vec::new();
            for candidate in ["ast", "check", "lex", "program"] {
                if counts.iter().any(|item| *item == candidate) { all.push(candidate); }
            }
            let _ = usage_flags;
            eprintln!(
                "error: The argument '--{}' was provided more than once, but cannot be used multiple times\n\nUSAGE:\n    {} {}\n\nFor more information try --help",
                name,
                bin,
                all.iter().map(|flag| format!("--{}", flag)).collect::<Vec<_>>().join(" ")
            );
            return CliOutcome::Exit(1);
        }
        seen.push(name);
    }

    CliOutcome::Run { flags, positional, bin }
}

fn cli_unknown(bin: &str, displayed: &str, counts: &[&'static str]) -> CliOutcome {
    let usage = usage_for(counts);
    eprintln!(
        "error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    {} {}\n\nFor more information try --help",
        displayed, bin, usage
    );
    CliOutcome::Exit(1)
}

fn cli_unknown_long(bin: &str, name: &str, suggestion: Option<&'static str>, counts: &[&'static str]) -> CliOutcome {
    let mut out = format!(
        "error: Found argument '--{}' which wasn't expected, or isn't valid in this context\n",
        name
    );
    let usage;
    if let Some(suggestion) = suggestion {
        out.push_str(&format!("\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{}\x1b[0m?\n", suggestion));
        usage = format!("--{}", suggestion);
    } else {
        usage = usage_for(counts);
    }
    out.push_str(&format!("\nUSAGE:\n    {} {}\n\nFor more information try --help\n", bin, usage));
    eprint!("{}", out);
    CliOutcome::Exit(1)
}

fn usage_for(counts: &[&'static str]) -> String {
    let mut all: Vec<&'static str> = Vec::new();
    for candidate in ["ast", "check", "lex", "program"] {
        if counts.iter().any(|item| *item == candidate) { all.push(candidate); }
    }
    if all.is_empty() {
        "[FLAGS] [arguments]...".to_string()
    } else {
        all.iter().map(|flag| format!("--{}", flag)).collect::<Vec<_>>().join(" ")
    }
}

fn clap_invalid_utf8() -> ! {
    eprintln!(
        "\nthread 'main' ({}) panicked at /usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap-2.33.3/src/app/parser.rs:1685:46:\nunexpected invalid UTF-8 code point\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace",
        std::process::id()
    );
    std::process::exit(101);
}

fn did_you_mean(name: &str) -> Option<&'static str> {
    let candidates = ["ast", "check", "lex", "program", "help", "version"];
    let mut best: Option<(&'static str, f64)> = None;
    for candidate in candidates {
        let score = jaro_winkler(name, candidate);
        if score > 0.8 {
            if best.map(|(_, current)| score > current).unwrap_or(true) {
                best = Some((candidate, score));
            }
        }
    }
    best.map(|(candidate, _)| candidate)
}

fn jaro(s1: &str, s2: &str) -> f64 {
    let a: Vec<char> = s1.chars().collect();
    let b: Vec<char> = s2.chars().collect();
    if a.is_empty() && b.is_empty() { return 1.0; }
    if a.is_empty() || b.is_empty() { return 0.0; }
    let max_len = a.len().max(b.len());
    let search_range = max_len / 2;
    let search_range = search_range.saturating_sub(1);
    let mut b_matched = vec![false; b.len()];
    let mut matches = 0usize;
    for (i, ca) in a.iter().enumerate() {
        let start = i.saturating_sub(search_range);
        let end = (i + search_range + 1).min(b.len());
        for j in start..end {
            if !b_matched[j] && *ca == b[j] {
                b_matched[j] = true;
                matches += 1;
                break;
            }
        }
    }
    if matches == 0 { return 0.0; }
    let mut transpositions = 0usize;
    let mut j = 0usize;
    for (i, ca) in a.iter().enumerate() {
        // Count matched characters in order.
        let _ = (i, ca, j);
        break;
    }
    // Standard transposition count.
    let mut matched_a: Vec<char> = Vec::new();
    let mut matched_b: Vec<char> = Vec::new();
    {
        let mut b_matched2 = vec![false; b.len()];
        for (i, ca) in a.iter().enumerate() {
            let start = i.saturating_sub(search_range);
            let end = (i + search_range + 1).min(b.len());
            for jj in start..end {
                if !b_matched2[jj] && *ca == b[jj] {
                    b_matched2[jj] = true;
                    matched_a.push(*ca);
                    break;
                }
            }
        }
        let mut idx = 0usize;
        for jj in 0..b.len() {
            if b_matched2[jj] {
                if idx < matched_a.len() { matched_b.push(b[jj]); }
                idx += 1;
            }
        }
        for k in 0..matched_a.len().min(matched_b.len()) {
            if matched_a[k] != matched_b[k] { transpositions += 1; }
        }
    }
    let _ = j;
    let m = matches as f64;
    (m / a.len() as f64 + m / b.len() as f64 + (m - (transpositions / 2) as f64) / m) / 3.0
}

fn jaro_winkler(s1: &str, s2: &str) -> f64 {
    let j = jaro(s1, s2);
    let prefix = s1.chars().zip(s2.chars()).take_while(|(a, b)| a == b).take(4).count();
    j + prefix as f64 * 0.1 * (1.0 - j)
}

fn run(flags: CliFlags, positional: Vec<std::ffi::OsString>) -> i32 {
    // Select the script source.
    let mut source_name: String;
    let mut source_data: Vec<u8>;
    let script_args_os: Vec<std::ffi::OsString>;

    let first = positional.first().cloned();
    let use_stdin_script = match &first {
        Some(path) if path.as_encoded_bytes() == b"-" => true,
        _ => false,
    };

    if let Some(first_path) = first.clone() {
        if use_stdin_script {
            source_name = "<stdin>".to_string();
            source_data = read_all_stdin();
            script_args_os = positional.iter().skip(1).cloned().collect();
        } else if std::path::Path::new(&first_path).is_file() {
            source_name = first_path.to_string_lossy().into_owned();
            match std::fs::read(&first_path) {
                Ok(data) => {
                    source_data = data;
                    script_args_os = positional.iter().skip(1).cloned().collect();
                }
                Err(error) => {
                    let pos = source::SourcePos::new(Rc::new(source_name.clone()), 0, 0);
                    eprintln!("Panic in {}: {}", pos, error);
                    return 127;
                }
            }
        } else {
            source_name = "<stdin>".to_string();
            source_data = read_all_stdin();
            script_args_os = positional.clone();
        }
    } else {
        source_name = "<stdin>".to_string();
        source_data = read_all_stdin();
        script_args_os = Vec::new();
    }

    let script_args: Vec<Vec<u8>> = script_args_os
        .iter()
        .map(|arg| arg.to_string_lossy().into_owned().into_bytes())
        .collect();

    let source_rc = Rc::new(source_name.clone());
    let (tokens, lex_errors, lex_items) = Lexer::new(source_data, source_rc.clone()).lex();
    let mut parser = Parser::new(tokens, source_rc.clone());
    let ast = parser.parse_program();

    let mut syntax_errors: Vec<ErrorItem> = lex_errors;
    syntax_errors.extend(parser.errors.iter().cloned());

    // Syntax errors are reported before the debug listings.
    if !syntax_errors.is_empty() {
        print_errors(&syntax_errors);
    }

    if flags.lex {
        let mut out = String::new();
        out.push_str("--------------------------------------------------\n");
        for item in &lex_items {
            match item {
                LexItem::Token(token) => {
                    out.push_str(&format!("{}:\t{}\n", token.pos, token.display()));
                }
                LexItem::Error(error) => match &error.pos {
                    Some(pos) => out.push_str(&format!("Error: line {}, column {} - {}\n", pos.line, pos.column, error.message)),
                    None => out.push_str(&format!("Error: {}\n", error.message)),
                },
            }
        }
        out.push_str("--------------------------------------------------\n");
        print!("{}", out);
    }

    if flags.ast {
        println!("--------------------------------------------------");
        println!("AST for {}", source_name);
        println!("{}", print::print_program(&ast));
        println!("--------------------------------------------------");
    }

    let mut resolver = Resolver::new();
    let program = resolver.resolve_program(&ast);
    if !resolver.errors.is_empty() {
        print_errors(&resolver.errors);
        return 2;
    }

    if flags.program {
        println!("--------------------------------------------------");
        println!("Program for {}", source_name);
        println!("{}", print::print_resolved_program(&program));
        println!("--------------------------------------------------");
    }

    if !syntax_errors.is_empty() {
        return 2;
    }
    if flags.check {
        return 0;
    }

    let runtime = Arc::new(Runtime::new(script_args));
    let mut executor = Executor::new(runtime);
    match executor.execute_program(&program, source_rc.clone()) {
        Ok(_) => 0,
        Err(Signal::Exit(code)) => code,
        Err(Signal::Panic(panic)) => {
            eprintln!("{}", panic.format());
            127
        }
        Err(_) => 0,
    }
}

fn print_errors(errors: &[ErrorItem]) {
    for error in errors {
        eprint!("{}", error.format_main());
    }
    let _ = std::io::stderr().flush();
}

fn read_all_stdin() -> Vec<u8> {
    let mut data = Vec::new();
    let _ = std::io::stdin().lock().read_to_end(&mut data);
    data
}
