{"command":"cat >> src/print.rs <<'EOF'

pub fn contains_ill_formed(block: &Block) -> bool {
    block.iter().any(stmt_ill_formed)
}

fn stmt_ill_formed(stmt: &Statement) -> bool {
    match stmt {
        Statement::IllFormed => true,
        Statement::Let { init, .. } => init.as_ref().map(expr_ill_formed).unwrap_or(false),
        Statement::Assign { target, value, .. } => expr_ill_formed(target) || expr_ill_formed(value),
        Statement::Expr(expr) => expr_ill_formed(expr),
        Statement::Return(expr, _) => expr.as_ref().map(expr_ill_formed).unwrap_or(false),
        Statement::Break(_) => false,
        Statement::For { iter, body, .. } => expr_ill_formed(iter) || body.iter().any(stmt_ill_formed),
        Statement::While { cond, body, .. } => expr_ill_formed(cond) || body.iter().any(stmt_ill_formed),
    }
}

fn expr_ill_formed(expr: &Expr) -> bool {
    match &expr.kind {
        ExprKind::IllFormed => true,
        ExprKind::Array(items) => items.iter().any(expr_ill_formed),
        ExprKind::Dict(pairs) => pairs.iter().any(|pair| expr_ill_formed(&pair.value)),
        ExprKind::Function(fun) => fun.body.iter().any(stmt_ill_formed),
        ExprKind::If(if_expr) => {
            expr_ill_formed(&if_expr.cond)
                || if_expr.then_block.iter().any(stmt_ill_formed)
                || if_expr.else_block.as_ref().map(|block| block.iter().any(stmt_ill_formed)).unwrap_or(false)
        }
        ExprKind::Command(block) => {
            block.ill_formed_block
                || block.pipelines.iter().any(|pipeline| {
                    pipeline.ill_formed
                        || pipeline.commands.iter().any(|command| {
                            command.ill_formed_program
                                || command.redirects.iter().any(|redirect| matches!(redirect.target, RedirectTarget::IllFormed))
                        })
                })
        }
        ExprKind::Unary(_, inner) => expr_ill_formed(inner),
        ExprKind::Binary(_, left, right, _) => expr_ill_formed(left) || expr_ill_formed(right),
        ExprKind::Call(callee, args, _) => expr_ill_formed(callee) || args.iter().any(expr_ill_formed),
        ExprKind::Try(inner, _) => expr_ill_formed(inner),
        ExprKind::Index(base, index) => expr_ill_formed(base) || expr_ill_formed(index),
        ExprKind::Field(base, ..) => expr_ill_formed(base),
        _ => false,
    }
}
