new='''fn split_bytes(bytes: &[u8], pattern: &[u8]) -> Vec<Vec<u8>> {
    if pattern.is_empty() {
        let mut pieces = vec![Vec::new()];
        for byte in bytes {
            pieces.push(vec![*byte]);
        }
        pieces.push(Vec::new());
        return pieces;
    }
    let mut pieces = Vec::new();
    let mut start = 0usize;
    let mut index = 0usize;
    while index + pattern.len() <= bytes.len() {
        if &bytes[index..index + pattern.len()] == pattern {
            pieces.push(bytes[start..index].to_vec());
            index += pattern.len();
            start = index;
        } else {
            index += 1;
        }
    }
    pieces.push(bytes[start..].to_vec());
    pieces
}

fn replace_bytes(bytes: &[u8], from: &[u8], to: &[u8]) -> Vec<u8> {
    if from.is_empty() {
        let mut out = Vec::new();
        out.extend_from_slice(to);
        for byte in bytes {
            out.push(*byte);
            out.extend_from_slice(to);
        }
        return out;
    }
    let mut out = Vec::new();
    let mut index = 0usize;
    while index < bytes.len() {
        if index + from.len() <= bytes.len() && &bytes[index..index + from.len()] == from {
            out.extend_from_slice(to);
            index += from.len();
        } else {
            out.push(bytes[index]);
            index += 1;
        }
    }
    out
}

