new='''fn json_float_format(value: f64) -> String {
    if value == 0.0 {
        return if value.is_sign_negative() { "-0.0".to_string() } else { "0.0".to_string() };
    }
    let scientific = format!("{:e}", value);
    let (mantissa, exponent_text) = scientific.split_once('e').unwrap_or((scientific.as_str(), "0"));
    let exponent: i32 = exponent_text.parse().unwrap_or(0);
    let negative = mantissa.starts_with('-');
    let digits_raw: String = mantissa.chars().filter(|c| c.is_ascii_digit()).collect();
    let digits = digits_raw.trim_end_matches('0');
    let digits = if digits.is_empty() { "0" } else { digits };
    let sign = if negative { "-" } else { "" };
    if (-5..=15).contains(&exponent) {
        if exponent >= 0 {
            let integer_len = (exponent + 1) as usize;
            if digits.len() <= integer_len {
                format!("{}{}.0", sign, digits.pad_to_width(integer_len))
            } else {
                format!("{}{}.{}", sign, &digits[..integer_len], &digits[integer_len..])
            }
        } else {
            let zeros = (-exponent - 1) as usize;
            format!("{}0.{}{}", sign, "0".repeat(zeros), digits)
        }
    } else if digits.len() == 1 {
        format!("{}{}e{}", sign, digits, exponent)
    } else {
        format!("{}{}.{}e{}", sign, &digits[..1], &digits[1..], exponent)
    }
}

